INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('25675e4b-995b-4db1-aadc-ebabbf3fe810', '句 二', '句 二', '3fef2451-3384-4e62-9fb2-2e1e3fb62673', '唐', '["樹蔭逢歇馬，魚潭見洗船。"]', '["樹蔭逢歇马，鱼潭见洗船。"]', '诗', 'shi', '', NULL, '句 二 無名氏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6b77be7f-c920-42a6-ae1b-16b1a4b08f19', '句 三', '句 三', '3fef2451-3384-4e62-9fb2-2e1e3fb62673', '唐', '["隔花遙勸酒，就水更移床。","（以上均爲文贅詩）。"]', '["隔花遙勸酒，就水更移床。","（以上均爲文贅诗）。"]', '诗', 'shi', '', NULL, '句 三 無名氏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('885d0dbf-f0a9-44a2-968e-0235d55341e0', '相反詩', '相反诗', '3fef2451-3384-4e62-9fb2-2e1e3fb62673', '唐', '["晴雲開極野，積霧掩長洲。","。"]', '["晴云开極野，積霧掩长洲。","。"]', '诗', 'shi', '', NULL, '相反詩 無名氏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('38243641-3857-47b6-b0ca-b619813d81c8', '相重詩', '相重诗', '3fef2451-3384-4e62-9fb2-2e1e3fb62673', '唐', '["驅馬清渭濱，飛鑣犯夕塵。","川波張遠蓋，山日下遙輪。","柳葉眉行盡，桃花騎轉新。","（自《平頭詩》以下二十八題均見《文鏡秘府論》西卷《文二十八種病》）（按：《文二十八種病》節，爲弘法大師綜合劉善經、元兢、崔融及《文筆式》等諸家之說而成。","所引作品，可考知者有六朝及初唐人之作，多數爲作者無考之佚詩佚句。","今將可考知出某家著作所引者另錄，餘皆附於此，雖難定時代，爲六朝至初唐人作則無問題。","）。"]', '["驱马清渭濱，飞鑣犯夕塵。","川波張远蓋，山日下遙輪。","柳葉眉行尽，桃花騎轉新。","（自《平头诗》以下二十八題均见《文镜秘府論》西卷《文二十八種病》）（按：《文二十八種病》節，爲弘法大師綜合劉善經、元兢、崔融及《文笔式》等諸家之说而成。","所引作品，可考知者有六朝及初唐人之作，多數爲作者無考之佚诗佚句。","今將可考知出某家著作所引者另錄，餘皆附於此，雖难定时代，爲六朝至初唐人作則無问題。","）。"]', '诗', 'shi', '', NULL, '相重詩 無名氏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('043b3f44-be78-492d-ba8a-3c7b17f6a8cc', '的名對詩 一', '的名对诗 一', '3fef2451-3384-4e62-9fb2-2e1e3fb62673', '唐', '["東圃青梅發，西園綠草開。","砌下花徐去，階前絮緩來。"]', '["东圃青梅發，西园綠草开。","砌下花徐去，階前絮緩来。"]', '诗', 'shi', '', NULL, '的名對詩 一 無名氏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8ba5cf7d-9baa-439e-aa94-e03d9c3b0c59', '的名對詩 二', '的名对诗 二', '3fef2451-3384-4e62-9fb2-2e1e3fb62673', '唐', '["手披黃卷盡，目送白雲征。","玉霜摧草色，金風斷雁聲。","片雲愁近戍，半月隱遙城。"]', '["手披黄卷尽，目送白云征。","玉霜摧草色，金风斷雁声。","片云愁近戍，半月隐遙城。"]', '诗', 'shi', '', NULL, '的名對詩 二 無名氏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1600b923-6505-49c0-ae15-472e56194bdb', '的名對詩 三', '的名对诗 三', '3fef2451-3384-4e62-9fb2-2e1e3fb62673', '唐', '["鮮光葉上動，艷彩花中出。","疏桐映蘭閣，密柳蓋荷池。"]', '["鲜光葉上动，艷彩花中出。","疏桐映蘭閣，密柳蓋荷池。"]', '诗', 'shi', '', NULL, '的名對詩 三 無名氏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2459c3d8-9248-4c38-aa3e-b743bf8ffb67', '隔句對詩 一', '隔句对诗 一', '3fef2451-3384-4e62-9fb2-2e1e3fb62673', '唐', '["昨夜越溪難，含悲赴上蘭。","今朝逾嶺易，抱笑入長安。"]', '["昨夜越溪难，含悲赴上蘭。","今朝逾嶺易，抱笑入长安。"]', '诗', 'shi', '', NULL, '隔句對詩 一 無名氏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('578ab26a-89aa-4a2b-a6b5-bf246e302f75', '隔句對詩 二', '隔句对诗 二', '3fef2451-3384-4e62-9fb2-2e1e3fb62673', '唐', '["月映茱萸錦，艷起桃花頰。","風發蒲桃秀，香生雲母帖。"]', '["月映茱萸錦，艷起桃花頰。","风發蒲桃秀，香生云母帖。"]', '诗', 'shi', '', NULL, '隔句對詩 二 無名氏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('995f2d43-9ab3-4aeb-9cbe-bfd5b9ceb729', '隔句對詩 三', '隔句对诗 三', '3fef2451-3384-4e62-9fb2-2e1e3fb62673', '唐', '["翠苑翠峰外，單蜂拾蘂歸。","芳園芳樹裏，雙燕歷花飛。"]', '["翠苑翠峰外，單蜂拾蘂归。","芳园芳樹裏，雙燕歷花飞。"]', '诗', 'shi', '', NULL, '隔句對詩 三 無名氏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8b5e3a9c-1642-4d68-8c68-5e7c5825b3ef', '雙擬對詩 一', '雙擬对诗 一', '3fef2451-3384-4e62-9fb2-2e1e3fb62673', '唐', '["夏暑夏不衰，秋陰秋未歸。","炎至炎難却，涼消涼易追。","。"]', '["夏暑夏不衰，秋陰秋未归。","炎至炎难却，涼消涼易追。","。"]', '诗', 'shi', '', NULL, '雙擬對詩 一 無名氏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('84d31dd4-99b3-4ec3-af25-cb5c075f6286', '雙擬對詩 二', '雙擬对诗 二', '3fef2451-3384-4e62-9fb2-2e1e3fb62673', '唐', '["乍行乍理髮，或笑或看衣。"]', '["乍行乍理髮，或笑或看衣。"]', '诗', 'shi', '', NULL, '雙擬對詩 二 無名氏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('271f5b41-1538-4b08-b908-a7c1ef454794', '雙擬對詩 三', '雙擬对诗 三', '3fef2451-3384-4e62-9fb2-2e1e3fb62673', '唐', '["結萼結花九，飛嵐飛葉始。"]', '["結萼結花九，飞嵐飞葉始。"]', '诗', 'shi', '', NULL, '雙擬對詩 三 無名氏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3e938bd4-e1c6-416c-a2f2-5a37c654169b', '聯綿對詩 一', '聯綿对诗 一', '3fef2451-3384-4e62-9fb2-2e1e3fb62673', '唐', '["看山山已峻，望水水仍清。","聽蟬蟬響急，思鄉鄉別情。"]', '["看山山已峻，望水水仍清。","听蟬蟬响急，思乡乡別情。"]', '诗', 'shi', '', NULL, '聯綿對詩 一 無名氏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('fb153457-ea9c-48b9-8ad7-5f6dbc21721a', '聯綿對詩 二', '聯綿对诗 二', '3fef2451-3384-4e62-9fb2-2e1e3fb62673', '唐', '["嫩荷荷似頰，淺河河似帶，初月月似眉。"]', '["嫩荷荷似頰，淺河河似带，初月月似眉。"]', '诗', 'shi', '', NULL, '聯綿對詩 二 無名氏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e79d4560-e17a-4554-be3f-2a8d355acf0d', '聯綿對詩 三', '聯綿对诗 三', '3fef2451-3384-4e62-9fb2-2e1e3fb62673', '唐', '["煙離離萬代，雨絕絕千年。"]', '["煙離離万代，雨絕絕千年。"]', '诗', 'shi', '', NULL, '聯綿對詩 三 無名氏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ad61b90c-ff6c-4af0-9c20-42ed9fb08094', '聯綿對詩 四', '聯綿对诗 四', '3fef2451-3384-4e62-9fb2-2e1e3fb62673', '唐', '["望日日已晚，懷人人不歸。"]', '["望日日已晚，懷人人不归。"]', '诗', 'shi', '', NULL, '聯綿對詩 四 無名氏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d53b3604-4500-4774-80cf-e9738dea69eb', '聯綿對詩 五', '聯綿对诗 五', '3fef2451-3384-4e62-9fb2-2e1e3fb62673', '唐', '["霏霏歛夕霧，赫赫吐晨曦。","軒軒多秀氣，奕奕有光儀。"]', '["霏霏歛夕霧，赫赫吐晨曦。","軒軒多秀氣，奕奕有光儀。"]', '诗', 'shi', '', NULL, '聯綿對詩 五 無名氏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('51e397d6-b162-4dcc-8449-44ac66f1828c', '聯綿對詩 六', '聯綿对诗 六', '3fef2451-3384-4e62-9fb2-2e1e3fb62673', '唐', '["視日日將晚，望雲雲漸積。"]', '["視日日將晚，望云云漸積。"]', '诗', 'shi', '', NULL, '聯綿對詩 六 無名氏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('bd1471a6-32ee-436b-8ab3-0ff1012d840c', '互成對詩 一', '互成对诗 一', '3fef2451-3384-4e62-9fb2-2e1e3fb62673', '唐', '["天地心間靜，日月眼中明。","麟鳳千年貴，金銀一代榮。"]', '["天地心间静，日月眼中明。","麟鳳千年貴，金銀一代榮。"]', '诗', 'shi', '', NULL, '互成對詩 一 無名氏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('cd0e8a04-7ad4-44c1-9433-a7f137a8e496', '互成對詩 二', '互成对诗 二', '3fef2451-3384-4e62-9fb2-2e1e3fb62673', '唐', '["玉釵丹翠纏，象榻金銀鏤。","青㫙丹碧度，輕霧歷簷飛。"]', '["玉釵丹翠纏，象榻金銀鏤。","青㫙丹碧度，轻霧歷簷飞。"]', '诗', 'shi', '', NULL, '互成對詩 二 無名氏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2f71c53e-7bb6-46ed-b7a3-670d9173c804', '互成對詩 三', '互成对诗 三', '3fef2451-3384-4e62-9fb2-2e1e3fb62673', '唐', '["歲時傷道路，親友念東西。"]', '["歲时傷道路，親友念东西。"]', '诗', 'shi', '', NULL, '互成對詩 三 無名氏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0cb7439d-27ac-4f4a-95f8-5e4206b002b5', '異類對詩 一', '異類对诗 一', '3fef2451-3384-4e62-9fb2-2e1e3fb62673', '唐', '["天清時雲外，山峻紫微中。","鳥飛隨去影，花落逐搖風。"]', '["天清时云外，山峻紫微中。","鸟飞隨去影，花落逐搖风。"]', '诗', 'shi', '', NULL, '異類對詩 一 無名氏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5f0a15dd-5915-4999-a6b0-6fea8240498d', '異類對詩 二', '異類对诗 二', '3fef2451-3384-4e62-9fb2-2e1e3fb62673', '唐', '["鯉躍排荷戲，燕舞拂泥飛。","琴上丹花拂，酒側黃鸝度。","。"]', '["鯉躍排荷戲，燕舞拂泥飞。","琴上丹花拂，酒側黄鸝度。","。"]', '诗', 'shi', '', NULL, '異類對詩 二 無名氏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('81ce3a94-de36-4070-a426-cbabd1b6272f', '賦體對詩 一', '賦體对诗 一', '3fef2451-3384-4e62-9fb2-2e1e3fb62673', '唐', '["褭褭樹驚風，麗麗雲蔽月。"]', '["褭褭樹驚风，丽丽云蔽月。"]', '诗', 'shi', '', NULL, '賦體對詩 一 無名氏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e0181a8f-c786-4a0c-b848-3b94773e7371', '賦體對詩 二', '賦體对诗 二', '3fef2451-3384-4e62-9fb2-2e1e3fb62673', '唐', '["皎皎夜蟬鳴，曬曬曉光發。","（二聯爲句首重字）。"]', '["皎皎夜蟬鳴，曬曬晓光發。","（二聯爲句首重字）。"]', '诗', 'shi', '', NULL, '賦體對詩 二 無名氏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d85c24e0-08e9-4825-9bb9-9b3529359bac', '賦體對詩 三', '賦體对诗 三', '3fef2451-3384-4e62-9fb2-2e1e3fb62673', '唐', '["漢月朝朝暗，胡風夜夜寒。","（句腹重字）。"]', '["漢月朝朝暗，胡风夜夜寒。","（句腹重字）。"]', '诗', 'shi', '', NULL, '賦體對詩 三 無名氏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2ca4f9be-f93d-4ac2-b9c9-b9382037a441', '賦體對詩 四', '賦體对诗 四', '3fef2451-3384-4e62-9fb2-2e1e3fb62673', '唐', '["月蔽雲曬曬，風驚樹褭褭。","（句尾重字）。"]', '["月蔽云曬曬，风驚樹褭褭。","（句尾重字）。"]', '诗', 'shi', '', NULL, '賦體對詩 四 無名氏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8c93cb16-22fc-4c2b-8b6a-cec7984fa6c4', '賦體對詩 五', '賦體对诗 五', '3fef2451-3384-4e62-9fb2-2e1e3fb62673', '唐', '["徘徊四顧望，悵悢獨心愁。","（句首疊韻）。"]', '["徘徊四顧望，悵悢独心愁。","（句首叠韻）。"]', '诗', 'shi', '', NULL, '賦體對詩 五 無名氏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7cf8ca53-116f-444e-96ad-aec3068da345', '賦體對詩 六', '賦體对诗 六', '3fef2451-3384-4e62-9fb2-2e1e3fb62673', '唐', '["君赴燕然戍，妾坐逍遙樓。","（句腹疊韻）。"]', '["君赴燕然戍，妾坐逍遙楼。","（句腹叠韻）。"]', '诗', 'shi', '', NULL, '賦體對詩 六 無名氏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4f74fd01-185a-4b77-bcab-4cde6b8f2598', '賦體對詩 七', '賦體对诗 七', '3fef2451-3384-4e62-9fb2-2e1e3fb62673', '唐', '["疏雲雨滴瀝，薄霧樹朦朧。","（句尾疊韻）。"]', '["疏云雨滴瀝，薄霧樹朦朧。","（句尾叠韻）。"]', '诗', 'shi', '', NULL, '賦體對詩 七 無名氏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e0af3c61-83a6-4b7e-8d4f-a5552e1cf18e', '賦體對詩 八', '賦體对诗 八', '3fef2451-3384-4e62-9fb2-2e1e3fb62673', '唐', '["留連千里賓，留待一年春。","（句首雙聲）。"]', '["留連千里賓，留待一年春。","（句首雙声）。"]', '诗', 'shi', '', NULL, '賦體對詩 八 無名氏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0174d813-84db-41cb-b804-038a7d755164', '賦體對詩 九', '賦體对诗 九', '3fef2451-3384-4e62-9fb2-2e1e3fb62673', '唐', '["我陟崎嶇嶺，君行嶢崅山。","（句腹雙聲）。"]', '["我陟崎嶇嶺，君行嶢崅山。","（句腹雙声）。"]', '诗', 'shi', '', NULL, '賦體對詩 九 無名氏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('87fa38ce-a707-4f27-8e62-23d2027cbc32', '賦體對詩 十', '賦體对诗 十', '3fef2451-3384-4e62-9fb2-2e1e3fb62673', '唐', '["妾意逐行雲，君身入暮門。","（句尾雙聲）。"]', '["妾意逐行云，君身入暮门。","（句尾雙声）。"]', '诗', 'shi', '', NULL, '賦體對詩 十 無名氏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e2f9f1f8-9938-4bc1-b35f-af084b90eb2e', '賦體對詩 十一', '賦體对诗 十一', '3fef2451-3384-4e62-9fb2-2e1e3fb62673', '唐', '["團團月掛嶺，納納（《文鏡秘府論校注》引日本密僧伽維寶《文鏡秘府論箋》云：「『納』疑當作『細』。","」）露沾衣。","（頭）。"]', '["團團月掛嶺，納納（《文镜秘府論校注》引日本密僧伽維寶《文镜秘府論箋》云：「『納』疑當作『細』。","」）露沾衣。","（头）。"]', '诗', 'shi', '', NULL, '賦體對詩 十一 無名氏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('658f3430-4bec-45ec-8145-3d6a7f6d8b81', '賦體對詩 十二', '賦體对诗 十二', '3fef2451-3384-4e62-9fb2-2e1e3fb62673', '唐', '["花承滴滴露，風垂褭褭衣。","（腹）。"]', '["花承滴滴露，风垂褭褭衣。","（腹）。"]', '诗', 'shi', '', NULL, '賦體對詩 十二 無名氏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4408bd4a-1e53-4190-8994-05b0871d5c26', '賦體對詩 十三', '賦體对诗 十三', '3fef2451-3384-4e62-9fb2-2e1e3fb62673', '唐', '["山風晚習習，水浪魚淫淫。","（尾）。"]', '["山风晚習習，水浪鱼淫淫。","（尾）。"]', '诗', 'shi', '', NULL, '賦體對詩 十三 無名氏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('aad162d5-9649-4503-8a57-bb10fe4f799c', '雙聲對詩 一', '雙声对诗 一', '3fef2451-3384-4e62-9fb2-2e1e3fb62673', '唐', '["飋䫻歲陰曉，皎潔寒流清。","結交一顧重，然諾百金香。","。"]', '["飋䫻歲陰晓，皎潔寒流清。","結交一顧重，然諾百金香。","。"]', '诗', 'shi', '', NULL, '雙聲對詩 一 無名氏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('df8cadb0-d2b5-49b3-8add-aec7605a8ce5', '雙聲對詩 二', '雙声对诗 二', '3fef2451-3384-4e62-9fb2-2e1e3fb62673', '唐', '["五章紛冉弱，三冬粲陸離。","悵望一途阻，參差百慮違。"]', '["五章紛冉弱，三冬粲陸離。","悵望一途阻，參差百慮違。"]', '诗', 'shi', '', NULL, '雙聲對詩 二 無名氏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3955b64a-ee48-4fcf-8b3d-ac5ffb40eae9', '雙聲對詩 三', '雙声对诗 三', '3fef2451-3384-4e62-9fb2-2e1e3fb62673', '唐', '["洲渚遞縈映，樹石相因依。"]', '["洲渚遞縈映，樹石相因依。"]', '诗', 'shi', '', NULL, '雙聲對詩 三 無名氏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0b27711f-8b49-46bd-b2e0-cedcf93f983d', '疊韻對詩 一', '叠韻对诗 一', '3fef2451-3384-4e62-9fb2-2e1e3fb62673', '唐', '["放暢千般意，逍遙一個心。","潄流還枕石，步月復彈琴。"]', '["放暢千般意，逍遙一個心。","潄流還枕石，步月复彈琴。"]', '诗', 'shi', '', NULL, '疊韻對詩 一 無名氏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('953717b3-1fe2-453c-831c-3195f368c60f', '疊韻對詩 二', '叠韻对诗 二', '3fef2451-3384-4e62-9fb2-2e1e3fb62673', '唐', '["徘徊夜月滿，肅穆曉風清。","此時一罇酒，無君徒自盈。"]', '["徘徊夜月满，肅穆晓风清。","此时一罇酒，無君徒自盈。"]', '诗', 'shi', '', NULL, '疊韻對詩 二 無名氏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('715f7043-3587-46a1-b936-4020aec1f157', '迴文對詩', '迴文对诗', '3fef2451-3384-4e62-9fb2-2e1e3fb62673', '唐', '["情親由得意，得意遂情親。","新情終會故，會故亦經新。","（自《的名對詩》以下十題均出《文鏡秘府論》東卷《二十九種對》）。"]', '["情親由得意，得意遂情親。","新情終會故，會故亦經新。","（自《的名对诗》以下十題均出《文镜秘府論》东卷《二十九種对》）。"]', '诗', 'shi', '', NULL, '迴文對詩 無名氏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('88b4fb28-0a22-4b3c-8bdb-e72a2e2905d5', '詩', '诗', '3fef2451-3384-4e62-9fb2-2e1e3fb62673', '唐', '["淨宮鄰博望，香剎對承華。","（見《文鏡秘府論》地卷《十四例》引皎公《詩議》引）。"]', '["淨宮鄰博望，香剎对承华。","（见《文镜秘府論》地卷《十四例》引皎公《诗議》引）。"]', '诗', 'shi', '', NULL, '詩 無名氏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('14324dab-386d-4b39-9546-eefbff340d6a', '雙虛實對詩', '雙虛實对诗', '3fef2451-3384-4e62-9fb2-2e1e3fb62673', '唐', '["故人雲雨散，空山來往疏。"]', '["故人云雨散，空山来往疏。"]', '诗', 'shi', '', NULL, '雙虛實對詩 無名氏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('45577ba6-3bdd-4aa1-8132-f41c8f00ebff', '假對詩', '假对诗', '3fef2451-3384-4e62-9fb2-2e1e3fb62673', '唐', '["不獻胸中策，空歸海上山。","（同前書東卷引皎然《詩議》）。"]', '["不獻胸中策，空归海上山。","（同前书东卷引皎然《诗議》）。"]', '诗', 'shi', '', NULL, '假對詩 無名氏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f3dabde2-1c09-4caa-aad2-ac384a178c63', '詠物階詩 一', '詠物階诗 一', '3fef2451-3384-4e62-9fb2-2e1e3fb62673', '唐', '["雙眉學新綠，二臉例輕紅。","言模（一作摸）出浪鳥，字寫入花蟲。"]', '["雙眉学新綠，二臉例轻紅。","言模（一作摸）出浪鸟，字寫入花蟲。"]', '诗', 'shi', '', NULL, '詠物階詩 一 無名氏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7b93d83f-b4f5-4e1e-9423-b634f3d90246', '詠物階詩 二', '詠物階诗 二', '3fef2451-3384-4e62-9fb2-2e1e3fb62673', '唐', '["灑塵成細跡，點水作圓文。","白銀花裏散，明珠葉上分。","。"]', '["灑塵成細跡，点水作圓文。","白銀花裏散，明珠葉上分。","。"]', '诗', 'shi', '', NULL, '詠物階詩 二 無名氏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ce899b18-7615-4b9d-9858-64582f9404a1', '贈物階詩 一', '贈物階诗 一', '3fef2451-3384-4e62-9fb2-2e1e3fb62673', '唐', '["心貞如玉性，志潔若金爲。","託曾同心葉，因附合歡枝。"]', '["心貞如玉性，志潔若金爲。","託曾同心葉，因附合歡枝。"]', '诗', 'shi', '', NULL, '贈物階詩 一 無名氏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1eff93e5-b186-4427-bc61-24c76b5c80ca', '贈物階詩 二', '贈物階诗 二', '3fef2451-3384-4e62-9fb2-2e1e3fb62673', '唐', '["合瞑刺縫罷，守啼方達曙。","帶長垂兩巾，代人交手處。"]', '["合瞑刺縫罷，守啼方達曙。","带长垂兩巾，代人交手处。"]', '诗', 'shi', '', NULL, '贈物階詩 二 無名氏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('209a68e4-0f85-4f7a-bdbe-3f2d06527044', '述志階詩 一', '述志階诗 一', '3fef2451-3384-4e62-9fb2-2e1e3fb62673', '唐', '["有鳥異孤鸞，飛無羣獨漾。","鶴戲逐輕風，起響（一作「聊起」）三臺上。"]', '["有鸟異孤鸾，飞無羣独漾。","鹤戲逐轻风，起响（一作「聊起」）三台上。"]', '诗', 'shi', '', NULL, '述志階詩 一 無名氏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('587f6d68-47ae-49f9-901f-d55adfc3414b', '述志階詩 二', '述志階诗 二', '3fef2451-3384-4e62-9fb2-2e1e3fb62673', '唐', '["丈夫懷慷慨，膽（一作瞻）上湧波奔。","只將三尺劍，決搆一朱門。"]', '["丈夫懷慷慨，膽（一作瞻）上湧波奔。","只將三尺劍，決搆一朱门。"]', '诗', 'shi', '', NULL, '述志階詩 二 無名氏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3ca7c62d-1b2b-4fe2-a092-e6d7f75f383a', '寫心階詩 一', '寫心階诗 一', '3fef2451-3384-4e62-9fb2-2e1e3fb62673', '唐', '["命禮遣舟車，佇望談言志。","若值信來符（一作府），共子同琴瑟。"]', '["命禮遣舟车，佇望談言志。","若值信来符（一作府），共子同琴瑟。"]', '诗', 'shi', '', NULL, '寫心階詩 一 無名氏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b135add7-8a8c-4ba0-97b6-97efbd9c9f67', '寫心階詩 二', '寫心階诗 二', '3fef2451-3384-4e62-9fb2-2e1e3fb62673', '唐', '["插花花未歇，薰衣衣已香。","望望遙心斷，悽悽愁切腸。"]', '["插花花未歇，薰衣衣已香。","望望遙心斷，悽悽愁切腸。"]', '诗', 'shi', '', NULL, '寫心階詩 二 無名氏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('84c6bf78-0bee-401a-88d0-f545f00d8849', '近酬階詩 一', '近酬階诗 一', '3fef2451-3384-4e62-9fb2-2e1e3fb62673', '唐', '["盛夏盛炎光（一作光炎），焦天焦氣烈。"]', '["盛夏盛炎光（一作光炎），焦天焦氣烈。"]', '诗', 'shi', '', NULL, '近酬階詩 一 無名氏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('33c6ab89-6f5a-4352-a113-603b2211ddf2', '近酬階詩 二', '近酬階诗 二', '3fef2451-3384-4e62-9fb2-2e1e3fb62673', '唐', '["清階清溜瀉，涼戶涼風入。"]', '["清階清溜瀉，涼戶涼风入。"]', '诗', 'shi', '', NULL, '近酬階詩 二 無名氏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a2099b03-df8a-4148-a744-02391287011d', '讚毀階詩 一', '讚毀階诗 一', '3fef2451-3384-4e62-9fb2-2e1e3fb62673', '唐', '["施朱桃惡彩，點黛柳慚色。"]', '["施朱桃惡彩，点黛柳慚色。"]', '诗', 'shi', '', NULL, '讚毀階詩 一 無名氏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6026d6a3-4198-4210-8e25-1bd0ac9667c5', '讚毀階詩 二', '讚毀階诗 二', '3fef2451-3384-4e62-9fb2-2e1e3fb62673', '唐', '["皓雪已藏暉，凝霜方疊影。"]', '["皓雪已藏暉，凝霜方叠影。"]', '诗', 'shi', '', NULL, '讚毀階詩 二 無名氏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('73482d57-21da-4be9-867c-e646506d8819', '援寡階詩', '援寡階诗', '3fef2451-3384-4e62-9fb2-2e1e3fb62673', '唐', '["。"]', '["。"]', '诗', 'shi', '', NULL, '援寡階詩 無名氏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5a0dfd57-db6a-4b01-a6a1-7dda510ff489', '援寡階詩 一', '援寡階诗 一', '3fef2451-3384-4e62-9fb2-2e1e3fb62673', '唐', '["女蘿本細草，抽莖信不功。","憑高出嶺上，假樹入雲中。"]', '["女蘿本細草，抽莖信不功。","憑高出嶺上，假樹入云中。"]', '诗', 'shi', '', NULL, '援寡階詩 一 無名氏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d723ae8e-d60b-40f4-ad53-c8f74ab077e7', '援寡階詩 二', '援寡階诗 二', '3fef2451-3384-4e62-9fb2-2e1e3fb62673', '唐', '["愁臨玉臺鏡，淚垂金縷裙。"]', '["愁臨玉台镜，泪垂金縷裙。"]', '诗', 'shi', '', NULL, '援寡階詩 二 無名氏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('099b0cdf-0e1e-4461-907f-80ee49e8c42e', '和詩階詩 一', '和诗階诗 一', '3fef2451-3384-4e62-9fb2-2e1e3fb62673', '唐', '["花桃微散紅，萠蘭稍開紫。","客子情已多，春望復如此。"]', '["花桃微散紅，萠蘭稍开紫。","客子情已多，春望复如此。"]', '诗', 'shi', '', NULL, '和詩階詩 一 無名氏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b6b8b842-fdda-4930-8b70-aeca9d5dde35', '和詩階詩 二', '和诗階诗 二', '3fef2451-3384-4e62-9fb2-2e1e3fb62673', '唐', '["風光搖隴麥，日華映林蘂。","春情重以傷，歸念（一作命）何由弭？","（均見《文鏡秘府論》地卷《八階》錄佚名《文筆式》）（〖1〗今人逯欽立《先秦漢魏晉南北朝詩後記》云：「又如《文鏡秘府》也曾徵引許多詩篇，但這些詩篇率不著作者，其中有一部分又可能是初唐之作，因此，這裏也不加輯錄。","」按：逯說甚是。","今參照王利器先生《文鏡秘府論校注》的考訂，將《文鏡秘府論》中不見於《先秦漢魏晉南北朝詩》及《全唐詩》的作品，皆錄入先宋詩，以便研究者檢用。","）。"]', '["风光搖隴麦，日华映林蘂。","春情重以傷，归念（一作命）何由弭？","（均见《文镜秘府論》地卷《八階》錄佚名《文笔式》）（〖1〗今人逯欽立《先秦漢魏晉南北朝诗後記》云：「又如《文镜秘府》也曾徵引許多诗篇，但這些诗篇率不著作者，其中有一部分又可能是初唐之作，因此，這裏也不加輯錄。","」按：逯说甚是。","今參照王利器先生《文镜秘府論校注》的考訂，將《文镜秘府論》中不见於《先秦漢魏晉南北朝诗》及《全唐诗》的作品，皆錄入先宋诗，以便研究者檢用。","）。"]', '诗', 'shi', '', NULL, '和詩階詩 二 無名氏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9c488507-8cd2-4f51-9816-6d75ce5e5352', '北方歌', '北方歌', '3fef2451-3384-4e62-9fb2-2e1e3fb62673', '唐', '["北方玄武身本黑，家鄉體住崑崙國。","尋常定志有長生，方圓任性可生得。","隨流信運長爲客，誰識我身性無白。","不獨含著五行精，就中偏感陰陽魄。","調和兌震爲夫婦，四象排來在高處。","分明指似後人言，莫使昏迷錯天路。"]', '["北方玄武身本黑，家乡體住崑崙国。","尋常定志有长生，方圓任性可生得。","隨流信運长爲客，誰識我身性無白。","不独含著五行精，就中偏感陰陽魄。","調和兌震爲夫婦，四象排来在高处。","分明指似後人言，莫使昏迷錯天路。"]', '诗', 'shi', '', NULL, '北方歌 無名氏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c1bcc273-d38e-4922-a145-3b97eec1453a', '西方歌', '西方歌', '3fef2451-3384-4e62-9fb2-2e1e3fb62673', '唐', '["西方白虎本屬陰，爲男爲女亦爲金。","長立子宮胎產午，成形兌體坎同心。","嬌姿玉貌欺冰雪，素質含光洒輕血。","則知喚作白琅玕，怎識我身是明月。","無媒自嫁得黃芽，生死在歸戊己家。","炎烈下時寒國上，陰陽催強緫成砂。","若人會得吾此語，目前便是三清路。","駕鶴沖天日有菁定知永劫拋塵土。"]', '["西方白虎本屬陰，爲男爲女亦爲金。","长立子宮胎產午，成形兌體坎同心。","嬌姿玉貌欺冰雪，素質含光洒轻血。","則知喚作白琅玕，怎識我身是明月。","無媒自嫁得黄芽，生死在归戊己家。","炎烈下时寒国上，陰陽催強緫成砂。","若人會得吾此語，目前便是三清路。","駕鹤沖天日有菁定知永劫拋塵土。"]', '诗', 'shi', '', NULL, '西方歌 無名氏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5b84cd9f-4e96-48f4-8d1d-2bcc97c5e66b', '南方歌', '南方歌', '3fef2451-3384-4e62-9fb2-2e1e3fb62673', '唐', '["南方朱雀其身赤，猛烈雄強勢難敵。","性共乾坤造化齊，體並陰陽難消息。","水妻土母木家子，白帝金形胎受此。","四象皆因我氣生，萬類須由我氣死。","性連甲乙氣偏通，媾扇金娘嫁木翁。","歸投戊己到中宮，看看變轉緫交紅。","此謌不悟慇懃說，句句從頭細分雪。","莫言積學但陰功，始解消詳吾志訣。"]', '["南方朱雀其身赤，猛烈雄強勢难敵。","性共乾坤造化齊，體並陰陽难消息。","水妻土母木家子，白帝金形胎受此。","四象皆因我氣生，万類須由我氣死。","性連甲乙氣偏通，媾扇金娘嫁木翁。","归投戊己到中宮，看看变轉緫交紅。","此謌不悟慇懃说，句句從头細分雪。","莫言積学但陰功，始解消詳吾志訣。"]', '诗', 'shi', '', NULL, '南方歌 無名氏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6f3c06b6-7643-4794-8144-363e13c3dcd1', '東方歌', '东方歌', '3fef2451-3384-4e62-9fb2-2e1e3fb62673', '唐', '["東方有木本名砂，爲男爲女亦爲芽。","受氣午成須立子，含精育質長金家。","自從成長多年月，朝朝各自向天涯。","莫欺形貌黑皴皵，渾身緫是日精華。","忽若遇著陰家子，不假良媒自相許。","迎歸寶帳到中宮，陰陽氣合情意與。","特地爲胎重造化，運動坎離巡八卦。","十月懷胎母子分，定知霄漢驂鸞駕。"]', '["东方有木本名砂，爲男爲女亦爲芽。","受氣午成須立子，含精育質长金家。","自從成长多年月，朝朝各自向天涯。","莫欺形貌黑皴皵，渾身緫是日精华。","忽若遇著陰家子，不假良媒自相許。","迎归寶帳到中宮，陰陽氣合情意與。","特地爲胎重造化，運动坎離巡八卦。","十月懷胎母子分，定知霄漢驂鸾駕。"]', '诗', 'shi', '', NULL, '東方歌 無名氏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d79b3944-ccf8-4855-85cc-80f657bb238e', '中方歌', '中方歌', '3fef2451-3384-4e62-9fb2-2e1e3fb62673', '唐', '["中央戊己屬句陳，體合虛無與道隣。","純抱元和精粹氣，陶身萬煉緫成真。","木妻火子水家鬼，水土相鎮不能起。","還教却產西方金，遞代相承壯精髓。","雖然我身無正形，志事隈憑四象生。","四象不因連我氣，水金木火豈能成？","徧通金木恩情熟，留向胎中親養育。","麗物相和氣緫幷，須憑丙火來煎蹙。","丙火元來是我命，節候輪排依法令。"]', '["中央戊己屬句陳，體合虛無與道隣。","純抱元和精粹氣，陶身万煉緫成真。","木妻火子水家鬼，水土相鎮不能起。","還教却產西方金，遞代相承壯精髓。","雖然我身無正形，志事隈憑四象生。","四象不因連我氣，水金木火豈能成？","徧通金木恩情熟，留向胎中親養育。","丽物相和氣緫幷，須憑丙火来煎蹙。","丙火元来是我命，節候輪排依法令。"]', '诗', 'shi', '', NULL, '中方歌 無名氏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e4c95cba-0eec-4e8f-aace-586dadcbcca7', '二氣產黃芽歌', '二氣產黄芽歌', '3fef2451-3384-4e62-9fb2-2e1e3fb62673', '唐', '["乾坤感應始爲形，造化元因北戶成。","日月周旋魂魄合，陰陽交媾結爲精。","分明一氣從金長，認取黃芽自水生。","無限虛於塵世裏，時人日用不知名。"]', '["乾坤感應始爲形，造化元因北戶成。","日月周旋魂魄合，陰陽交媾結爲精。","分明一氣從金长，認取黄芽自水生。","無限虛於塵世裏，时人日用不知名。"]', '诗', 'shi', '', NULL, '二氣產黃芽歌 無名氏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c47a9c82-3268-48c3-8602-f807dc427496', '廣成子口訣', '廣成子口訣', '3fef2451-3384-4e62-9fb2-2e1e3fb62673', '唐', '["世上忙忙沒了程，百年如夢瞥然榮。","不知道有雲衢客，剛自爭超塵裏名。","若欲留年從太一，須吞靈藥便長生。","純燒無地陰陽髓，煉取乾坤日月精。"]', '["世上忙忙沒了程，百年如梦瞥然榮。","不知道有云衢客，剛自爭超塵裏名。","若欲留年從太一，須吞靈藥便长生。","純燒無地陰陽髓，煉取乾坤日月精。"]', '诗', 'shi', '', NULL, '廣成子口訣 無名氏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1488388b-4c95-4809-ab2e-5653bd7a4f00', '廣成子傳附二味', '廣成子傳附二味', '3fef2451-3384-4e62-9fb2-2e1e3fb62673', '唐', '["要伏離宮亦等閑，搜求坎戶取精研。","但比夫婦成交感，孕出黃芽見本源。","若不親傳師指受，此外徒勞虛費錢。","火候仍修終九九，丹成直待是三年。","（按：廣成子爲古神仙，事見《莊子·在宥》。","）。"]', '["要伏離宮亦等闲，搜求坎戶取精研。","但比夫婦成交感，孕出黄芽见本源。","若不親傳師指受，此外徒勞虛費錢。","火候仍修終九九，丹成直待是三年。","（按：廣成子爲古神仙，事见《莊子·在宥》。","）。"]', '诗', 'shi', '', NULL, '廣成子傳附二味 無名氏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1fe0920e-a984-4216-bf6b-58eed2191780', '抱朴子口訣', '抱朴子口訣', '3fef2451-3384-4e62-9fb2-2e1e3fb62673', '唐', '["朱砂水銀入華池，收得黃芽人不知。","本是仙人留口訣，世上喧喧亂言說。","七十年中付一人，分付還須有仙骨。","一一事須手眼傳，採取只在片時間。","河專覆在丹田裏，制伏只在黃芽邊。","（按：抱朴子即晉葛洪。","）。"]', '["朱砂水銀入华池，收得黄芽人不知。","本是仙人留口訣，世上喧喧亂言说。","七十年中付一人，分付還須有仙骨。","一一事須手眼傳，採取只在片时间。","河專覆在丹田裏，制伏只在黄芽邊。","（按：抱朴子即晉葛洪。","）。"]', '诗', 'shi', '', NULL, '抱朴子口訣 無名氏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c28bbfc9-018f-495b-8300-5e5d0612f204', '張華真人鉛汞歌', '張华真人鉛汞歌', '3fef2451-3384-4e62-9fb2-2e1e3fb62673', '唐', '["赤龍化爲粉，白虎利如霜。","其中投石液，還要帝流漿。","調神清五臟，欲得鍊三光。","專守堅冰性，如何陰使陽？。"]', '["赤龙化爲粉，白虎利如霜。","其中投石液，還要帝流漿。","調神清五臟，欲得鍊三光。","專守堅冰性，如何陰使陽？。"]', '诗', 'shi', '', NULL, '張華真人鉛汞歌 無名氏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('47b2e569-2a37-4386-88db-499306b051ff', '張華真人二味口訣', '張华真人二味口訣', '3fef2451-3384-4e62-9fb2-2e1e3fb62673', '唐', '["虎伏龍亦藏，龍潛先伏虎。","但畢河車功，不用隄防慮。","黃老學飛仙，狂迷不得路。","迴首指牝鷄，不測陰陽數。","却坐太一宮，參商方始遇。","左右得近神，四相皆扶護。","乾坤法象成，自有仙人顧。","（按：張華爲西晉時人。","）。"]', '["虎伏龙亦藏，龙潛先伏虎。","但畢河车功，不用隄防慮。","黄老学飞仙，狂迷不得路。","迴首指牝鷄，不測陰陽數。","却坐太一宮，參商方始遇。","左右得近神，四相皆扶護。","乾坤法象成，自有仙人顧。","（按：張华爲西晉时人。","）。"]', '诗', 'shi', '', NULL, '張華真人二味口訣 無名氏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('cf4f31b1-c909-4be2-808e-f620e73dada1', '尹喜真人口訣', '尹喜真人口訣', '3fef2451-3384-4e62-9fb2-2e1e3fb62673', '唐', '["至藥須用鉛，盃向黑中聚。","若欲識黃芽，先應問陰土。","真鉛配坎男，戊己來相顧。","只此號黃礬，便是還丹祖。","（按：尹喜即關尹喜，傳爲老子同時人。","）。"]', '["至藥須用鉛，盃向黑中聚。","若欲識黄芽，先應问陰土。","真鉛配坎男，戊己来相顧。","只此號黄礬，便是還丹祖。","（按：尹喜即关尹喜，傳爲老子同时人。","）。"]', '诗', 'shi', '', NULL, '尹喜真人口訣 無名氏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('bc3276c3-3a78-4a78-bd37-466876bbb7a3', '函谷關元君鉛汞謌', '函谷关元君鉛汞謌', '3fef2451-3384-4e62-9fb2-2e1e3fb62673', '唐', '["紅鉛黑鉛大丹頭，紅鉛黑鉛體同金。","黑金取精赤取髓，解用赤黑藥無比。","用赤入黑保長生，用黑入赤天仙矣。","顛倒兩法緫稱鉛，黑能變化赤天仙。","至道之人莫容易，貪財好色不須傳。","函谷關頭梁石山，老君鐫石留此言。"]', '["紅鉛黑鉛大丹头，紅鉛黑鉛體同金。","黑金取精赤取髓，解用赤黑藥無比。","用赤入黑保长生，用黑入赤天仙矣。","顛倒兩法緫稱鉛，黑能变化赤天仙。","至道之人莫容易，貪財好色不須傳。","函谷关头梁石山，老君鐫石留此言。"]', '诗', 'shi', '', NULL, '函谷關元君鉛汞謌 無名氏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ea1a7e7a-36b3-4790-be58-83bd32fb97f7', '漢祖天師口訣', '漢祖天師口訣', '3fef2451-3384-4e62-9fb2-2e1e3fb62673', '唐', '["鉛抽髓，髓抽精，精髓相合丹必成。","一斤水銀十七兩，一兩變化是鉛精。","將此鉛精作大丹，老子九轉入生研。","一麗水銀特牛力，服之令人貌若仙，貌若仙兮筋骨堅。","筋骨堅強返枯槁，截舌人間不須道。","未能隱顯出沒藏，切慎懼口莫顛狂。","若教上界天神怒，恐遭非橫及刀光。","。"]', '["鉛抽髓，髓抽精，精髓相合丹必成。","一斤水銀十七兩，一兩变化是鉛精。","將此鉛精作大丹，老子九轉入生研。","一丽水銀特牛力，服之令人貌若仙，貌若仙兮筋骨堅。","筋骨堅強返枯槁，截舌人间不須道。","未能隐显出沒藏，切慎懼口莫顛狂。","若教上界天神怒，恐遭非橫及刀光。","。"]', '诗', 'shi', '', NULL, '漢祖天師口訣 無名氏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7e6d323e-590d-4882-b7b5-c5c6136d80c0', '嚴君平口訣', '嚴君平口訣', '3fef2451-3384-4e62-9fb2-2e1e3fb62673', '唐', '["鉛是鉛，汞是汞，只這兩般是鉛汞。","龍是龍，虎是虎，只這兩箇同宗祖。","若能識此坎離宮，離宮之下出黃土。","黃土出黃芽，黃芽之下金花成。","金花成，金花之下結紫精。","紫精成，紫精之下出白金。","白金沉，黃金浮，世人採沉作丹頭，搜取赤髓相和種。","種有時，採有日，換筋骨，添壽歷，天仙地仙不思議。","點鉛鐵，兼瓦礫，一二三四五，水火木金土。","但知明此訣，便是長生路。"]', '["鉛是鉛，汞是汞，只這兩般是鉛汞。","龙是龙，虎是虎，只這兩箇同宗祖。","若能識此坎離宮，離宮之下出黄土。","黄土出黄芽，黄芽之下金花成。","金花成，金花之下結紫精。","紫精成，紫精之下出白金。","白金沉，黄金浮，世人採沉作丹头，搜取赤髓相和種。","種有时，採有日，換筋骨，添壽歷，天仙地仙不思議。","点鉛鐵，兼瓦礫，一二三四五，水火木金土。","但知明此訣，便是长生路。"]', '诗', 'shi', '', NULL, '嚴君平口訣 無名氏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4bb8a6ab-81ce-41da-add8-a4cfa56ac5e8', '陰長生口訣', '陰长生口訣', '3fef2451-3384-4e62-9fb2-2e1e3fb62673', '唐', '["金作骨兮鉛作身，陰陽定配龍虎親。","紅顏二八三才合，八卦分張斗建寅。","從子午，不須移，七十二候莫參差。","姹女因媒歸太一，紫微宮內生雄雌。","鉛中寶，砂中珍，此物含弘象五神。","七月懷胎分六甲，終歲人轉乃成真。","淮南法，煉秋石，黃帝金花燒琥珀。","白酒盃添九醖香，晶輝甘甜號龍液。","一人有，一人無，三姓同家二子俱。","狐兔非羣不乳馬，異類天然種性殊。","冥復冥，玄復玄，此法非人不可傳。","世人不知世上藥，知我還命不由天。","（按：嚴君平、陰長生皆漢時人。","）。"]', '["金作骨兮鉛作身，陰陽定配龙虎親。","紅顏二八三才合，八卦分張斗建寅。","從子午，不須移，七十二候莫參差。","姹女因媒归太一，紫微宮內生雄雌。","鉛中寶，砂中珍，此物含弘象五神。","七月懷胎分六甲，終歲人轉乃成真。","淮南法，煉秋石，黄帝金花燒琥珀。","白酒盃添九醖香，晶輝甘甜號龙液。","一人有，一人無，三姓同家二子俱。","狐兔非羣不乳马，異類天然種性殊。","冥复冥，玄复玄，此法非人不可傳。","世人不知世上藥，知我還命不由天。","（按：嚴君平、陰长生皆漢时人。","）。"]', '诗', 'shi', '', NULL, '陰長生口訣 無名氏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5c9a6197-e92b-42b2-a0e7-cb3f2f46be82', '果州謝自然口訣', '果州謝自然口訣', '3fef2451-3384-4e62-9fb2-2e1e3fb62673', '唐', '["白女正當年十六，自誇弱質顏如玉。","常嗟歲月無良媒，晝夜孤單唯獨宿。","爺娘不審他心意，謾說張三並李四。","幾度爲話緫不成，教人羞天復愧地。","忽遇黃婆來扣門，說道金公體性溫，遂將二命問君平。","君平斷言此好婚，不偏不曲合乾坤。","審此因緣甚宜良，至今子孫滿帝鄉。","昔時不因黃婆力，如何得契合陰陽。","（以上皆見《正統道藏》本《大還丹照鑑》）（按：《大還丹照鑑》編者不詳，卷首有後蜀廣政二十五年序，稱「偶因閑暇，採摭仙經，重刪先聖格言，留爲後人軌範，名曰《照鑑登仙集》，總成一卷，分作三十三篇」。","《通志·藝文略》著錄作《大還丹照鑑登仙集》一卷。","知今本書名未完。","此書所收詩以唐的之作爲多。","上錄自《北方歌》以下六篇不題撰人，自《廣成子口訣》以下十篇皆題古聖前哲之名，應皆爲唐人或唐以前人所依託。","謝自然，爲唐德宗貞元時人，事詳《太平廣記》卷六六引《集仙錄》。","然此詩顯爲時人詠其事之作。","與前列諸詩不同，姑錄存於此。","）。"]', '["白女正當年十六，自誇弱質顏如玉。","常嗟歲月無良媒，晝夜孤單唯独宿。","爺娘不審他心意，謾说張三並李四。","幾度爲話緫不成，教人羞天复愧地。","忽遇黄婆来扣门，说道金公體性溫，遂將二命问君平。","君平斷言此好婚，不偏不曲合乾坤。","審此因緣甚宜良，至今子孫满帝乡。","昔时不因黄婆力，如何得契合陰陽。","（以上皆见《正統道藏》本《大還丹照鑑》）（按：《大還丹照鑑》編者不詳，卷首有後蜀廣政二十五年序，稱「偶因闲暇，採摭仙經，重刪先聖格言，留爲後人軌範，名曰《照鑑登仙集》，總成一卷，分作三十三篇」。","《通志·藝文略》著錄作《大還丹照鑑登仙集》一卷。","知今本书名未完。","此书所收诗以唐的之作爲多。","上錄自《北方歌》以下六篇不題撰人，自《廣成子口訣》以下十篇皆題古聖前哲之名，應皆爲唐人或唐以前人所依託。","謝自然，爲唐德宗貞元时人，事詳《太平廣記》卷六六引《集仙錄》。","然此诗显爲时人詠其事之作。","與前列諸诗不同，姑錄存於此。","）。"]', '诗', 'shi', '', NULL, '果州謝自然口訣 無名氏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('adaaca24-e740-4037-9f4e-c23c3b2cc4d6', '太微天帝君讚大有妙經頌一章', '太微天帝君讚大有妙經頌一章', '3fef2451-3384-4e62-9fb2-2e1e3fb62673', '唐', '["丹暉映雲庭，紫煙光玉林。","煥爛七寶花，璀璨瑤靈音。","宮商自相和，妙靈開人衿。","玄唱種福田，廣度無界心。"]', '["丹暉映云庭，紫煙光玉林。","煥爛七寶花，璀璨瑤靈音。","宮商自相和，妙靈开人衿。","玄唱種福田，廣度無界心。"]', '诗', 'shi', '', NULL, '太微天帝君讚大有妙經頌一章 無名氏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('14e2c24b-656b-4ad5-b754-aaecc22e0da5', '天帝君讚大有妙經頌一章', '天帝君讚大有妙經頌一章', '3fef2451-3384-4e62-9fb2-2e1e3fb62673', '唐', '["玄化本無跡，有跡生道宗。","遨遊九天際，息駕六領宮，道暢虛漠內，靈歌發太空。","形感至寂庭，思詠希微通。"]', '["玄化本無跡，有跡生道宗。","遨游九天際，息駕六領宮，道暢虛漠內，靈歌發太空。","形感至寂庭，思詠希微通。"]', '诗', 'shi', '', NULL, '天帝君讚大有妙經頌一章 無名氏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a17bb619-a31d-4dc3-8231-3053754c9040', '太帝君讚大有妙經頌一章', '太帝君讚大有妙經頌一章', '3fef2451-3384-4e62-9fb2-2e1e3fb62673', '唐', '["翳翳元化初，眇眇晨霞散。","太寂空玄上，寥朗二儀判。","凝精抱空胎，結化孕靈觀。","含真頤神內，倏歘啓㝠旦。","始悟憂促齡，運交反天漢。"]', '["翳翳元化初，眇眇晨霞散。","太寂空玄上，寥朗二儀判。","凝精抱空胎，結化孕靈观。","含真頤神內，倏歘啓㝠旦。","始悟憂促齡，運交反天漢。"]', '诗', 'shi', '', NULL, '太帝君讚大有妙經頌一章 無名氏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('31cc9034-da97-43ea-92ef-102bf10f6a31', '老君本生經頌一章', '老君本生經頌一章', '3fef2451-3384-4e62-9fb2-2e1e3fb62673', '唐', '["衆生之本際，寂然無起滅。","弱喪迷其根，自與真源別。","妄作善惡緣，禍福報無絕。","欲得苦海傾，當使愛河竭。","守一固專柔，持此無疵缺。","正智通羣有，妙慧摧諸結。","萬行混同歸，三乘泯殊轍。","真靜離塵垢，清涼無惱熱。"]', '["衆生之本際，寂然無起滅。","弱喪迷其根，自與真源別。","妄作善惡緣，禍福報無絕。","欲得苦海傾，當使愛河竭。","守一固專柔，持此無疵缺。","正智通羣有，妙慧摧諸結。","万行混同归，三乘泯殊轍。","真静離塵垢，清涼無惱熱。"]', '诗', 'shi', '', NULL, '老君本生經頌一章 無名氏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7c827828-384b-498e-8de3-3d246a8d39b8', '太上智慧佪玄經頌一章', '太上智慧佪玄經頌一章', '3fef2451-3384-4e62-9fb2-2e1e3fb62673', '唐', '["靈仙乘慶霄，駕龍躡玄波。","洽真表嘉祥，濯足八天河。","福應不我期，故能釋天羅。","道德冠三界，地網亦以過。","感遇靈真會，淨慧經蓮華。"]', '["靈仙乘慶霄，駕龙躡玄波。","洽真表嘉祥，濯足八天河。","福應不我期，故能釋天羅。","道德冠三界，地網亦以過。","感遇靈真會，淨慧經蓮华。"]', '诗', 'shi', '', NULL, '太上智慧佪玄經頌一章 無名氏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1c527ae6-0f3d-4198-9a70-216932b42cea', '太上智慧經讚一章', '太上智慧經讚一章', '3fef2451-3384-4e62-9fb2-2e1e3fb62673', '唐', '["學仙絕華念，念念相因積。","去來亂我神，神躁靡不歷。","滅念停虛閑，蕭蕭入空寂。","請經若飢渴，持志如金石。","保子飛玄路，五靈度符籍。"]', '["学仙絕华念，念念相因積。","去来亂我神，神躁靡不歷。","滅念停虛闲，蕭蕭入空寂。","請經若飢渴，持志如金石。","保子飞玄路，五靈度符籍。"]', '诗', 'shi', '', NULL, '太上智慧經讚一章 無名氏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('05fa7fbf-19fc-4fa7-947c-f6445d734fb2', '本願大戒經頌一章', '本願大戒經頌一章', '3fef2451-3384-4e62-9fb2-2e1e3fb62673', '唐', '["學自行爲急，奉戒制情心。","虛夷正氣居，仙聖自相尋。"]', '["学自行爲急，奉戒制情心。","虛夷正氣居，仙聖自相尋。"]', '诗', 'shi', '', NULL, '本願大戒經頌一章 無名氏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9c28112b-597f-4195-bc31-7610c231912e', '玉皇授歘生大洞三十九章與登龍臺歌二章 一', '玉皇授歘生大洞三十九章與登龙台歌二章 一', '3fef2451-3384-4e62-9fb2-2e1e3fb62673', '唐', '["飈飈三霞領，佪剛七元蓋。","八景入太元，飛灑九天外。","瓊扉生景雲，靈煙絶幽藹。","西宮詠洞玄，清唱扶桑際。","守雌森峯間，玄吟五老會。","歘生有心哉，與爾結中帶。"]', '["飈飈三霞領，佪剛七元蓋。","八景入太元，飞灑九天外。","瓊扉生景云，靈煙絶幽藹。","西宮詠洞玄，清唱扶桑際。","守雌森峯间，玄吟五老會。","歘生有心哉，與爾結中带。"]', '诗', 'shi', '', NULL, '玉皇授歘生大洞三十九章與登龍臺歌二章 一 無名氏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d5258933-09e2-4115-b3e5-ff5bc2e9e34f', '玉皇授歘生大洞三十九章與登龍臺歌二章 二', '玉皇授歘生大洞三十九章與登龙台歌二章 二', '3fef2451-3384-4e62-9fb2-2e1e3fb62673', '唐', '["匏河振滄茫，天津鼓萬流。","八風駕神霄，緬緬虛中遊。","詠洞神明唱，音爲汝玄投。","歘生必至行，肘伏塵中趨。","可爲苦心哉，當告爾所求。","。"]', '["匏河振滄茫，天津鼓万流。","八风駕神霄，緬緬虛中游。","詠洞神明唱，音爲汝玄投。","歘生必至行，肘伏塵中趨。","可爲苦心哉，當告爾所求。","。"]', '诗', 'shi', '', NULL, '玉皇授歘生大洞三十九章與登龍臺歌二章 二 無名氏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a5f4a8f9-7e00-44db-bc91-bc4593115c5b', '西王母授紫度炎光神變經頌三篇 一', '西王母授紫度炎光神变經頌三篇 一', '3fef2451-3384-4e62-9fb2-2e1e3fb62673', '唐', '["嘯歌九玄臺，崖嶺凝淒端。","心理六覺暢，目棄塵滓氛。","流霞耀金室，虛堂散重玄。","積感致靈降，形單道亦分。","倏歘盼萬劫，豈覺周億椿。"]', '["嘯歌九玄台，崖嶺凝淒端。","心理六覺暢，目棄塵滓氛。","流霞耀金室，虛堂散重玄。","積感致靈降，形單道亦分。","倏歘盼万劫，豈覺周億椿。"]', '诗', 'shi', '', NULL, '西王母授紫度炎光神變經頌三篇 一 無名氏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('02cf0323-ca5f-4be1-8a4e-03abf7611d1d', '西王母授紫度炎光神變經頌三篇 二', '西王母授紫度炎光神变經頌三篇 二', '3fef2451-3384-4e62-9fb2-2e1e3fb62673', '唐', '["秀圃蔚神階，朱扉瓊林庭。","流風鼓空洞，玉籟乘虛鳴。","紫烟纏曲戶，丹暉映綠軿。","飛旗欝玄蓋，羽節耀紫清。","登景九霄際，遨遊戲鳳城。","顧愛幽境子，一樂同朝生。"]', '["秀圃蔚神階，朱扉瓊林庭。","流风鼓空洞，玉籟乘虛鳴。","紫烟纏曲戶，丹暉映綠軿。","飞旗欝玄蓋，羽節耀紫清。","登景九霄際，遨游戲鳳城。","顧愛幽境子，一乐同朝生。"]', '诗', 'shi', '', NULL, '西王母授紫度炎光神變經頌三篇 二 無名氏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('fa2cb517-b622-43b0-8251-1c653e8b0ce1', '西王母授紫度炎光神變經頌三篇 三', '西王母授紫度炎光神变經頌三篇 三', '3fef2451-3384-4e62-9fb2-2e1e3fb62673', '唐', '["騰轡控朗暉，宴景洞野外。","流浪尋靈人，合形慶霄際。","手披朱島戶，朗若神沖泰。","金闕欝嵯峨，清景無塵穢，解衿玄閬臺，適我良願會。","脫屣三塗難，保鍊固年邁。"]', '["腾轡控朗暉，宴景洞野外。","流浪尋靈人，合形慶霄際。","手披朱島戶，朗若神沖泰。","金闕欝嵯峨，清景無塵穢，解衿玄閬台，適我良願會。","脫屣三塗难，保鍊固年邁。"]', '诗', 'shi', '', NULL, '西王母授紫度炎光神變經頌三篇 三 無名氏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('73a08b84-df6d-4c40-a17b-c5361d0c3198', '靈寶真一自然太上玄一真人頌一章', '靈寶真一自然太上玄一真人頌一章', '3fef2451-3384-4e62-9fb2-2e1e3fb62673', '唐', '["衆妙出洞真，煥爛曜太清。","奉者號仙人，體無永長生。","逍遙戲玄虛，宮殿羅無形。","蒨粲七寶林，晃朗日月精。","龍鱗交橫馳，鳳皇翔悲鳴。","太上治紫臺，衆真誦洞經。","捻香稽首禮，旋行遶宮城。","三周歸高座，道王爲應聲。","人主弘至道，天下普安寧。"]', '["衆妙出洞真，煥爛曜太清。","奉者號仙人，體無永长生。","逍遙戲玄虛，宮殿羅無形。","蒨粲七寶林，晃朗日月精。","龙鱗交橫驰，鳳皇翔悲鳴。","太上治紫台，衆真誦洞經。","捻香稽首禮，旋行遶宮城。","三周归高座，道王爲應声。","人主弘至道，天下普安寧。"]', '诗', 'shi', '', NULL, '靈寶真一自然太上玄一真人頌一章 無名氏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b9cbf372-b4c8-4428-8f94-a7cab160556d', '太上弘道頌一章', '太上弘道頌一章', '3fef2451-3384-4e62-9fb2-2e1e3fb62673', '唐', '["太上玄虛宗，弘道尊其經。","俯仰已得仙，歷劫無數齡。","巍巍太真德，寂寂因無生。","霄景結空構，乘虛自然征。","明月光炳灼，安和樂未央。"]', '["太上玄虛宗，弘道尊其經。","俯仰已得仙，歷劫無數齡。","巍巍太真德，寂寂因無生。","霄景結空構，乘虛自然征。","明月光炳灼，安和乐未央。"]', '诗', 'shi', '', NULL, '太上弘道頌一章 無名氏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3225b4d2-7027-401f-bc26-329f45be25d3', '吳王夫差書一章（幷序）', '吳王夫差书一章（幷序）', '3fef2451-3384-4e62-9fb2-2e1e3fb62673', '唐', '["玄津流絳波，崑碧映琅山。","朝日控晨輝，薈豔何婉蜒。","遊雲落太陽，飈景淩三天。","靈寶曜九虛，幽明鍾山間。","夏禹登八牕，散氣響金蘭。","因枝振玉條，緣波討洪源。","扶質立靈榦，垂葉以結繁。","渺邈龍鳳跡，煥爛九天翰。","仰挹三辰精，保身永長安。","俯漱五華液，還復反童顏。","騰神溫涼宮，豈知熱與寒。","千秋似清旦，萬歲猶日半。","鼓翼空洞上，要我靈寶官。","棼棼五帝駕，俱會景漠端。","相問飢與渴，玄泉饒流丹。","永仙方寸內，八遐無易難。","顧聞朱門臭，當塗中有難。","銘碣勞巖陰，穴岫可稽盤。","（以上皆見《雲笈七籤》卷九六）。"]', '["玄津流絳波，崑碧映琅山。","朝日控晨輝，薈豔何婉蜒。","游云落太陽，飈景淩三天。","靈寶曜九虛，幽明鍾山间。","夏禹登八牕，散氣响金蘭。","因枝振玉條，緣波討洪源。","扶質立靈榦，垂葉以結繁。","渺邈龙鳳跡，煥爛九天翰。","仰挹三辰精，保身永长安。","俯漱五华液，還复反童顏。","腾神溫涼宮，豈知熱與寒。","千秋似清旦，万歲猶日半。","鼓翼空洞上，要我靈寶官。","棼棼五帝駕，俱會景漠端。","相问飢與渴，玄泉饒流丹。","永仙方寸內，八遐無易难。","顧闻朱门臭，當塗中有难。","銘碣勞巖陰，穴岫可稽盤。","（以上皆见《云笈七籤》卷九六）。"]', '诗', 'shi', '', NULL, '吳王夫差書一章（幷序） 無名氏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1edcf79a-6b17-408c-a6a1-37f4f8277872', '衆仙步虛詞五首 一', '衆仙步虛词五首 一', '3fef2451-3384-4e62-9fb2-2e1e3fb62673', '唐', '["飄飄上雲路，黯黯入長霄。","星宮日去遠，光陰劫數遙。","仰德金顏隱，傾想佇神飈。","願得暎霞軫，焚香稽首朝。"]', '["飄飄上云路，黯黯入长霄。","星宮日去远，光陰劫數遙。","仰德金顏隐，傾想佇神飈。","願得暎霞軫，焚香稽首朝。"]', '诗', 'shi', '', NULL, '衆仙步虛詞五首 一 無名氏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('fa819521-af85-4a95-ad62-ff13af26ca78', '衆仙步虛詞五首 二', '衆仙步虛词五首 二', '3fef2451-3384-4e62-9fb2-2e1e3fb62673', '唐', '["玄風轉飛蓋，紫氣汎仙車。","浮空不侍駕，倐忽昇虛無。","徘徊哀下界，顧眄愍羣諸。","三元真化畢，翛然入太虛。"]', '["玄风轉飞蓋，紫氣汎仙车。","浮空不侍駕，倐忽昇虛無。","徘徊哀下界，顧眄愍羣諸。","三元真化畢，翛然入太虛。"]', '诗', 'shi', '', NULL, '衆仙步虛詞五首 二 無名氏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0dcdcb3d-0fcc-490f-a17a-f05c651877ca', '衆仙步虛詞五首 三', '衆仙步虛词五首 三', '3fef2451-3384-4e62-9fb2-2e1e3fb62673', '唐', '["萬氣浮空上，千光合太微。","霄間望華蓋，虛裏眄霞衣。","真儀入雲路，圓曜逐風飛。","願得三元會，金容乘運歸。"]', '["万氣浮空上，千光合太微。","霄间望华蓋，虛裏眄霞衣。","真儀入云路，圓曜逐风飞。","願得三元會，金容乘運归。"]', '诗', 'shi', '', NULL, '衆仙步虛詞五首 三 無名氏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('746b3ca7-e7fa-4b22-806b-72b7c74cdbbe', '衆仙步虛詞五首 四', '衆仙步虛词五首 四', '3fef2451-3384-4e62-9fb2-2e1e3fb62673', '唐', '["吉光騰紫氣，霄路逸丹天。","蟠颺香風轉，蓋動超浮煙。","道中還復道，玄中已復玄。","真光不識際，大道竟無形。","法輪常自轉，希音不可聽。","空閑待三寶，虛中聞洞經。","七變遊魂反，萬氣駐頹齡。"]', '["吉光腾紫氣，霄路逸丹天。","蟠颺香风轉，蓋动超浮煙。","道中還复道，玄中已复玄。","真光不識際，大道竟無形。","法輪常自轉，希音不可听。","空闲待三寶，虛中闻洞經。","七变游魂反，万氣駐頹齡。"]', '诗', 'shi', '', NULL, '衆仙步虛詞五首 四 無名氏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5d47f9ab-605f-44b4-90b1-19c1d4e40c81', '衆仙步虛詞五首 五', '衆仙步虛词五首 五', '3fef2451-3384-4e62-9fb2-2e1e3fb62673', '唐', '["香風飄羽蓋，遊氣轉飈車。","泠泠上雲路，窈窈入長虛。","顧愍埃塵子，應運演靈書。","妙果諧今日，㝠契自然符。","（《雲笈七籤》卷九九）。"]', '["香风飄羽蓋，游氣轉飈车。","泠泠上云路，窈窈入长虛。","顧愍埃塵子，應運演靈书。","妙果諧今日，㝠契自然符。","（《云笈七籤》卷九九）。"]', '诗', 'shi', '', NULL, '衆仙步虛詞五首 五 無名氏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d3a5b9ea-70fc-4c1d-ad67-12c498019caa', '青童天君常吟一首', '青童天君常吟一首', '3fef2451-3384-4e62-9fb2-2e1e3fb62673', '唐', '["欲植滅度根，當拔生死栽。","沉吟墮九泉，但坐惜形骸。","（同前）。"]', '["欲植滅度根，當拔生死栽。","沉吟墮九泉，但坐惜形骸。","（同前）。"]', '诗', 'shi', '', NULL, '青童天君常吟一首 無名氏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('79c2288a-0eb6-42b0-b594-5961a44da7fd', '陶隱居望江南 一', '陶隐居望江南 一', '3fef2451-3384-4e62-9fb2-2e1e3fb62673', '唐', '["長生藥，本是五行作。","子午三門開卯酉，四時運火合乾坤。","龍虎自相吞。"]', '["长生藥，本是五行作。","子午三门开卯酉，四时運火合乾坤。","龙虎自相吞。"]', '诗', 'shi', '', NULL, '陶隱居望江南 一 無名氏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('559deef1-764f-4f72-ad38-023d298a67d7', '過崔駙馬山池', '過崔駙马山池', '0a9829cc-805b-4812-a86a-1b2aee6a69ad', '唐', '["畫樓吹笛妓，金椀酒家胡。","錦石稱貞女，青松學大夫。","脫貂貰桂醑，射雁與山廚。","聞道高陽會，愚公谷正愚。"]', '["畫楼吹笛妓，金椀酒家胡。","錦石稱貞女，青松学大夫。","脫貂貰桂醑，射雁與山廚。","闻道高陽會，愚公谷正愚。"]', '诗', 'shi', '', NULL, '過崔駙馬山池 王維 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('595dc46d-917d-4e78-ad43-09fd253a689d', '過福禪師蘭若', '過福禪師蘭若', '0a9829cc-805b-4812-a86a-1b2aee6a69ad', '唐', '["巖壑轉微逕，雲林隱法堂。","羽人飛奏樂，天女跪焚香。","竹外峰偏曙，藤陰水更涼。","欲知禪坐久，行路長春芳。"]', '["巖壑轉微逕，云林隐法堂。","羽人飞奏乐，天女跪焚香。","竹外峰偏曙，藤陰水更涼。","欲知禪坐久，行路长春芳。"]', '诗', 'shi', '', NULL, '過福禪師蘭若 王維 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e4354c00-c83e-43da-9341-7007889dd625', '過香積寺', '過香積寺', '0a9829cc-805b-4812-a86a-1b2aee6a69ad', '唐', '["不知香積寺，數里入雲峰。","古木無人逕，深山何處鐘。","泉聲咽危石，日色冷青松。","薄暮空潭曲，安禪制毒龍。"]', '["不知香積寺，數里入云峰。","古木無人逕，深山何处鐘。","泉声咽危石，日色冷青松。","薄暮空潭曲，安禪制毒龙。"]', '诗', 'shi', '', NULL, '過香積寺 王維 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f9b87c32-b12b-498f-9988-501a50e9d27e', '過感化寺曇興上人山院', '過感化寺曇兴上人山院', '0a9829cc-805b-4812-a86a-1b2aee6a69ad', '唐', '["暮持筇竹杖，相待虎谿頭。","催客聞山響，歸房逐水流。","野花叢發好，谷鳥一聲幽。","夜坐空林寂，松風直似秋。"]', '["暮持筇竹杖，相待虎谿头。","催客闻山响，归房逐水流。","野花叢發好，谷鸟一声幽。","夜坐空林寂，松风直似秋。"]', '诗', 'shi', '', NULL, '過感化寺曇興上人山院 王維 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('fd260e2f-fd85-4464-9589-37744e39c7f8', '夏日過青龍寺謁操禪師', '夏日過青龙寺謁操禪師', '0a9829cc-805b-4812-a86a-1b2aee6a69ad', '唐', '["龍鍾一老翁，徐步謁禪宮。","欲問義心義，遙知空病空。","山河天眼裏，世界法身中。","莫怪銷炎熱，能生大地風。"]', '["龙鍾一老翁，徐步謁禪宮。","欲问義心義，遙知空病空。","山河天眼裏，世界法身中。","莫怪銷炎熱，能生大地风。"]', '诗', 'shi', '', NULL, '夏日過青龍寺謁操禪師 王維 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0acfb9ff-839d-46d5-81cb-248a546da7e0', '登辨覺寺', '登辨覺寺', '0a9829cc-805b-4812-a86a-1b2aee6a69ad', '唐', '["竹徑從初地，蓮峰出化城。","窗中三楚盡，林上九江平。","軟草承趺坐，長松響梵聲。","空居法雲外，觀世得無生。"]', '["竹徑從初地，蓮峰出化城。","窗中三楚尽，林上九江平。","軟草承趺坐，长松响梵声。","空居法云外，观世得無生。"]', '诗', 'shi', '', NULL, '登辨覺寺 王維 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3a21432b-5303-4025-af6a-92c04037393c', '喜祖三至留宿', '喜祖三至留宿', '0a9829cc-805b-4812-a86a-1b2aee6a69ad', '唐', '["門前洛陽客，下馬拂征衣。","不枉故人駕，平生多掩扉。","行人返深巷，積雪帶餘暉。","早歲同袍者，高車何處歸。"]', '["门前洛陽客，下马拂征衣。","不枉故人駕，平生多掩扉。","行人返深巷，積雪带餘暉。","早歲同袍者，高车何处归。"]', '诗', 'shi', '', NULL, '喜祖三至留宿 王維 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('71bdf7b5-493f-41e8-b0cf-6f1acd7bb8ea', '黎拾遺昕裴秀才迪見過秋夜對雨之作', '黎拾遺昕裴秀才迪见過秋夜对雨之作', '0a9829cc-805b-4812-a86a-1b2aee6a69ad', '唐', '["促織鳴已急，輕衣行向重。","寒燈坐高館，秋雨聞疎鐘。","白法調狂象，玄言問老龍。","何人顧蓬徑，空愧求羊蹤。"]', '["促织鳴已急，轻衣行向重。","寒灯坐高館，秋雨闻疎鐘。","白法調狂象，玄言问老龙。","何人顧蓬徑，空愧求羊蹤。"]', '诗', 'shi', '', NULL, '黎拾遺昕裴秀才迪見過秋夜對雨之作 王維 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b5b56a19-8b98-4755-ad3a-a0da6b6612da', '慕容承攜素饌見過', '慕容承携素饌见過', '0a9829cc-805b-4812-a86a-1b2aee6a69ad', '唐', '["紗帽烏皮几，閑居懶賦詩。","門看五柳識，年筭六身知。","靈壽君王賜，彫胡弟子炊。","空勞酒食饌，持底解人頤。"]', '["紗帽烏皮几，闲居懶賦诗。","门看五柳識，年筭六身知。","靈壽君王賜，彫胡弟子炊。","空勞酒食饌，持底解人頤。"]', '诗', 'shi', '', NULL, '慕容承攜素饌見過 王維 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a47c06ac-69d2-4395-953d-e56efcfc4eb3', '晚春嚴少尹與諸公見過', '晚春嚴少尹與諸公见過', '0a9829cc-805b-4812-a86a-1b2aee6a69ad', '唐', '["松菊荒三逕，圖書共五車。","烹葵邀上客，看竹到貧家。","鵲乳先春草，鶯啼過落花。","自憐黃髪暮，一倍惜年華。"]', '["松菊荒三逕，圖书共五车。","烹葵邀上客，看竹到貧家。","鵲乳先春草，鶯啼過落花。","自怜黄髪暮，一倍惜年华。"]', '诗', 'shi', '', NULL, '晚春嚴少尹與諸公見過 王維 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d2d687a3-fdce-4d68-93dd-ce9195d5925e', '鄭果州相過', '鄭果州相過', '0a9829cc-805b-4812-a86a-1b2aee6a69ad', '唐', '["麗日照殘春，初晴草木新。","牀前磨鏡客，樹下灌園人。","五馬驚窮巷，雙童逐老身。","中廚辦麤飯，當恕阮家貧。"]', '["丽日照殘春，初晴草木新。","牀前磨镜客，樹下灌园人。","五马驚窮巷，雙童逐老身。","中廚辦麤飯，當恕阮家貧。"]', '诗', 'shi', '', NULL, '鄭果州相過 王維 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('00f12a19-bb96-4980-a4f5-11a1b9d604dd', '山居秋暝', '山居秋暝', '0a9829cc-805b-4812-a86a-1b2aee6a69ad', '唐', '["空山新雨後，天氣晚來秋。","明月松間照，清泉石上流。","竹喧歸浣女，蓮動下漁舟。","隨意春芳歇，王孫自可留。"]', '["空山新雨後，天氣晚来秋。","明月松间照，清泉石上流。","竹喧归浣女，蓮动下漁舟。","隨意春芳歇，王孫自可留。"]', '诗', 'shi', '', NULL, '山居秋暝 王維 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6d098c75-038d-45f4-8f86-73976c355e44', '終南別業', '終南別業', '0a9829cc-805b-4812-a86a-1b2aee6a69ad', '唐', '["中歲頗好道，晚家南山陲。","興來每獨往，勝事空自知。","行到水窮處，坐看雲起時。","偶然值林叟，談笑無還期。"]', '["中歲頗好道，晚家南山陲。","兴来每独往，勝事空自知。","行到水窮处，坐看云起时。","偶然值林叟，談笑無還期。"]', '诗', 'shi', '', NULL, '終南別業 王維 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('40cd6eec-c6ce-4659-a225-61063cd210e9', '歸嵩山作', '归嵩山作', '0a9829cc-805b-4812-a86a-1b2aee6a69ad', '唐', '["清川帶長薄，車馬去閑閑。","流水如有意，暮禽相與還。","荒城臨古渡，落日滿秋山。","迢遞嵩高下，歸來且閉關。"]', '["清川带长薄，车马去闲闲。","流水如有意，暮禽相與還。","荒城臨古渡，落日满秋山。","迢遞嵩高下，归来且閉关。"]', '诗', 'shi', '', NULL, '歸嵩山作 王維 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6146d9b1-b526-4c8e-86be-ea0be3c72375', '歸輞川作', '归輞川作', '0a9829cc-805b-4812-a86a-1b2aee6a69ad', '唐', '["谷口疎鐘動，漁樵稍欲稀。","悠然遠山暮，獨向白雲歸。","菱蔓弱難定，楊花輕易飛。","東臯春草色，惆悵掩柴扉。"]', '["谷口疎鐘动，漁樵稍欲稀。","悠然远山暮，独向白云归。","菱蔓弱难定，楊花轻易飞。","东臯春草色，惆悵掩柴扉。"]', '诗', 'shi', '', NULL, '歸輞川作 王維 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('142d78a3-2f2b-4652-8cd0-e8ef74aef212', '韋給事山居', '韋給事山居', '0a9829cc-805b-4812-a86a-1b2aee6a69ad', '唐', '["幽尋得此地，詎有一人曾。","大壑隨階轉，羣山入戶登。","庖廚出深竹，印綬隔垂藤。","即事辭軒冕，誰云病未能。"]', '["幽尋得此地，詎有一人曾。","大壑隨階轉，羣山入戶登。","庖廚出深竹，印綬隔垂藤。","即事辞軒冕，誰云病未能。"]', '诗', 'shi', '', NULL, '韋給事山居 王維 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('304699b5-7b28-445c-8e97-1b3c4431e69d', '山居即事', '山居即事', '0a9829cc-805b-4812-a86a-1b2aee6a69ad', '唐', '["寂寞掩柴扉，蒼茫對落暉。","鶴巢松樹遍，人訪蓽門稀。","綠竹含新粉，紅蓮落故衣。","渡頭煙火起，處處采菱歸。"]', '["寂寞掩柴扉，蒼茫对落暉。","鹤巢松樹遍，人訪蓽门稀。","綠竹含新粉，紅蓮落故衣。","渡头煙火起，处处采菱归。"]', '诗', 'shi', '', NULL, '山居即事 王維 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a5b1f5c9-1ba7-4533-b497-55b1d4af1bbb', '終南山', '終南山', '0a9829cc-805b-4812-a86a-1b2aee6a69ad', '唐', '["太乙近天都，連山接海隅。","白雲迴望合，青靄入看無。","分野中峰變，陰晴衆壑殊。","欲投人處宿，隔水問樵夫。"]', '["太乙近天都，連山接海隅。","白云迴望合，青靄入看無。","分野中峰变，陰晴衆壑殊。","欲投人处宿，隔水问樵夫。"]', '诗', 'shi', '', NULL, '終南山 王維 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2323f730-4046-4aad-a753-14425c7f0c3c', '輞川閑居', '輞川闲居', '0a9829cc-805b-4812-a86a-1b2aee6a69ad', '唐', '["一從歸白社，不復到青門。","時倚檐前樹，遠看原上村。","青菰臨水拔，白鳥向山翻。","寂寞於陵子，桔槔方灌園。"]', '["一從归白社，不复到青门。","时倚檐前樹，远看原上村。","青菰臨水拔，白鸟向山翻。","寂寞於陵子，桔槔方灌园。"]', '诗', 'shi', '', NULL, '輞川閑居 王維 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('90d959e3-5b1e-4ff5-b7a5-468290a2e7fc', '春園即事', '春园即事', '0a9829cc-805b-4812-a86a-1b2aee6a69ad', '唐', '["宿雨乘輕屐，春寒著弊袍。","開畦分白水，間柳發紅桃。","草際成棋局，林端舉桔槔。","還持鹿皮几，日暮隱蓬蒿。"]', '["宿雨乘轻屐，春寒著弊袍。","开畦分白水，间柳發紅桃。","草際成棋局，林端舉桔槔。","還持鹿皮几，日暮隐蓬蒿。"]', '诗', 'shi', '', NULL, '春園即事 王維 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('cb402b16-d987-453e-9a95-4130ee43abab', '淇上田園即事', '淇上田园即事', '0a9829cc-805b-4812-a86a-1b2aee6a69ad', '唐', '["屏居淇水上，東野曠無山。","日隱桑柘外，河明閭井間。","牧童望村去，獵犬隨人還。","靜者亦何事，荆扉乘晝關。"]', '["屏居淇水上，东野曠無山。","日隐桑柘外，河明閭井间。","牧童望村去，獵犬隨人還。","静者亦何事，荆扉乘晝关。"]', '诗', 'shi', '', NULL, '淇上田園即事 王維 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d8c1b2ae-8f64-464a-bb2b-e8a675236f64', '涼州郊外遊望', '涼州郊外游望', '0a9829cc-805b-4812-a86a-1b2aee6a69ad', '唐', '["野老纔三戶，邊村少四鄰。","婆娑依里社，簫鼓賽田神。","灑酒澆芻狗，焚香拜木人。","女巫紛屢舞，羅襪自生塵。"]', '["野老纔三戶，邊村少四鄰。","婆娑依里社，簫鼓賽田神。","灑酒澆芻狗，焚香拜木人。","女巫紛屢舞，羅襪自生塵。"]', '诗', 'shi', '', NULL, '涼州郊外遊望 王維 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f66fc9fd-c77f-4c19-b4b5-33784cb612cb', '觀獵', '观獵', '0a9829cc-805b-4812-a86a-1b2aee6a69ad', '唐', '["風勁角弓鳴，將軍獵渭城。","草枯鷹眼疾，雪盡馬蹄輕。","忽過新豐市，還歸細柳營。","迴看射鵰處，千里暮雲平。"]', '["风勁角弓鳴，將軍獵渭城。","草枯鷹眼疾，雪尽马蹄轻。","忽過新豐市，還归細柳營。","迴看射鵰处，千里暮云平。"]', '诗', 'shi', '', NULL, '觀獵 王維 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b994d0ea-2762-4e26-88cd-b6c27cd7cef3', '春日上方即事', '春日上方即事', '0a9829cc-805b-4812-a86a-1b2aee6a69ad', '唐', '["好讀高僧傳，時看辟穀方。","鳩形將刻杖，龜殼用支牀。","柳色春山暎，梨花夕鳥藏。","北窗桃李下，閑坐但焚香。"]', '["好读高僧傳，时看辟穀方。","鳩形將刻杖，龟殼用支牀。","柳色春山暎，梨花夕鸟藏。","北窗桃李下，闲坐但焚香。"]', '诗', 'shi', '', NULL, '春日上方即事 王維 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9080a103-2750-4b9b-a4fa-1167cd670a0c', '漢江臨汎', '漢江臨汎', '0a9829cc-805b-4812-a86a-1b2aee6a69ad', '唐', '["楚塞三湘接，荆門九派通。","江流天地外，山色有無中。","郡邑浮前浦，波瀾動遠空。","襄陽好風日，留醉與山翁。"]', '["楚塞三湘接，荆门九派通。","江流天地外，山色有無中。","郡邑浮前浦，波瀾动远空。","襄陽好风日，留醉與山翁。"]', '诗', 'shi', '', NULL, '漢江臨汎 王維 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ea78eb6a-3e1f-4193-9ec0-974c12a4491a', '汎前陂', '汎前陂', '0a9829cc-805b-4812-a86a-1b2aee6a69ad', '唐', '["秋空自明迥，況復遠人間。","暢以沙際鶴，兼之雲外山。","澄波澹將夕，清月皓方閑。","此夜任孤櫂，夷猶殊未還。"]', '["秋空自明迥，況复远人间。","暢以沙際鹤，兼之云外山。","澄波澹將夕，清月皓方闲。","此夜任孤櫂，夷猶殊未還。"]', '诗', 'shi', '', NULL, '汎前陂 王維 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a7bedc82-2f58-414a-b3b3-c1576c1d4083', '登河北城樓作', '登河北城楼作', '0a9829cc-805b-4812-a86a-1b2aee6a69ad', '唐', '["井邑傅巖上，客亭雲霧間。","高城眺落日，極浦暎蒼山。","岸火孤舟宿，漁家夕鳥還。","寂寥天地暮，心與廣川閑。"]', '["井邑傅巖上，客亭云霧间。","高城眺落日，極浦暎蒼山。","岸火孤舟宿，漁家夕鸟還。","寂寥天地暮，心與廣川闲。"]', '诗', 'shi', '', NULL, '登河北城樓作 王維 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('92c0add0-13ab-4368-921a-721e16eda7db', '千塔主人', '千塔主人', '0a9829cc-805b-4812-a86a-1b2aee6a69ad', '唐', '["逆旅逢佳節，征帆未可前。","窗臨汴河水，門渡楚人船。","雞犬散墟落，桑榆蔭遠田。","所居人不見，枕席生雲煙。"]', '["逆旅逢佳節，征帆未可前。","窗臨汴河水，门渡楚人船。","雞犬散墟落，桑榆蔭远田。","所居人不见，枕席生云煙。"]', '诗', 'shi', '', NULL, '千塔主人 王維 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8ec59c80-46dc-4916-b069-a25ed8f144ec', '使至塞上', '使至塞上', '0a9829cc-805b-4812-a86a-1b2aee6a69ad', '唐', '["單車欲問邊，屬國過居延。","征蓬出漢塞，歸雁入胡天。","大漠孤煙直，長河落日圓。","蕭關逢候吏，都護在燕然。"]', '["單车欲问邊，屬国過居延。","征蓬出漢塞，归雁入胡天。","大漠孤煙直，长河落日圓。","蕭关逢候吏，都護在燕然。"]', '诗', 'shi', '', NULL, '使至塞上 王維 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8d9fabc0-2285-4a7d-84f0-c12f22b6d57b', '使至塞上', '使至塞上', '0a9829cc-805b-4812-a86a-1b2aee6a69ad', '唐', '["銜命辭天闕，單車欲問邊。","征蓬出漢塞，歸雁入胡天。","大漠孤煙直，長河落日圓。","蕭關逢候吏，都護在燕然。"]', '["銜命辞天闕，單车欲问邊。","征蓬出漢塞，归雁入胡天。","大漠孤煙直，长河落日圓。","蕭关逢候吏，都護在燕然。"]', '诗', 'shi', '', NULL, '使至塞上 王維 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('fba8b6f6-0707-4e45-a7f1-d8667adf4083', '晚春歸思', '晚春归思', '0a9829cc-805b-4812-a86a-1b2aee6a69ad', '唐', '["新妝可憐色，落日卷羅帷。","鑪氣清珍簟，牆陰上玉墀。","春蟲飛網戶，暮雀隱花枝。","向晚多愁思，閑窗桃李時。"]', '["新妝可怜色，落日卷羅帷。","鑪氣清珍簟，牆陰上玉墀。","春蟲飞網戶，暮雀隐花枝。","向晚多愁思，闲窗桃李时。"]', '诗', 'shi', '', NULL, '晚春歸思 王維 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('292c8f22-de30-4826-8ab0-29963317adbf', '戲題示蕭氏甥', '戲題示蕭氏甥', '0a9829cc-805b-4812-a86a-1b2aee6a69ad', '唐', '["憐爾解臨池，渠爺未學詩。","老夫何足似，弊宅倘因之。","蘆筍穿荷葉，菱花罥雁兒。","郗公不易勝，莫著外家欺。"]', '["怜爾解臨池，渠爺未学诗。","老夫何足似，弊宅倘因之。","蘆筍穿荷葉，菱花罥雁兒。","郗公不易勝，莫著外家欺。"]', '诗', 'shi', '', NULL, '戲題示蕭氏甥 王維 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c2320ab0-98b1-405f-bf9b-8a3774e793fc', '秋夜獨坐', '秋夜独坐', '0a9829cc-805b-4812-a86a-1b2aee6a69ad', '唐', '["獨坐悲雙鬢，空堂欲二更。","雨中山果落，燈下草蟲鳴。","白髮終難變，黃金不可成。","欲知除老病，唯有學無生。"]', '["独坐悲雙鬢，空堂欲二更。","雨中山果落，灯下草蟲鳴。","白髮終难变，黄金不可成。","欲知除老病，唯有学無生。"]', '诗', 'shi', '', NULL, '秋夜獨坐 王維 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7852c87b-2870-4e6d-be75-94d4c658e07c', '待儲光羲不至', '待儲光羲不至', '0a9829cc-805b-4812-a86a-1b2aee6a69ad', '唐', '["重門朝已啓，起坐聽車聲。","要欲聞清佩，方將出戶迎。","晚鐘鳴上苑，疎雨過春城。","了自不相顧，臨堂空復情。"]', '["重门朝已啓，起坐听车声。","要欲闻清佩，方將出戶迎。","晚鐘鳴上苑，疎雨過春城。","了自不相顧，臨堂空复情。"]', '诗', 'shi', '', NULL, '待儲光羲不至 王維 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9c9edd1a-6db7-4657-a804-02e0c2c75daa', '聽宮鶯', '听宮鶯', '0a9829cc-805b-4812-a86a-1b2aee6a69ad', '唐', '["春樹遶宮牆，宮鶯囀曙光。","忽驚啼暫斷，移處弄還長。","隱葉棲承露，攀花出未央。","遊人未應返，爲此始思鄉。"]', '["春樹遶宮牆，宮鶯囀曙光。","忽驚啼暫斷，移处弄還长。","隐葉棲承露，攀花出未央。","游人未應返，爲此始思乡。"]', '诗', 'shi', '', NULL, '聽宮鶯 王維 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2e7c3681-1817-45f3-b25b-ad027640e921', '雜詩', '杂诗', '0a9829cc-805b-4812-a86a-1b2aee6a69ad', '唐', '["雙燕初命子，五桃新作花。","王昌是東舍，宋玉次西家。","小小能織綺，時時出浣紗。","親勞使君問，南陌駐香車。"]', '["雙燕初命子，五桃新作花。","王昌是东舍，宋玉次西家。","小小能织綺，时时出浣紗。","親勞使君问，南陌駐香车。"]', '诗', 'shi', '', NULL, '雜詩 王維 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('daa10a71-7423-4830-96cf-8db885e4bbe5', '留別錢起', '留別錢起', '0a9829cc-805b-4812-a86a-1b2aee6a69ad', '唐', '["卑栖却得性，每與白雲歸。","徇祿仍懷橘，看山免採薇。","暮禽先去馬，新月待開扉。","霄漢時回首，知音青瑣闈。"]', '["卑栖却得性，每與白云归。","徇祿仍懷橘，看山免採薇。","暮禽先去马，新月待开扉。","霄漢时回首，知音青瑣闈。"]', '诗', 'shi', '', NULL, '留別錢起 王維 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f0327a66-a977-4c02-8f5d-df22f136603a', '留別丘爲', '留別丘爲', '0a9829cc-805b-4812-a86a-1b2aee6a69ad', '唐', '["歸鞍白雲外，繚繞出前山。","今日又明日，自知心不閑。","親勞簪組送，欲趂鶯花還。","一步一迴首，遲遲向近關。"]', '["归鞍白云外，繚繞出前山。","今日又明日，自知心不闲。","親勞簪組送，欲趂鶯花還。","一步一迴首，遲遲向近关。"]', '诗', 'shi', '', NULL, '留別丘爲 王維 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9875d4ea-304f-4fef-9f68-41c4bbb89e0a', '愚公谷三首 一', '愚公谷三首 一', '0a9829cc-805b-4812-a86a-1b2aee6a69ad', '唐', '["愚谷與誰去，唯將黎子同。","非須一處住，不那兩心空。","寧問春將夏，誰論西復東。","不知吾與子，若箇是愚公。"]', '["愚谷與誰去，唯將黎子同。","非須一处住，不那兩心空。","寧问春將夏，誰論西复东。","不知吾與子，若箇是愚公。"]', '诗', 'shi', '', NULL, '愚公谷三首 一 王維 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8be21612-23b0-4edb-8675-6ff0a5cb0b24', '愚公谷三首 二', '愚公谷三首 二', '0a9829cc-805b-4812-a86a-1b2aee6a69ad', '唐', '["吾家愚谷裏，此谷本來平。","雖則行無跡，還能響應聲。","不隨雲色暗，只待日光明。","緣底名愚谷，都由愚所成。"]', '["吾家愚谷裏，此谷本来平。","雖則行無跡，還能响應声。","不隨云色暗，只待日光明。","緣底名愚谷，都由愚所成。"]', '诗', 'shi', '', NULL, '愚公谷三首 二 王維 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('99a434dd-4a05-45a7-88d9-cc3bb92c8025', '愚公谷三首 三', '愚公谷三首 三', '0a9829cc-805b-4812-a86a-1b2aee6a69ad', '唐', '["借問愚公谷，與君聊一尋。","不尋翻到谷，此谷不離心。","行處曾無險，看時豈有深。","寄言塵世客，何處欲歸臨。"]', '["借问愚公谷，與君聊一尋。","不尋翻到谷，此谷不離心。","行处曾無險，看时豈有深。","寄言塵世客，何处欲归臨。"]', '诗', 'shi', '', NULL, '愚公谷三首 三 王維 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('721f092d-4087-411c-a29e-3ee51bf59e7e', '酬慕容十一', '酬慕容十一', '0a9829cc-805b-4812-a86a-1b2aee6a69ad', '唐', '["行行西陌返，駐幰問車公。","挾轂雙官騎，應門五尺僮。","老年如塞北，強起離牆東。","爲報壺丘子，來人道姓蒙。"]', '["行行西陌返，駐幰问车公。","挾轂雙官騎，應门五尺僮。","老年如塞北，強起離牆东。","爲報壺丘子，来人道姓蒙。"]', '诗', 'shi', '', NULL, '酬慕容十一 王維 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f7146947-bf34-4321-a154-e99b91de984c', '過始皇墓', '過始皇墓', '0a9829cc-805b-4812-a86a-1b2aee6a69ad', '唐', '["古墓成蒼嶺，幽宮象紫臺。","星辰七曜隔，河漢九泉開。","有海人寧渡，無春雁不廻。","更聞松韻切，疑是大夫哀。"]', '["古墓成蒼嶺，幽宮象紫台。","星辰七曜隔，河漢九泉开。","有海人寧渡，無春雁不廻。","更闻松韻切，疑是大夫哀。"]', '诗', 'shi', '', NULL, '過始皇墓 王維 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7e6ed758-443d-4266-a4f9-33a05d295be2', '恭懿太子挽歌五首 一', '恭懿太子挽歌五首 一', '0a9829cc-805b-4812-a86a-1b2aee6a69ad', '唐', '["何悟藏環早，纔知拜璧年。","翀天王子去，對日聖君憐。","樹轉宮猶出，笳悲馬不前。","雖蒙絕馳道，京兆別開阡。"]', '["何悟藏环早，纔知拜璧年。","翀天王子去，对日聖君怜。","樹轉宮猶出，笳悲马不前。","雖蒙絕驰道，京兆別开阡。"]', '诗', 'shi', '', NULL, '恭懿太子挽歌五首 一 王維 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8a9ef331-f84a-491a-b61b-2f913365bbc2', '恭懿太子挽歌五首 二', '恭懿太子挽歌五首 二', '0a9829cc-805b-4812-a86a-1b2aee6a69ad', '唐', '["蘭殿新恩切，椒宮夕臨幽。","白雲隨鳳管，明月在龍樓。","人向青山哭，天臨渭水愁。","雞鳴常問膳，今恨玉京留。"]', '["蘭殿新恩切，椒宮夕臨幽。","白云隨鳳管，明月在龙楼。","人向青山哭，天臨渭水愁。","雞鳴常问膳，今恨玉京留。"]', '诗', 'shi', '', NULL, '恭懿太子挽歌五首 二 王維 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('af6d46a3-23d7-4dcc-bc3f-a188098d5228', '恭懿太子挽歌五首 三', '恭懿太子挽歌五首 三', '0a9829cc-805b-4812-a86a-1b2aee6a69ad', '唐', '["騎吹凌霜發，旌旗夾路陳。","凱容金節護，冊命玉符新。","傅母悲香褓，君家擁畫輪。","射熊今夢帝，秤象問何人。"]', '["騎吹凌霜發，旌旗夾路陳。","凱容金節護，冊命玉符新。","傅母悲香褓，君家擁畫輪。","射熊今梦帝，秤象问何人。"]', '诗', 'shi', '', NULL, '恭懿太子挽歌五首 三 王維 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('649732ca-310d-4000-b6ca-299fc070468e', '恭懿太子挽歌五首 四', '恭懿太子挽歌五首 四', '0a9829cc-805b-4812-a86a-1b2aee6a69ad', '唐', '["蒼舒留帝寵，子晉有仙才。","五歲過人智，三天使鶴催。","心悲陽祿館，目斷望思臺。","若道長安近，何爲更不來。"]', '["蒼舒留帝寵，子晉有仙才。","五歲過人智，三天使鹤催。","心悲陽祿館，目斷望思台。","若道长安近，何爲更不来。"]', '诗', 'shi', '', NULL, '恭懿太子挽歌五首 四 王維 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ea79dfc0-f0e6-4323-9427-3d5569d006ab', '恭懿太子挽歌五首 五', '恭懿太子挽歌五首 五', '0a9829cc-805b-4812-a86a-1b2aee6a69ad', '唐', '["西望昆池闊，東瞻下杜平。","山朝豫章館，樹轉鳳凰城。","五校連旗色，千門疊鼓聲。","金環如有驗，還向畫堂生。"]', '["西望昆池闊，东瞻下杜平。","山朝豫章館，樹轉鳳凰城。","五校連旗色，千门叠鼓声。","金环如有驗，還向畫堂生。"]', '诗', 'shi', '', NULL, '恭懿太子挽歌五首 五 王維 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('74da7ff1-46dd-425a-b52d-9bff2a31332b', '故太子太師徐公挽歌四首 一', '故太子太師徐公挽歌四首 一', '0a9829cc-805b-4812-a86a-1b2aee6a69ad', '唐', '["功德冠羣英，彌綸有大名。","軒皇用風后，傅說是星精。","就第優遺老，來朝詔不名。","留侯常辟穀，何苦不長生。"]', '["功德冠羣英，彌綸有大名。","軒皇用风后，傅说是星精。","就第優遺老，来朝詔不名。","留侯常辟穀，何苦不长生。"]', '诗', 'shi', '', NULL, '故太子太師徐公挽歌四首 一 王維 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ce798dc5-d0ff-458d-8d4b-6723ff5f497d', '故太子太師徐公挽歌四首 二', '故太子太師徐公挽歌四首 二', '0a9829cc-805b-4812-a86a-1b2aee6a69ad', '唐', '["謀猷爲相國，翊戴奉宸輿。","劒履升前殿，貂蟬託後車。","齊侯疏土宇，漢室賴圖書。","僻處留田宅，仍纔十頃餘。"]', '["謀猷爲相国，翊戴奉宸輿。","劒履升前殿，貂蟬託後车。","齊侯疏土宇，漢室賴圖书。","僻处留田宅，仍纔十頃餘。"]', '诗', 'shi', '', NULL, '故太子太師徐公挽歌四首 二 王維 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4e1e5489-c5f8-4486-ab8e-f89fef41c9dc', '故太子太師徐公挽歌四首 三', '故太子太師徐公挽歌四首 三', '0a9829cc-805b-4812-a86a-1b2aee6a69ad', '唐', '["舊里趨庭日，新年置酒辰。","聞詩鸞渚客，獻賦鳳樓人。","北首辭明主，東堂哭大臣。","猶思御朱輅，不惜[汙]車茵。"]', '["旧里趨庭日，新年置酒辰。","闻诗鸾渚客，獻賦鳳楼人。","北首辞明主，东堂哭大臣。","猶思御朱輅，不惜[汙]车茵。"]', '诗', 'shi', '', NULL, '故太子太師徐公挽歌四首 三 王維 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4dcba919-7a6d-4d13-b3a4-bf84d63d840a', '故太子太師徐公挽歌四首 四', '故太子太師徐公挽歌四首 四', '0a9829cc-805b-4812-a86a-1b2aee6a69ad', '唐', '["久踐中台座，終登上將壇。","誰言斷車騎，空憶盛衣冠。","風日咸陽慘，笳簫渭水寒。","無人當便闕，應罷太師官。"]', '["久踐中台座，終登上將壇。","誰言斷车騎，空憶盛衣冠。","风日咸陽慘，笳簫渭水寒。","無人當便闕，應罷太師官。"]', '诗', 'shi', '', NULL, '故太子太師徐公挽歌四首 四 王維 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3cc058ac-75ae-429f-a5c4-9a2821158574', '故西河郡杜太守挽歌三首 一', '故西河郡杜太守挽歌三首 一', '0a9829cc-805b-4812-a86a-1b2aee6a69ad', '唐', '["天上去西征，雲中護北平。","生擒白馬將，連破黑鵰城。","忽見芻靈苦，徒聞竹使榮。","空留左氏傳，誰繼卜商名。"]', '["天上去西征，云中護北平。","生擒白马將，連破黑鵰城。","忽见芻靈苦，徒闻竹使榮。","空留左氏傳，誰繼卜商名。"]', '诗', 'shi', '', NULL, '故西河郡杜太守挽歌三首 一 王維 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3688e0ff-705f-4319-b147-9a30bf7cd064', '故西河郡杜太守挽歌三首 二', '故西河郡杜太守挽歌三首 二', '0a9829cc-805b-4812-a86a-1b2aee6a69ad', '唐', '["返葬金符守，同歸石窌妻。","卷衣悲畫翟，持翣待鳴雞。","容衞都人慘，山川駟馬嘶。","猶聞隴上客，相對哭征西。"]', '["返葬金符守，同归石窌妻。","卷衣悲畫翟，持翣待鳴雞。","容衞都人慘，山川駟马嘶。","猶闻隴上客，相对哭征西。"]', '诗', 'shi', '', NULL, '故西河郡杜太守挽歌三首 二 王維 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('34227689-02b7-4228-a8c3-6ab9598fd3e4', '故西河郡杜太守挽歌三首 三', '故西河郡杜太守挽歌三首 三', '0a9829cc-805b-4812-a86a-1b2aee6a69ad', '唐', '["塗芻去國門，祕器出東園。","太守留金印，夫人罷錦軒。","旌旗轉衰木，簫鼓上寒原。","墳樹應西靡，長思魏闕恩。"]', '["塗芻去国门，祕器出东园。","太守留金印，夫人罷錦軒。","旌旗轉衰木，簫鼓上寒原。","墳樹應西靡，长思魏闕恩。"]', '诗', 'shi', '', NULL, '故西河郡杜太守挽歌三首 三 王維 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('aff8ddda-07ac-45a4-8305-419bc0c6ec35', '故南陽夫人樊氏挽歌', '故南陽夫人樊氏挽歌', '0a9829cc-805b-4812-a86a-1b2aee6a69ad', '唐', '["錦衣餘翟茀，繡轂罷魚軒。","淑女詩長在，夫人法尚存。","凝笳隨曉斾，行哭向秋原。","歸去將何見，誰能返戟門。"]', '["錦衣餘翟茀，繡轂罷鱼軒。","淑女诗长在，夫人法尚存。","凝笳隨晓斾，行哭向秋原。","归去將何见，誰能返戟门。"]', '诗', 'shi', '', NULL, '故南陽夫人樊氏挽歌 王維 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('02875e90-84dc-47cf-81cd-edc3377d5a66', '達奚侍郎夫人寇氏挽詞二首 一', '達奚侍郎夫人寇氏挽词二首 一', '0a9829cc-805b-4812-a86a-1b2aee6a69ad', '唐', '["束帶將朝日，鳴環映牖辰。","能令諫明主，相勸識賢人。","遺挂空留壁，廻文日覆塵。"]', '["束带將朝日，鳴环映牖辰。","能令諫明主，相勸識賢人。","遺挂空留壁，廻文日覆塵。"]', '诗', 'shi', '', NULL, '達奚侍郎夫人寇氏挽詞二首 一 王維 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6ac17fcb-2c1d-4508-a632-89c7c8f54ada', '達奚侍郎夫人寇氏挽詞二首 二', '達奚侍郎夫人寇氏挽词二首 二', '0a9829cc-805b-4812-a86a-1b2aee6a69ad', '唐', '["女史悲彤管，夫人罷錦軒。","卜塋占二室，行哭度千門。","秋日光能淡，寒川波自翻。","一朝成萬古，松柏暗平原。"]', '["女史悲彤管，夫人罷錦軒。","卜塋占二室，行哭度千门。","秋日光能淡，寒川波自翻。","一朝成万古，松柏暗平原。"]', '诗', 'shi', '', NULL, '達奚侍郎夫人寇氏挽詞二首 二 王維 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('153323dd-8a38-45a0-a2c8-f687152e5ed5', '送孫秀才', '送孫秀才', '0a9829cc-805b-4812-a86a-1b2aee6a69ad', '唐', '["帝城風日好，況復建平家。","玉枕雙文簟，金盤五色瓜。","山中無魯酒，松下飯胡麻。","莫厭田家苦，歸期遠復賒。"]', '["帝城风日好，況复建平家。","玉枕雙文簟，金盤五色瓜。","山中無魯酒，松下飯胡麻。","莫厭田家苦，归期远复賒。"]', '诗', 'shi', '', NULL, '送孫秀才 王維 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1c48c29a-98fd-41d7-a8c4-758015a12af1', '奉和聖製慶玄元皇帝玉像之作應制', '奉和聖製慶玄元皇帝玉像之作應制', '0a9829cc-805b-4812-a86a-1b2aee6a69ad', '唐', '["明君夢帝先，寶命上齊天。","秦后徒聞樂，周王恥卜年。","玉京移大像，金籙會羣仙。","承露調天供，臨空敞御筵。","斗廻迎壽酒，山近起鑪煙。","願奉無爲化，齋心學自然。"]', '["明君梦帝先，寶命上齊天。","秦后徒闻乐，周王恥卜年。","玉京移大像，金籙會羣仙。","承露調天供，臨空敞御筵。","斗廻迎壽酒，山近起鑪煙。","願奉無爲化，斋心学自然。"]', '诗', 'shi', '', NULL, '奉和聖製慶玄元皇帝玉像之作應制 王維 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('13a6108b-14b9-4a92-9f12-5445f794814b', '奉和聖製與太子諸王三月三日龍池春禊應制', '奉和聖製與太子諸王三月三日龙池春禊應制', '0a9829cc-805b-4812-a86a-1b2aee6a69ad', '唐', '["故事修春禊，新宮展豫遊。","明君移鳳輦，太子出龍樓。","賦掩陳王作，桮如洛水流。","金人來捧劒，畫鷁去回舟。","苑樹浮宮闕，天池照冕旒。","宸章在雲表，垂象滿皇州。"]', '["故事修春禊，新宮展豫游。","明君移鳳輦，太子出龙楼。","賦掩陳王作，桮如洛水流。","金人来捧劒，畫鷁去回舟。","苑樹浮宮闕，天池照冕旒。","宸章在云表，垂象满皇州。"]', '诗', 'shi', '', NULL, '奉和聖製與太子諸王三月三日龍池春禊應制 王維 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('619ac57c-25f0-4f6d-84f2-1319ecfabfaf', '奉和聖製上巳於望春亭觀禊飲應制', '奉和聖製上巳於望春亭观禊饮應制', '0a9829cc-805b-4812-a86a-1b2aee6a69ad', '唐', '["長樂青門外，宜春小苑東。","樓開萬井上，輦過百花中。","畫鷁移仙妓，金貂列上公。","清歌邀落日，妙舞向春風。","渭水明秦甸，黃山入漢宮。","君王來祓禊，灞滻亦朝宗。"]', '["长乐青门外，宜春小苑东。","楼开万井上，輦過百花中。","畫鷁移仙妓，金貂列上公。","清歌邀落日，妙舞向春风。","渭水明秦甸，黄山入漢宮。","君王来祓禊，灞滻亦朝宗。"]', '诗', 'shi', '', NULL, '奉和聖製上巳於望春亭觀禊飲應制 王維 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5f58d6b2-6a7c-4563-869c-46713cd2d196', '奉和聖製暮春送朝集使歸郡應制', '奉和聖製暮春送朝集使归郡應制', '0a9829cc-805b-4812-a86a-1b2aee6a69ad', '唐', '["萬國仰宗周，衣冠拜冕旒。","玉乘迎大客，金節送諸侯。","祖席傾三省，褰帷向九州。","楊花飛上路，槐色蔭通溝。","來預鈞天樂，歸分漢主憂。","宸章類河漢，垂象滿中州。"]', '["万国仰宗周，衣冠拜冕旒。","玉乘迎大客，金節送諸侯。","祖席傾三省，褰帷向九州。","楊花飞上路，槐色蔭通溝。","来預鈞天乐，归分漢主憂。","宸章類河漢，垂象满中州。"]', '诗', 'shi', '', NULL, '奉和聖製暮春送朝集使歸郡應制 王維 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c8684b9f-6eb9-40db-9cbf-bd87fb3dee50', '三月三日曲江侍宴應制', '三月三日曲江侍宴應制', '0a9829cc-805b-4812-a86a-1b2aee6a69ad', '唐', '["萬乘親齋祭，千官喜豫遊。","奉迎從上苑，祓禊向中流。","草樹連容衞，山河對冕旒。","畫旗搖浦漵，春服滿汀洲。","仙籞龍媒下，神臯鳳蹕留。","從今億萬歲，天寶紀春秋。"]', '["万乘親斋祭，千官喜豫游。","奉迎從上苑，祓禊向中流。","草樹連容衞，山河对冕旒。","畫旗搖浦漵，春服满汀洲。","仙籞龙媒下，神臯鳳蹕留。","從今億万歲，天寶紀春秋。"]', '诗', 'shi', '', NULL, '三月三日曲江侍宴應制 王維 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a1001ba3-9f0f-405b-b837-ad0014601838', '奉和聖製重陽節宰臣及羣官上壽應制', '奉和聖製重陽節宰臣及羣官上壽應制', '0a9829cc-805b-4812-a86a-1b2aee6a69ad', '唐', '["四海方無事，三秋大有年。","百生無此日，萬壽願齊天。","芍藥和金鼎，茱萸插玳筵。","玉堂開右个，天樂動宮懸。","御柳疎秋景，城鴉拂曙煙。","無窮菊花節，長奉柏梁篇。"]', '["四海方無事，三秋大有年。","百生無此日，万壽願齊天。","芍藥和金鼎，茱萸插玳筵。","玉堂开右个，天乐动宮懸。","御柳疎秋景，城鴉拂曙煙。","無窮菊花節，长奉柏梁篇。"]', '诗', 'shi', '', NULL, '奉和聖製重陽節宰臣及羣官上壽應制 王維 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8930cd67-9812-429b-86c0-1278d91b2c08', '三月三日勤政樓侍宴應制', '三月三日勤政楼侍宴應制', '0a9829cc-805b-4812-a86a-1b2aee6a69ad', '唐', '["綵仗連宵合，瓊樓拂曙通。","年光三月裏，宮殿百花中。","不數秦王日，誰將洛水同。","酒筵嫌落絮，舞袖怯春風。","天保無爲德，人歡不戰功。","仍臨九衢宴，更達四門聰。"]', '["綵仗連宵合，瓊楼拂曙通。","年光三月裏，宮殿百花中。","不數秦王日，誰將洛水同。","酒筵嫌落絮，舞袖怯春风。","天保無爲德，人歡不戰功。","仍臨九衢宴，更達四门聰。"]', '诗', 'shi', '', NULL, '三月三日勤政樓侍宴應制 王維 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a195930e-c593-46ba-83a3-695da669f5aa', '奉和聖製十五夜然燈繼以酺宴應制', '奉和聖製十五夜然灯繼以酺宴應制', '0a9829cc-805b-4812-a86a-1b2aee6a69ad', '唐', '["上路笙歌滿，春城漏刻長。","遊人多晝日，明月讓燈光。","魚鑰通翔鳳，龍輿出建章。","九衢陳廣樂，百福透名香。","仙伎來金殿，都人遶玉堂。","定應偷妙舞，從此學新妝。","奉引迎三事，司儀列萬方。","願將天地壽，同以獻君王。"]', '["上路笙歌满，春城漏刻长。","游人多晝日，明月讓灯光。","鱼鑰通翔鳳，龙輿出建章。","九衢陳廣乐，百福透名香。","仙伎来金殿，都人遶玉堂。","定應偷妙舞，從此学新妝。","奉引迎三事，司儀列万方。","願將天地壽，同以獻君王。"]', '诗', 'shi', '', NULL, '奉和聖製十五夜然燈繼以酺宴應制 王維 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('46088148-cd2f-42f5-aa17-1499e658a3ca', '奉和聖製幸玉真公主山莊因題石壁十韻之作應制', '奉和聖製幸玉真公主山莊因題石壁十韻之作應制', '0a9829cc-805b-4812-a86a-1b2aee6a69ad', '唐', '["碧落風煙外，瑤臺道路賒。","如何連帝苑，別自有仙家。","此地回鸞駕，緣谿轉翠華。","洞中開日月，窗裏發雲霞。","庭養沖天鶴，溪流上漢查。","種田生白玉，泥竈化丹砂。","谷靜泉逾響，山深日易斜。","御羹和石髓，香飯進胡麻。","大道今無外，長生詎有涯。","還瞻九霄上，來往五雲車。"]', '["碧落风煙外，瑤台道路賒。","如何連帝苑，別自有仙家。","此地回鸾駕，緣谿轉翠华。","洞中开日月，窗裏發云霞。","庭養沖天鹤，溪流上漢查。","種田生白玉，泥竈化丹砂。","谷静泉逾响，山深日易斜。","御羹和石髓，香飯進胡麻。","大道今無外，长生詎有涯。","還瞻九霄上，来往五云车。"]', '诗', 'shi', '', NULL, '奉和聖製幸玉真公主山莊因題石壁十韻之作應制 王維 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('27d4ad2d-99e7-47d0-bef4-6644d8e30f3e', '春日直門下省早朝', '春日直门下省早朝', '0a9829cc-805b-4812-a86a-1b2aee6a69ad', '唐', '["騎省直明光，雞鳴謁建章。","遙聞侍中珮，闇識令君香。","玉漏隨銅史，天書拜夕郎。","旌旗暎閶闔，歌吹滿昭陽。","官舍梅初紫，宮門柳欲黃。","願將遲日意，同與聖恩長。"]', '["騎省直明光，雞鳴謁建章。","遙闻侍中珮，闇識令君香。","玉漏隨銅史，天书拜夕郎。","旌旗暎閶闔，歌吹满昭陽。","官舍梅初紫，宮门柳欲黄。","願將遲日意，同與聖恩长。"]', '诗', 'shi', '', NULL, '春日直門下省早朝 王維 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ed02514c-ebc4-4324-97c6-c7381edf7271', '和僕射晉公扈從溫湯', '和僕射晉公扈從溫湯', '0a9829cc-805b-4812-a86a-1b2aee6a69ad', '唐', '["天子幸新豐，旌旗渭水東。","寒山天仗外，溫谷幔城中。","奠玉羣仙座，焚香太乙宮。","出遊逢牧馬，罷獵見非熊。","上宰無爲化，明時太古同。","靈芝三秀紫，陳粟萬箱紅。","王禮奠儒教，天兵小戰功。","謀猶歸哲匠，詞賦屬文宗。","司諫方無闕，陳詩且未工。","長吟吉甫頌，朝夕仰清風。"]', '["天子幸新豐，旌旗渭水东。","寒山天仗外，溫谷幔城中。","奠玉羣仙座，焚香太乙宮。","出游逢牧马，罷獵见非熊。","上宰無爲化，明时太古同。","靈芝三秀紫，陳粟万箱紅。","王禮奠儒教，天兵小戰功。","謀猶归哲匠，词賦屬文宗。","司諫方無闕，陳诗且未工。","长吟吉甫頌，朝夕仰清风。"]', '诗', 'shi', '', NULL, '和僕射晉公扈從溫湯 王維 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ad472842-1792-451c-826d-311acb8d8b21', '和宋中丞夏日遊福賢觀天長寺寺即陳左相宅所施之作', '和宋中丞夏日游福賢观天长寺寺即陳左相宅所施之作', '0a9829cc-805b-4812-a86a-1b2aee6a69ad', '唐', '["已相殷王國，空餘尚父谿。","釣磯開月殿，築道出雲梯。","積水浮香象，深山鳴白雞。","虛空陳伎樂，衣服製虹霓。","墨點三千界，丹飛六一泥。","桃源勿遽返，再訪恐君迷。"]', '["已相殷王国，空餘尚父谿。","釣磯开月殿，築道出云梯。","積水浮香象，深山鳴白雞。","虛空陳伎乐，衣服製虹霓。","墨点三千界，丹飞六一泥。","桃源勿遽返，再訪恐君迷。"]', '诗', 'shi', '', NULL, '和宋中丞夏日遊福賢觀天長寺寺即陳左相宅所施之作 王維 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1ff40801-4e65-4862-9a7c-f0315445d357', '和陳監四郎秋雨中思從弟據', '和陳監四郎秋雨中思從弟據', '0a9829cc-805b-4812-a86a-1b2aee6a69ad', '唐', '["嫋嫋秋風動，淒淒煙雨繁。","聲連鳷鵲觀，色暗鳳凰原。","細柳疎高閣，輕槐落洞門。","九衢行欲斷，萬井寂無喧。","忽有愁霖唱，更陳多露言。","平原思令弟，康樂謝賢昆。","逸興方三接，衰顏強七奔。","相如今老病，歸守茂陵園。"]', '["嫋嫋秋风动，淒淒煙雨繁。","声連鳷鵲观，色暗鳳凰原。","細柳疎高閣，轻槐落洞门。","九衢行欲斷，万井寂無喧。","忽有愁霖唱，更陳多露言。","平原思令弟，康乐謝賢昆。","逸兴方三接，衰顏強七奔。","相如今老病，归守茂陵园。"]', '诗', 'shi', '', NULL, '和陳監四郎秋雨中思從弟據 王維 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b55431ec-7de2-4f5a-86e1-79103eabe5bc', '上張令公', '上張令公', '0a9829cc-805b-4812-a86a-1b2aee6a69ad', '唐', '["珥筆趨丹陛，垂璫上玉除。","步檐青瑣闥，方幰畫輪車。","市閱千金字，朝聞五色書。","致君光帝典，薦士滿公車。","伏奏回金駕，橫經重石渠。","從茲罷角觝，且復幸儲胥。","天統知堯後，王章笑魯初。","匈奴遙俯伏，漢相儼簪裾。","賈生非不遇，汲黯自堪疎。","學易思求我，言詩或起予。","當從大夫後，何惜隸人餘。"]', '["珥笔趨丹陛，垂璫上玉除。","步檐青瑣闥，方幰畫輪车。","市閱千金字，朝闻五色书。","致君光帝典，薦士满公车。","伏奏回金駕，橫經重石渠。","從茲罷角觝，且复幸儲胥。","天統知堯後，王章笑魯初。","匈奴遙俯伏，漢相儼簪裾。","賈生非不遇，汲黯自堪疎。","学易思求我，言诗或起予。","當從大夫後，何惜隸人餘。"]', '诗', 'shi', '', NULL, '上張令公 王維 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('311e0be8-6a88-4869-a44a-25bce2030cbf', '贈焦道士', '贈焦道士', '0a9829cc-805b-4812-a86a-1b2aee6a69ad', '唐', '["海上遊三島，淮南預八公。","坐知千里外，跳向一壺中。","縮地朝珠闕，行天使玉童。","飲人聊割酒，送客乍分風。","天老能行氣，吾師不養空。","謝君徒雀躍，無可問鴻濛。"]', '["海上游三島，淮南預八公。","坐知千里外，跳向一壺中。","縮地朝珠闕，行天使玉童。","饮人聊割酒，送客乍分风。","天老能行氣，吾師不養空。","謝君徒雀躍，無可问鴻濛。"]', '诗', 'shi', '', NULL, '贈焦道士 王維 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2348b914-3a21-4d5b-ac83-79d4da3071b1', '贈東嶽焦鍊師', '贈东嶽焦鍊師', '0a9829cc-805b-4812-a86a-1b2aee6a69ad', '唐', '["先生千歲餘，五嶽遍曾居。","遙識齊侯鼎，新過王母廬。","不能師孔墨，何事問長沮。","玉管時來鳳，銅盤即釣魚。","竦身空裏語，明目夜中書。","自有還丹術，時論太素初。","頻蒙露版詔，時降軟輪車。","山靜泉逾響，松高枝轉疎。","搘頤問樵客，世上復何如。"]', '["先生千歲餘，五嶽遍曾居。","遙識齊侯鼎，新過王母廬。","不能師孔墨，何事问长沮。","玉管时来鳳，銅盤即釣鱼。","竦身空裏語，明目夜中书。","自有還丹術，时論太素初。","頻蒙露版詔，时降軟輪车。","山静泉逾响，松高枝轉疎。","搘頤问樵客，世上复何如。"]', '诗', 'shi', '', NULL, '贈東嶽焦鍊師 王維 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f8854216-82aa-41a8-84ae-39b3ddd2d999', '送祕書晁監還日本國', '送祕书晁監還日本国', '0a9829cc-805b-4812-a86a-1b2aee6a69ad', '唐', '["積水不可極，安知滄海東。","九州何處遠，萬里若乘空。","向國唯看日，歸帆但信風。","鰲身暎天黑，魚眼射波紅。","鄉樹扶桑外，主人孤島中。","別離方異域，音信若爲通。"]', '["積水不可極，安知滄海东。","九州何处远，万里若乘空。","向国唯看日，归帆但信风。","鰲身暎天黑，鱼眼射波紅。","乡樹扶桑外，主人孤島中。","別離方異域，音信若爲通。"]', '诗', 'shi', '', NULL, '送祕書晁監還日本國 王維 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d7f08677-8042-4aff-98dd-d5381a58163a', '送禰郎中', '送禰郎中', '0a9829cc-805b-4812-a86a-1b2aee6a69ad', '唐', '["東郊春草色，驅馬去悠悠。","況復鄉山外，猿啼湘水流。","島夷傳露版，江館候鳴騶。","卉服爲諸吏，珠官拜本州。","孤鸎吟遠墅，野杏發山郵。","早晚方歸奏，南中纔忌秋。"]', '["东郊春草色，驱马去悠悠。","況复乡山外，猿啼湘水流。","島夷傳露版，江館候鳴騶。","卉服爲諸吏，珠官拜本州。","孤鸎吟远墅，野杏發山郵。","早晚方归奏，南中纔忌秋。"]', '诗', 'shi', '', NULL, '送禰郎中 王維 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a886fd41-799c-46e4-993f-205f9963d008', '送李太守赴上洛', '送李太守赴上洛', '0a9829cc-805b-4812-a86a-1b2aee6a69ad', '唐', '["商山包楚鄧，積翠藹沈沈。","驛路飛泉灑，關門落照深。","野花開古戍，行客響空林。","板屋春多雨，山城晝欲陰。","丹泉通虢略，白羽抵荆岑。","若見西山爽，應知黃綺心。"]', '["商山包楚鄧，積翠藹沈沈。","驛路飞泉灑，关门落照深。","野花开古戍，行客响空林。","板屋春多雨，山城晝欲陰。","丹泉通虢略，白羽抵荆岑。","若见西山爽，應知黄綺心。"]', '诗', 'shi', '', NULL, '送李太守赴上洛 王維 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0b572a44-2a64-4b87-9961-edaf9fdc2f75', '送熊九赴任安陽', '送熊九赴任安陽', '0a9829cc-805b-4812-a86a-1b2aee6a69ad', '唐', '["魏國應劉後，寂寥文雅空。","漳河如舊日，之子繼清風。","阡陌銅臺下，閭閻金虎中。","送車盈灞上，輕騎出關東。","相去千餘里，西園明月同。"]', '["魏国應劉後，寂寥文雅空。","漳河如旧日，之子繼清风。","阡陌銅台下，閭閻金虎中。","送车盈灞上，轻騎出关东。","相去千餘里，西园明月同。"]', '诗', 'shi', '', NULL, '送熊九赴任安陽 王維 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1c55121d-027e-4f20-a99d-fa2e7e7ef03c', '山中示弟', '山中示弟', '0a9829cc-805b-4812-a86a-1b2aee6a69ad', '唐', '["山林吾喪我，冠帶爾成人。","莫學嵇康懶，且安原憲貧。","山陰多北戶，泉水在東鄰。","緣合妄相有，性空無所親。","安知廣成子，不是老夫身。"]', '["山林吾喪我，冠带爾成人。","莫学嵇康懶，且安原憲貧。","山陰多北戶，泉水在东鄰。","緣合妄相有，性空無所親。","安知廣成子，不是老夫身。"]', '诗', 'shi', '', NULL, '山中示弟 王維 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('506d9295-9855-4fe2-9c8b-d459ccb95a63', '青龍寺曇璧上人兄院集', '青龙寺曇璧上人兄院集', '0a9829cc-805b-4812-a86a-1b2aee6a69ad', '唐', '["高處敞招提，虛空詎有倪。","坐看南陌騎，下聽秦城雞。","眇眇孤煙起，芊芊遠樹齊。","青山萬井外，落日五陵西。","眼界今無染，心空安可迷。"]', '["高处敞招提，虛空詎有倪。","坐看南陌騎，下听秦城雞。","眇眇孤煙起，芊芊远樹齊。","青山万井外，落日五陵西。","眼界今無染，心空安可迷。"]', '诗', 'shi', '', NULL, '青龍寺曇璧上人兄院集 王維 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('972307bb-ce93-4a37-aae3-f548363da1a8', '濟州過趙叟家宴', '濟州過趙叟家宴', '0a9829cc-805b-4812-a86a-1b2aee6a69ad', '唐', '["雖與人境接，閉門成隱居。","道言莊叟事，儒行魯人餘。","深巷斜暉靜，閑門高柳疎。","荷鋤修藥圃，散帙曝農書。","上客搖芳翰，中廚饋野蔬。","夫君第高飲，景晏出林閭。"]', '["雖與人境接，閉门成隐居。","道言莊叟事，儒行魯人餘。","深巷斜暉静，闲门高柳疎。","荷鋤修藥圃，散帙曝農书。","上客搖芳翰，中廚饋野蔬。","夫君第高饮，景晏出林閭。"]', '诗', 'shi', '', NULL, '濟州過趙叟家宴 王維 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('20fd7a4d-5374-4023-a410-b4bac9aec316', '春過賀遂員外藥園', '春過賀遂員外藥园', '0a9829cc-805b-4812-a86a-1b2aee6a69ad', '唐', '["前年槿籬故，新作藥欄成。","香草爲君子，名花是長卿。","水穿盤石透，藤繫古松生。","畫畏開廚走，來蒙到屣迎。","蔗漿菰米飯，蒟醬露葵羹。","頗識灌園意，於陵不自輕。"]', '["前年槿籬故，新作藥欄成。","香草爲君子，名花是长卿。","水穿盤石透，藤繫古松生。","畫畏开廚走，来蒙到屣迎。","蔗漿菰米飯，蒟醬露葵羹。","頗識灌园意，於陵不自轻。"]', '诗', 'shi', '', NULL, '春過賀遂員外藥園 王維 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5f315492-8086-4bbd-9249-8bc4c7bc06bf', '過盧四員外宅看飯僧共題七韻', '過盧四員外宅看飯僧共題七韻', '0a9829cc-805b-4812-a86a-1b2aee6a69ad', '唐', '["三賢異七賢，青眼慕青蓮。","乞飯從香積，裁衣學水田。","上人飛錫杖，檀越施金錢。","趺作檐前日，焚香竹下煙。","寒空法雲地，秋色淨居天。","身逐因緣法，心過次第禪。","不須愁日暮，自有一燈然。"]', '["三賢異七賢，青眼慕青蓮。","乞飯從香積，裁衣学水田。","上人飞錫杖，檀越施金錢。","趺作檐前日，焚香竹下煙。","寒空法云地，秋色淨居天。","身逐因緣法，心過次第禪。","不須愁日暮，自有一灯然。"]', '诗', 'shi', '', NULL, '過盧四員外宅看飯僧共題七韻 王維 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('fc0d15fb-1479-47a0-a82e-9ca99e5f26de', '河南嚴尹弟見宿弊廬訪別人賦十韻', '河南嚴尹弟见宿弊廬訪別人賦十韻', '0a9829cc-805b-4812-a86a-1b2aee6a69ad', '唐', '["上客能論道，吾生學養蒙。","貧交世情外，才子古人中。","冠上方簪豸，車邊已畫熊。","拂衣迎五馬，垂手憑雙童。","花醥和松屑，茶香透竹叢。","薄霜澄夜月，殘雪帶春風。","古壁蒼苔黑，寒山遠燒紅。","眼看東候別，心事北川同。","爲學輕先輩，何能訪老翁。","欲知今日後，不樂爲車公。"]', '["上客能論道，吾生学養蒙。","貧交世情外，才子古人中。","冠上方簪豸，车邊已畫熊。","拂衣迎五马，垂手憑雙童。","花醥和松屑，茶香透竹叢。","薄霜澄夜月，殘雪带春风。","古壁蒼苔黑，寒山远燒紅。","眼看东候別，心事北川同。","爲学轻先輩，何能訪老翁。","欲知今日後，不乐爲车公。"]', '诗', 'shi', '', NULL, '河南嚴尹弟見宿弊廬訪別人賦十韻 王維 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c710c26f-cd79-4723-be6f-29aa96aa5359', '投道一師蘭若宿', '投道一師蘭若宿', '0a9829cc-805b-4812-a86a-1b2aee6a69ad', '唐', '["一公棲太白，高頂出風煙。","梵流諸壑遍，花雨一峰偏。","跡爲無心隱，名因立教傳。","鳥來還語法，客去更安禪。","晝涉松路盡，暮投蘭若邊。","洞房隱深竹，清夜聞遙泉。","向是雲霞裏，今成枕席前。","豈唯暫留宿，服事將窮年。"]', '["一公棲太白，高頂出风煙。","梵流諸壑遍，花雨一峰偏。","跡爲無心隐，名因立教傳。","鸟来還語法，客去更安禪。","晝涉松路尽，暮投蘭若邊。","洞房隐深竹，清夜闻遙泉。","向是云霞裏，今成枕席前。","豈唯暫留宿，服事將窮年。"]', '诗', 'shi', '', NULL, '投道一師蘭若宿 王維 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4bf5acf2-6ad4-478d-a43a-1f8ef0bf7753', '遊感化寺', '游感化寺', '0a9829cc-805b-4812-a86a-1b2aee6a69ad', '唐', '["翡翠香煙合，琉璃寶地平。","龍宮連棟宇，虎穴傍檐楹。","谷靜唯松響，山深無鳥聲。","瓊峰當戶拆，金澗透林明。","郢路雲端逈，秦川雨外晴。","鴈王銜果獻，鹿女踏花行。","抖擻辭貧里，歸依宿化城。","繞籬生野蕨，空館發山櫻。","香飯青菰米，嘉蔬綠笋莖。","誓陪清梵末，端坐學無生。"]', '["翡翠香煙合，琉璃寶地平。","龙宮連棟宇，虎穴傍檐楹。","谷静唯松响，山深無鸟声。","瓊峰當戶拆，金澗透林明。","郢路云端逈，秦川雨外晴。","鴈王銜果獻，鹿女踏花行。","抖擻辞貧里，归依宿化城。","繞籬生野蕨，空館發山櫻。","香飯青菰米，嘉蔬綠笋莖。","誓陪清梵末，端坐学無生。"]', '诗', 'shi', '', NULL, '遊感化寺 王維 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d39f419a-021e-401f-b79d-d6964815d6bc', '遊悟真寺', '游悟真寺', '0a9829cc-805b-4812-a86a-1b2aee6a69ad', '唐', '["聞道黃金地，仍開白玉田。","擲山移巨石，呪嶺出飛泉。","猛虎同三逕，愁猿學四禪。","買香然綠桂，乞火踏紅蓮。","草色搖霞上，松聲汎月邊。","山河窮百二，世界接三千。","梵宇聊憑視，王城遂渺然。","灞陵纔出樹，渭水欲連天。","遠縣分諸郭，孤村起白煙。","望雲思聖主，披霧隱羣賢。","薄宦慚尸素，終身擬尚玄。","誰知草菴客，曾和柏梁篇。"]', '["闻道黄金地，仍开白玉田。","擲山移巨石，呪嶺出飞泉。","猛虎同三逕，愁猿学四禪。","買香然綠桂，乞火踏紅蓮。","草色搖霞上，松声汎月邊。","山河窮百二，世界接三千。","梵宇聊憑視，王城遂渺然。","灞陵纔出樹，渭水欲連天。","远縣分諸郭，孤村起白煙。","望云思聖主，披霧隐羣賢。","薄宦慚尸素，終身擬尚玄。","誰知草菴客，曾和柏梁篇。"]', '诗', 'shi', '', NULL, '遊悟真寺 王維 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2982d4a8-9d3b-40e3-bfac-8958d2f3b70e', '與蘇盧二員外期遊方丈寺而蘇不至因有是作', '與蘇盧二員外期游方丈寺而蘇不至因有是作', '0a9829cc-805b-4812-a86a-1b2aee6a69ad', '唐', '["共仰頭陀行，能忘世諦情。","回看雙鳳闕，相去一牛鳴。","法向空林說，心隨寶地平。","手巾花氎淨，香帔稻畦成。","聞道邀同舍，相期宿化城。","安知不來往，翻得似無生。"]', '["共仰头陀行，能忘世諦情。","回看雙鳳闕，相去一牛鳴。","法向空林说，心隨寶地平。","手巾花氎淨，香帔稻畦成。","闻道邀同舍，相期宿化城。","安知不来往，翻得似無生。"]', '诗', 'shi', '', NULL, '與蘇盧二員外期遊方丈寺而蘇不至因有是作 王維 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1811e946-63d4-4ddd-b580-2c972beeb82e', '曉行巴峽', '晓行巴峽', '0a9829cc-805b-4812-a86a-1b2aee6a69ad', '唐', '["際曉投巴峽，餘春憶帝京。","晴江一女浣，朝日衆雞鳴。","水國舟中市，山橋樹杪行。","登高萬井出，眺迥二流明。","人作殊方語，鸎爲故國聲。","賴多山水趣，稍解別離情。"]', '["際晓投巴峽，餘春憶帝京。","晴江一女浣，朝日衆雞鳴。","水国舟中市，山橋樹杪行。","登高万井出，眺迥二流明。","人作殊方語，鸎爲故国声。","賴多山水趣，稍解別離情。"]', '诗', 'shi', '', NULL, '曉行巴峽 王維 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6f2659f3-d735-4ddd-8f72-d30137a55255', '清如玉壺冰', '清如玉壺冰', '0a9829cc-805b-4812-a86a-1b2aee6a69ad', '唐', '["玉壺何用好，偏許素冰居。","未共銷丹日，還同照綺疏。","抱明中不隱，含淨外疑虛。","氣似庭霜積，光言砌月餘。","曉凌飛鵲鏡，宵暎聚螢書。","若向夫君比，清心尚不如。"]', '["玉壺何用好，偏許素冰居。","未共銷丹日，還同照綺疏。","抱明中不隐，含淨外疑虛。","氣似庭霜積，光言砌月餘。","晓凌飞鵲镜，宵暎聚螢书。","若向夫君比，清心尚不如。"]', '诗', 'shi', '', NULL, '清如玉壺冰 王維 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0a27e70d-a681-4031-8b7e-5f411f00fb49', '賦得秋日懸清光', '賦得秋日懸清光', '0a9829cc-805b-4812-a86a-1b2aee6a69ad', '唐', '["寥廓涼天靜，晶明白日秋。","圓光含萬象，碎影入閑流。","迥與青冥合，遙同江甸浮。","晝陰殊衆木，斜影下危樓。","宋玉登高怨，張衡望遠愁。","餘輝如可託，雲路豈悠悠。"]', '["寥廓涼天静，晶明白日秋。","圓光含万象，碎影入闲流。","迥與青冥合，遙同江甸浮。","晝陰殊衆木，斜影下危楼。","宋玉登高怨，張衡望远愁。","餘輝如可託，云路豈悠悠。"]', '诗', 'shi', '', NULL, '賦得秋日懸清光 王維 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b73fdaf7-eb78-46bc-88b0-f85faad3aed4', '東谿玩月', '东谿玩月', '0a9829cc-805b-4812-a86a-1b2aee6a69ad', '唐', '["月從斷山口，遙吐柴門端。","萬木分空霽，流陰中夜攢。","光連虛象白，氣與風露寒。","谷靜秋泉響，巖深青靄殘。","清燈入幽夢，破影抱空巒。","恍惚琴窗裏，松谿曉思難。"]', '["月從斷山口，遙吐柴门端。","万木分空霽，流陰中夜攢。","光連虛象白，氣與风露寒。","谷静秋泉响，巖深青靄殘。","清灯入幽梦，破影抱空巒。","恍惚琴窗裏，松谿晓思难。"]', '诗', 'shi', '', NULL, '東谿玩月 王維 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('69e71ade-05dd-4118-a040-bfe449a37260', '田家', '田家', '0a9829cc-805b-4812-a86a-1b2aee6a69ad', '唐', '["舊穀行將盡，良苗未可希。","老年方愛粥，卒歲且無衣。","雀乳青苔井，雞鳴白板扉。","柴車駕羸牸，草屩牧豪狶。","夕雨紅榴拆，新秋綠芋肥。","餉田桑下憩，旁舍草中歸。","住處名愚谷，何煩問是非。"]', '["旧穀行將尽，良苗未可希。","老年方愛粥，卒歲且無衣。","雀乳青苔井，雞鳴白板扉。","柴车駕羸牸，草屩牧豪狶。","夕雨紅榴拆，新秋綠芋肥。","餉田桑下憩，旁舍草中归。","住处名愚谷，何煩问是非。"]', '诗', 'shi', '', NULL, '田家 王維 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('626ba0c1-f8e9-47fb-94db-b97264d014d9', '沈十四拾遺新竹生讀經處同諸公之作', '沈十四拾遺新竹生读經处同諸公之作', '0a9829cc-805b-4812-a86a-1b2aee6a69ad', '唐', '["閑居日清靜，修竹自檀欒。","嫩節留餘籜，新叢出舊闌。","細枝風響亂，疎影月光寒。","樂府裁龍笛，漁家伐釣竿。","何如道門裏，青翠拂仙壇。"]', '["闲居日清静，修竹自檀欒。","嫩節留餘籜，新叢出旧闌。","細枝风响亂，疎影月光寒。","乐府裁龙笛，漁家伐釣竿。","何如道门裏，青翠拂仙壇。"]', '诗', 'shi', '', NULL, '沈十四拾遺新竹生讀經處同諸公之作 王維 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('04e3592c-e41d-4555-ba96-221070a2c5ae', '雜詩', '杂诗', '0a9829cc-805b-4812-a86a-1b2aee6a69ad', '唐', '["朝因折楊柳，相見洛陽隅。","楚國無如妾，秦家自有夫。","對人傳玉腕，暎燭解羅襦。","人見東方騎，皆言夫壻殊。","持謝金吾子，煩君提玉壺。"]', '["朝因折楊柳，相见洛陽隅。","楚国無如妾，秦家自有夫。","对人傳玉腕，暎燭解羅襦。","人见东方騎，皆言夫壻殊。","持謝金吾子，煩君提玉壺。"]', '诗', 'shi', '', NULL, '雜詩 王維 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4be7de82-296f-46c1-a7a5-313953bd12a0', '哭褚司馬', '哭褚司马', '0a9829cc-805b-4812-a86a-1b2aee6a69ad', '唐', '["妄識皆心累，浮生定死媒。","誰言老龍吉，未免伯牛災。","故有求仙藥，仍餘遯俗杯。","山川秋樹苦，窗戶夜泉哀。","尚憶青騾去，寧知白馬來。","漢臣修史記，莫蔽褚生才。"]', '["妄識皆心累，浮生定死媒。","誰言老龙吉，未免伯牛災。","故有求仙藥，仍餘遯俗杯。","山川秋樹苦，窗戶夜泉哀。","尚憶青騾去，寧知白马来。","漢臣修史記，莫蔽褚生才。"]', '诗', 'shi', '', NULL, '哭褚司馬 王維 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('223cc8ea-0fe5-4699-be56-196276a6f493', '過沈居士山居哭之', '過沈居士山居哭之', '0a9829cc-805b-4812-a86a-1b2aee6a69ad', '唐', '["楊朱來此哭，桑扈返於真。","獨自成千古，依然舊四鄰。","閑簷喧鳥鵲，故榻滿埃塵。","曙月孤鶯囀，空山五柳春。","野花愁對客，泉水咽迎人。","善卷明時隱，黔婁在日貧。","逝川嗟爾命，丘井歎吾身。","前後徒言隔，相悲詎幾晨。"]', '["楊朱来此哭，桑扈返於真。","独自成千古，依然旧四鄰。","闲簷喧鸟鵲，故榻满埃塵。","曙月孤鶯囀，空山五柳春。","野花愁对客，泉水咽迎人。","善卷明时隐，黔婁在日貧。","逝川嗟爾命，丘井歎吾身。","前後徒言隔，相悲詎幾晨。"]', '诗', 'shi', '', NULL, '過沈居士山居哭之 王維 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('40c43c40-99b9-49b1-849b-556135031e1b', '哭祖六自虛', '哭祖六自虛', '0a9829cc-805b-4812-a86a-1b2aee6a69ad', '唐', '["否極嘗聞泰，嗟君獨不然。","憫凶纔稚齒，羸疾主中年。","餘力文章秀，生知禮樂全。","翰留天帳覽，詞入帝宮傳。","國訝終軍少，人知賈誼賢。","公卿盡虛左，朋識共推先。","不恨依窮轍，終期濟巨川。","才雄望羔雁，壽促背貂蟬。","福善聞前錄，殲良昧上玄。","何辜鎩鸞翮，底事碎龍泉。","鵩起長沙賦，麟終曲阜編。","域中君道廣，海內我情偏。","乍失疑猶見，沈思悟絕緣。","生前不忍別，死後向誰宣。","爲此情難盡，彌令憶更纏。","本家清渭曲，歸葬舊塋邊。","永去長安道，徒聞京兆阡。","旌車出郊甸，鄉國隱雲天。","定作無期別，寧同舊日旋。","候門家屬苦，行路國人憐。","送客哀難進，征途泥復前。","贈言爲挽曲，奠席是離筵。","念昔同攜手，風期不暫捐。","南山俱隱逸，東洛類神仙。","未省音容間，那堪生死遷。","花時金谷飲，月夜竹林眠。","滿地傳都賦，傾朝看藥船。","羣公咸屬目，微物敢齊肩。","謬合同人旨，而將玉樹連。","不期先挂劒，長恐後施鞭。","爲善吾無矣，知音子絕焉。","琴聲縱不沒，終亦繼悲弦。"]', '["否極嘗闻泰，嗟君独不然。","憫凶纔稚齒，羸疾主中年。","餘力文章秀，生知禮乐全。","翰留天帳覽，词入帝宮傳。","国訝終軍少，人知賈誼賢。","公卿尽虛左，朋識共推先。","不恨依窮轍，終期濟巨川。","才雄望羔雁，壽促背貂蟬。","福善闻前錄，殲良昧上玄。","何辜鎩鸾翮，底事碎龙泉。","鵩起长沙賦，麟終曲阜編。","域中君道廣，海內我情偏。","乍失疑猶见，沈思悟絕緣。","生前不忍別，死後向誰宣。","爲此情难尽，彌令憶更纏。","本家清渭曲，归葬旧塋邊。","永去长安道，徒闻京兆阡。","旌车出郊甸，乡国隐云天。","定作無期別，寧同旧日旋。","候门家屬苦，行路国人怜。","送客哀难進，征途泥复前。","贈言爲挽曲，奠席是離筵。","念昔同携手，风期不暫捐。","南山俱隐逸，东洛類神仙。","未省音容间，那堪生死遷。","花时金谷饮，月夜竹林眠。","满地傳都賦，傾朝看藥船。","羣公咸屬目，微物敢齊肩。","謬合同人旨，而將玉樹連。","不期先挂劒，长恐後施鞭。","爲善吾無矣，知音子絕焉。","琴声縱不沒，終亦繼悲弦。"]', '诗', 'shi', '', NULL, '哭祖六自虛 王維 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ce71032a-c075-492c-9554-51eb080348a5', '奉和聖製從蓬萊向興慶閣道中留春雨中春望之作應制', '奉和聖製從蓬萊向兴慶閣道中留春雨中春望之作應制', '0a9829cc-805b-4812-a86a-1b2aee6a69ad', '唐', '["渭水自縈秦塞曲，黃山舊遶漢宮斜。","鑾輿迥出千門柳，閣道廻看上苑花。","雲裏帝城雙鳳闕，雨中春樹萬人家。","爲乘陽氣行時令，不是宸遊玩物華。"]', '["渭水自縈秦塞曲，黄山旧遶漢宮斜。","鑾輿迥出千门柳，閣道廻看上苑花。","云裏帝城雙鳳闕，雨中春樹万人家。","爲乘陽氣行时令，不是宸游玩物华。"]', '诗', 'shi', '', NULL, '奉和聖製從蓬萊向興慶閣道中留春雨中春望之作應制 王維 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3019a6aa-b32d-4a57-bd78-90c0dbe35453', '大同殿柱產玉芝龍池上有慶雲神光照殿百官共覩聖恩便賜宴樂敢書即事', '大同殿柱產玉芝龙池上有慶云神光照殿百官共覩聖恩便賜宴乐敢书即事', '0a9829cc-805b-4812-a86a-1b2aee6a69ad', '唐', '["欲笑周文歌宴鎬，遙輕漢武樂橫汾。","豈知玉殿生三秀，詎有銅池出五雲。","陌上堯樽傾北斗，樓前舜樂動南薰。","共歡天意同人意，萬歲千秋奉聖君。"]', '["欲笑周文歌宴鎬，遙轻漢武乐橫汾。","豈知玉殿生三秀，詎有銅池出五云。","陌上堯樽傾北斗，楼前舜乐动南薰。","共歡天意同人意，万歲千秋奉聖君。"]', '诗', 'shi', '', NULL, '大同殿柱產玉芝龍池上有慶雲神光照殿百官共覩聖恩便賜宴樂敢書即事 王維 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a69d95f9-9598-4ebe-9532-84b3c5c8cd82', '敕賜百官櫻桃', '敕賜百官櫻桃', '0a9829cc-805b-4812-a86a-1b2aee6a69ad', '唐', '["芙蓉闕下會千官，紫禁朱櫻出上[蘭]。","纔是寢園春薦後，非關御苑鳥銜殘。","歸鞍競帶青絲籠，中使頻傾赤玉盤。","飽食不須愁內熱，大官還有蔗漿寒。"]', '["芙蓉闕下會千官，紫禁朱櫻出上[蘭]。","纔是寢园春薦後，非关御苑鸟銜殘。","归鞍競带青絲籠，中使頻傾赤玉盤。","飽食不須愁內熱，大官還有蔗漿寒。"]', '诗', 'shi', '', NULL, '敕賜百官櫻桃 王維 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('40dd7d52-88ca-4f10-b5b4-b8f98e9a668c', '敕借岐王九成宮避暑應教', '敕借岐王九成宮避暑應教', '0a9829cc-805b-4812-a86a-1b2aee6a69ad', '唐', '["帝子遠辭丹鳳闕，天書遙借翠微宮。","隔窗雲霧生衣上，卷幔山泉入鏡中。","林下水聲喧語笑，巖間樹色隱房櫳。","仙家未必能勝此，何事吹笙向碧空。"]', '["帝子远辞丹鳳闕，天书遙借翠微宮。","隔窗云霧生衣上，卷幔山泉入镜中。","林下水声喧語笑，巖间樹色隐房櫳。","仙家未必能勝此，何事吹笙向碧空。"]', '诗', 'shi', '', NULL, '敕借岐王九成宮避暑應教 王維 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a364504e-3cfc-44c6-9203-173856452cdd', '和賈舍人早朝大明宮之作', '和賈舍人早朝大明宮之作', '0a9829cc-805b-4812-a86a-1b2aee6a69ad', '唐', '["絳幘雞人送曉籌，尚衣方進翠雲裘。","九天閶闔開宮殿，萬國衣冠拜冕旒。","日色纔臨仙掌動，香煙欲傍衮龍浮。","朝罷須裁五色詔，佩聲歸向鳳池頭。"]', '["絳幘雞人送晓籌，尚衣方進翠云裘。","九天閶闔开宮殿，万国衣冠拜冕旒。","日色纔臨仙掌动，香煙欲傍衮龙浮。","朝罷須裁五色詔，佩声归向鳳池头。"]', '诗', 'shi', '', NULL, '和賈舍人早朝大明宮之作 王維 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('837dbd82-f524-41e5-9f9f-38838ac3f41c', '和太常韋主簿五郎溫湯寓目之作', '和太常韋主簿五郎溫湯寓目之作', '0a9829cc-805b-4812-a86a-1b2aee6a69ad', '唐', '["漢主離宮接露臺，秦川一半夕陽開。","青山盡是朱旗繞，碧澗翻從玉殿來。","新豐樹裏行人度，小苑城邊獵騎廻。","聞道甘泉能獻賦，懸知獨有子雲才。"]', '["漢主離宮接露台，秦川一半夕陽开。","青山尽是朱旗繞，碧澗翻從玉殿来。","新豐樹裏行人度，小苑城邊獵騎廻。","闻道甘泉能獻賦，懸知独有子云才。"]', '诗', 'shi', '', NULL, '和太常韋主簿五郎溫湯寓目之作 王維 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('80a1044e-e0f3-4e29-8c12-b5fe7eb35336', '苑舍人能書梵字兼達梵音皆曲盡其妙戲爲之贈', '苑舍人能书梵字兼達梵音皆曲尽其妙戲爲之贈', '0a9829cc-805b-4812-a86a-1b2aee6a69ad', '唐', '["名儒待詔滿公車，才子爲郎典石渠。","蓮花法藏心懸悟，貝葉經文手自書。","楚詞共許勝楊馬，梵字何人辨魯魚。","故舊相望在三事，願君莫厭承明廬。"]', '["名儒待詔满公车，才子爲郎典石渠。","蓮花法藏心懸悟，貝葉經文手自书。","楚词共許勝楊马，梵字何人辨魯鱼。","故旧相望在三事，願君莫厭承明廬。"]', '诗', 'shi', '', NULL, '苑舍人能書梵字兼達梵音皆曲盡其妙戲爲之贈 王維 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5f677b56-89a4-404a-88e2-017e78a1cd5b', '重酬苑郎中', '重酬苑郎中', '0a9829cc-805b-4812-a86a-1b2aee6a69ad', '唐', '["何幸含香奉至尊，多慙未報主人恩。","草木盡能酬雨露，榮枯安敢問乾坤。","仙郎有意憐同舍，丞相無私斷埽門。","揚子解嘲徒自遣，馮唐已老復何論。"]', '["何幸含香奉至尊，多慙未報主人恩。","草木尽能酬雨露，榮枯安敢问乾坤。","仙郎有意怜同舍，丞相無私斷埽门。","揚子解嘲徒自遣，馮唐已老复何論。"]', '诗', 'shi', '', NULL, '重酬苑郎中 王維 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7950a49f-f51d-4926-9d1e-e5f76b153829', '酬郭給事', '酬郭給事', '0a9829cc-805b-4812-a86a-1b2aee6a69ad', '唐', '["洞門高閣靄餘輝，桃李陰陰柳絮飛。","禁裏疎鐘官舍晚，省中啼鳥吏人稀。","晨搖玉佩趨金殿，夕奉天書拜瑣闈。","強欲從君無那老，將因臥病解朝衣。"]', '["洞门高閣靄餘輝，桃李陰陰柳絮飞。","禁裏疎鐘官舍晚，省中啼鸟吏人稀。","晨搖玉佩趨金殿，夕奉天书拜瑣闈。","強欲從君無那老，將因臥病解朝衣。"]', '诗', 'shi', '', NULL, '酬郭給事 王維 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a7d807c5-435d-492a-8a17-d77b596f6d12', '出塞', '出塞', '0a9829cc-805b-4812-a86a-1b2aee6a69ad', '唐', '["居延城外獵天驕，白草連山野火燒。","暮雲空磧時驅馬，秋日平原好射鵰。","護羗校尉朝乘障，破虜將軍夜渡遼。","玉靶角弓珠勒馬，漢家將賜霍嫖姚。"]', '["居延城外獵天驕，白草連山野火燒。","暮云空磧时驱马，秋日平原好射鵰。","護羗校尉朝乘障，破虜將軍夜渡遼。","玉靶角弓珠勒马，漢家將賜霍嫖姚。"]', '诗', 'shi', '', NULL, '出塞 王維 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('81ae102d-4177-47e4-a93b-f500ba8ad175', '既蒙宥罪旋復拜官伏感聖恩竊書鄙意兼奉簡新除使君等諸公', '既蒙宥罪旋复拜官伏感聖恩竊书鄙意兼奉簡新除使君等諸公', '0a9829cc-805b-4812-a86a-1b2aee6a69ad', '唐', '["忽蒙漢詔還冠冕，始覺殷王解網羅。","日比皇明猶自暗，天齊聖壽未云多。","花迎喜氣皆知笑，鳥識歡心亦解歌。","聞道百城新佩印，還來雙闕共鳴珂。"]', '["忽蒙漢詔還冠冕，始覺殷王解網羅。","日比皇明猶自暗，天齊聖壽未云多。","花迎喜氣皆知笑，鸟識歡心亦解歌。","闻道百城新佩印，還来雙闕共鳴珂。"]', '诗', 'shi', '', NULL, '既蒙宥罪旋復拜官伏感聖恩竊書鄙意兼奉簡新除使君等諸公 王維 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b23eb216-8b5b-45d2-8c15-0c9dcb4fdd3b', '送方尊師歸嵩山', '送方尊師归嵩山', '0a9829cc-805b-4812-a86a-1b2aee6a69ad', '唐', '["仙官欲往九龍潭，旄節朱幡倚石龕。","山壓天中半天上，洞穿江底出江南。","瀑布杉松常帶雨，夕陽蒼翠忽成嵐。","借問迎來雙白鶴，已曾衡嶽送蘇耽。"]', '["仙官欲往九龙潭，旄節朱幡倚石龕。","山壓天中半天上，洞穿江底出江南。","瀑布杉松常带雨，夕陽蒼翠忽成嵐。","借问迎来雙白鹤，已曾衡嶽送蘇耽。"]', '诗', 'shi', '', NULL, '送方尊師歸嵩山 王維 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1ce3dd53-b772-4e88-8cd8-080329565416', '送楊少府貶郴州', '送楊少府貶郴州', '0a9829cc-805b-4812-a86a-1b2aee6a69ad', '唐', '["明到衡山與洞庭，若爲秋月聽猿聲。","愁看北渚三湘遠，惡說南風五兩輕。","青草瘴時過夏口，白頭浪裏出湓城。","長沙不久留才子，賈誼何須弔屈平。"]', '["明到衡山與洞庭，若爲秋月听猿声。","愁看北渚三湘远，惡说南风五兩轻。","青草瘴时過夏口，白头浪裏出湓城。","长沙不久留才子，賈誼何須弔屈平。"]', '诗', 'shi', '', NULL, '送楊少府貶郴州 王維 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b299afc7-1bde-46c6-9be3-7ffb8c4243e4', '過乘如禪師蕭居士嵩丘蘭若', '過乘如禪師蕭居士嵩丘蘭若', '0a9829cc-805b-4812-a86a-1b2aee6a69ad', '唐', '["無着天親弟與兄，嵩丘蘭若一峰晴。","食隨鳴磬巢烏下，行踏空林落葉聲。","迸水定侵香案濕，雨花應共石牀平。","深洞長松何所有，儼然天竺古先生。"]', '["無着天親弟與兄，嵩丘蘭若一峰晴。","食隨鳴磬巢烏下，行踏空林落葉声。","迸水定侵香案濕，雨花應共石牀平。","深洞长松何所有，儼然天竺古先生。"]', '诗', 'shi', '', NULL, '過乘如禪師蕭居士嵩丘蘭若 王維 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('80ff4aed-e8e4-459c-963f-659895422def', '春日與裴迪過新昌里訪呂逸人不遇', '春日與裴迪過新昌里訪呂逸人不遇', '0a9829cc-805b-4812-a86a-1b2aee6a69ad', '唐', '["桃源一向絕風塵，柳市南頭訪隱淪。","到門不敢題凡鳥，看竹何須問主人。","城上青山如屋裏，東家流水入西鄰。","閉戶著書多歲月，種松皆老作龍鱗。"]', '["桃源一向絕风塵，柳市南头訪隐淪。","到门不敢題凡鸟，看竹何須问主人。","城上青山如屋裏，东家流水入西鄰。","閉戶著书多歲月，種松皆老作龙鱗。"]', '诗', 'shi', '', NULL, '春日與裴迪過新昌里訪呂逸人不遇 王維 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0e7afbc5-fa58-41f9-8af4-1b2db6dc3c03', '酌酒與裴迪', '酌酒與裴迪', '0a9829cc-805b-4812-a86a-1b2aee6a69ad', '唐', '["酌酒與君君自寬，人情翻覆似波瀾。","白首相知猶按劒，朱門先達笑彈冠。","草色全經細雨濕，花枝欲動春風寒。","世事浮雲何足問，不如高臥且加餐。"]', '["酌酒與君君自寬，人情翻覆似波瀾。","白首相知猶按劒，朱门先達笑彈冠。","草色全經細雨濕，花枝欲动春风寒。","世事浮云何足问，不如高臥且加餐。"]', '诗', 'shi', '', NULL, '酌酒與裴迪 王維 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7f6c7690-adb5-4337-bb03-0b60d508e375', '輞川別業', '輞川別業', '0a9829cc-805b-4812-a86a-1b2aee6a69ad', '唐', '["不到東山向一年，歸來纔及種春田。","雨中草色綠堪染，水上桃花紅欲然。","優婁比丘經論學，傴僂丈人鄉里賢。","披衣倒屣且相見，相歡語笑衡門前。"]', '["不到东山向一年，归来纔及種春田。","雨中草色綠堪染，水上桃花紅欲然。","優婁比丘經論学，傴僂丈人乡里賢。","披衣倒屣且相见，相歡語笑衡门前。"]', '诗', 'shi', '', NULL, '輞川別業 王維 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('10b89f48-445d-4a21-a475-5d978eac5f0b', '早秋山中作', '早秋山中作', '0a9829cc-805b-4812-a86a-1b2aee6a69ad', '唐', '["無才不敢累明時，思向東谿守故籬。","豈厭尚平婚嫁早，却嫌陶令去官遲。","草間蛩響臨秋急，山裏蟬聲薄暮悲。","寂寞柴門人不到，空林獨與白雲期。"]', '["無才不敢累明时，思向东谿守故籬。","豈厭尚平婚嫁早，却嫌陶令去官遲。","草间蛩响臨秋急，山裏蟬声薄暮悲。","寂寞柴门人不到，空林独與白云期。"]', '诗', 'shi', '', NULL, '早秋山中作 王維 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0949fe2a-aadf-4cd4-b1c3-25fcdaecdb96', '積雨輞川莊作', '積雨輞川莊作', '0a9829cc-805b-4812-a86a-1b2aee6a69ad', '唐', '["積雨空林煙火遲，蒸藜炊黍餉東菑。","漠漠水田飛白鷺，陰陰夏木囀黃鸝。","山中習靜觀朝槿，松下清齋折露葵。","野老與人爭席罷，海鷗何事更相疑。"]', '["積雨空林煙火遲，蒸藜炊黍餉东菑。","漠漠水田飞白鷺，陰陰夏木囀黄鸝。","山中習静观朝槿，松下清斋折露葵。","野老與人爭席罷，海鷗何事更相疑。"]', '诗', 'shi', '', NULL, '積雨輞川莊作 王維 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a1cce991-036e-4212-8ce3-79e2ec09437e', '聽百舌鳥', '听百舌鸟', '0a9829cc-805b-4812-a86a-1b2aee6a69ad', '唐', '["上蘭門外草萋萋，未央宮中花裏栖。","亦有相隨過御苑，不知若箇向金堤。","入春解作千般語，拂曙能先百鳥啼。","萬戶千門應覺曉，建章何必聽鳴雞。"]', '["上蘭门外草萋萋，未央宮中花裏栖。","亦有相隨過御苑，不知若箇向金堤。","入春解作千般語，拂曙能先百鸟啼。","万戶千门應覺晓，建章何必听鳴雞。"]', '诗', 'shi', '', NULL, '聽百舌鳥 王維 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4aae89a6-18e5-453d-bfb4-2f3807bdd87c', '息夫人', '息夫人', '0a9829cc-805b-4812-a86a-1b2aee6a69ad', '唐', '["莫以今時寵，難忘舊日恩。","看花滿眼淚，不共楚王言。"]', '["莫以今时寵，难忘旧日恩。","看花满眼泪，不共楚王言。"]', '诗', 'shi', '', NULL, '息夫人 王維 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9357d459-7d1c-4eed-9fd0-d4b0ce6a2c2a', '班婕妤三首 一', '班婕妤三首 一', '0a9829cc-805b-4812-a86a-1b2aee6a69ad', '唐', '["玉窗螢影度，金殿人聲絕。","秋夜守羅帷，孤燈耿不滅。"]', '["玉窗螢影度，金殿人声絕。","秋夜守羅帷，孤灯耿不滅。"]', '诗', 'shi', '', NULL, '班婕妤三首 一 王維 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6f892ec1-3ab6-4630-b5c8-d2bc623f66ea', '班婕妤三首 二', '班婕妤三首 二', '0a9829cc-805b-4812-a86a-1b2aee6a69ad', '唐', '["宮殿生秋草，君王恩幸疎。","那堪聞鳳吹，門外度金輿。"]', '["宮殿生秋草，君王恩幸疎。","那堪闻鳳吹，门外度金輿。"]', '诗', 'shi', '', NULL, '班婕妤三首 二 王維 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2be95663-2cf4-495f-a000-32b4746cd296', '班婕妤三首 三', '班婕妤三首 三', '0a9829cc-805b-4812-a86a-1b2aee6a69ad', '唐', '["怪來妝閣閉，朝下不相迎。","總向春園裏，花間笑語聲。"]', '["怪来妝閣閉，朝下不相迎。","總向春园裏，花间笑語声。"]', '诗', 'shi', '', NULL, '班婕妤三首 三 王維 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0e955cd6-1201-4583-b05b-629688085383', '輞川集 孟城坳', '輞川集 孟城坳', '0a9829cc-805b-4812-a86a-1b2aee6a69ad', '唐', '["新家孟城口，古木餘衰柳。","來者復爲誰，空悲昔人有。"]', '["新家孟城口，古木餘衰柳。","来者复爲誰，空悲昔人有。"]', '诗', 'shi', '', NULL, '輞川集 孟城坳 王維 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d1114b54-1f47-470d-a9e4-c9c24101d9c2', '輞川集 華子岡', '輞川集 华子岡', '0a9829cc-805b-4812-a86a-1b2aee6a69ad', '唐', '["飛鳥去不窮，連山復秋色。","上下華子岡，惆悵情何極。"]', '["飞鸟去不窮，連山复秋色。","上下华子岡，惆悵情何極。"]', '诗', 'shi', '', NULL, '輞川集 華子岡 王維 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f9b25804-87bf-449c-9a95-ed86e9133ff2', '輞川集 文杏館', '輞川集 文杏館', '0a9829cc-805b-4812-a86a-1b2aee6a69ad', '唐', '["文杏裁爲梁，香茅結爲宇。","不知棟裏雲，去作人間雨。"]', '["文杏裁爲梁，香茅結爲宇。","不知棟裏云，去作人间雨。"]', '诗', 'shi', '', NULL, '輞川集 文杏館 王維 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('dff71696-64af-48ec-a90b-273a762752d3', '輞川集 斤竹嶺', '輞川集 斤竹嶺', '0a9829cc-805b-4812-a86a-1b2aee6a69ad', '唐', '["檀欒暎空曲，青翠漾漣漪。","暗入商山路，樵人不可知。"]', '["檀欒暎空曲，青翠漾漣漪。","暗入商山路，樵人不可知。"]', '诗', 'shi', '', NULL, '輞川集 斤竹嶺 王維 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2e8999a9-9df8-4483-ab1e-0231c3e46320', '輞川集 鹿柴', '輞川集 鹿柴', '0a9829cc-805b-4812-a86a-1b2aee6a69ad', '唐', '["空山不見人，但聞人語響。","返景入深林，復照青苔上。"]', '["空山不见人，但闻人語响。","返景入深林，复照青苔上。"]', '诗', 'shi', '', NULL, '輞川集 鹿柴 王維 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4721c4de-6b7f-4300-86c3-1c28027d0158', '輞川集 木蘭柴', '輞川集 木蘭柴', '0a9829cc-805b-4812-a86a-1b2aee6a69ad', '唐', '["秋山斂餘照，飛鳥逐前侶。","彩翠時分明，夕嵐無處所。"]', '["秋山斂餘照，飞鸟逐前侶。","彩翠时分明，夕嵐無处所。"]', '诗', 'shi', '', NULL, '輞川集 木蘭柴 王維 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('59d59574-aae3-463e-83d5-877fee9781be', '輞川集 茱萸沜', '輞川集 茱萸沜', '0a9829cc-805b-4812-a86a-1b2aee6a69ad', '唐', '["結實紅且綠，復如花更開。","山中儻留客，置此芙蓉杯。"]', '["結實紅且綠，复如花更开。","山中儻留客，置此芙蓉杯。"]', '诗', 'shi', '', NULL, '輞川集 茱萸沜 王維 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1cb863ff-de22-479b-94ca-6072ed5ed64d', '輞川集 宮槐陌', '輞川集 宮槐陌', '0a9829cc-805b-4812-a86a-1b2aee6a69ad', '唐', '["仄逕蔭宮槐，幽陰多綠苔。","應門但迎埽，畏有山僧來。"]', '["仄逕蔭宮槐，幽陰多綠苔。","應门但迎埽，畏有山僧来。"]', '诗', 'shi', '', NULL, '輞川集 宮槐陌 王維 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3c1a9546-02b6-4d89-9159-636dc5991f03', '輞川集 臨湖亭', '輞川集 臨湖亭', '0a9829cc-805b-4812-a86a-1b2aee6a69ad', '唐', '["輕舸迎上客，悠悠湖上來。","當軒對尊酒，四面芙蓉開。"]', '["轻舸迎上客，悠悠湖上来。","當軒对尊酒，四面芙蓉开。"]', '诗', 'shi', '', NULL, '輞川集 臨湖亭 王維 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ff97c1dc-6555-4269-8cbe-a33ccc29c62b', '輞川集 南垞', '輞川集 南垞', '0a9829cc-805b-4812-a86a-1b2aee6a69ad', '唐', '["輕舟南垞去，北垞淼難即。","隔浦望人家，遙遙不相識。"]', '["轻舟南垞去，北垞淼难即。","隔浦望人家，遙遙不相識。"]', '诗', 'shi', '', NULL, '輞川集 南垞 王維 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9f4f99a7-0759-42a8-89fb-cb80d33e5f8a', '輞川集 欹湖', '輞川集 欹湖', '0a9829cc-805b-4812-a86a-1b2aee6a69ad', '唐', '["吹簫凌極浦，日暮送夫君。","湖上一回首，青山卷白雲。"]', '["吹簫凌極浦，日暮送夫君。","湖上一回首，青山卷白云。"]', '诗', 'shi', '', NULL, '輞川集 欹湖 王維 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4f8103e8-da27-45f0-8a25-65a73144d816', '輞川集 柳浪', '輞川集 柳浪', '0a9829cc-805b-4812-a86a-1b2aee6a69ad', '唐', '["分行接綺樹，倒影入清漪。","不學御溝上，春風傷別離。"]', '["分行接綺樹，倒影入清漪。","不学御溝上，春风傷別離。"]', '诗', 'shi', '', NULL, '輞川集 柳浪 王維 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4faeaa69-bc55-45e3-b756-25c79f279e46', '輞川集 欒家瀨', '輞川集 欒家瀨', '0a9829cc-805b-4812-a86a-1b2aee6a69ad', '唐', '["颯颯秋雨中，淺淺石溜瀉。","跳波自相濺，白鷺驚復下。"]', '["颯颯秋雨中，淺淺石溜瀉。","跳波自相濺，白鷺驚复下。"]', '诗', 'shi', '', NULL, '輞川集 欒家瀨 王維 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3a0f62ca-eee5-4d9f-a608-bc98128b6a62', '輞川集 金屑泉', '輞川集 金屑泉', '0a9829cc-805b-4812-a86a-1b2aee6a69ad', '唐', '["日飲金屑泉，少當千餘歲。","翠鳳翊文螭，羽節朝玉帝。"]', '["日饮金屑泉，少當千餘歲。","翠鳳翊文螭，羽節朝玉帝。"]', '诗', 'shi', '', NULL, '輞川集 金屑泉 王維 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d99ce877-5157-48fb-9b4e-418eeda6dd78', '輞川集 白石灘', '輞川集 白石灘', '0a9829cc-805b-4812-a86a-1b2aee6a69ad', '唐', '["清淺白石灘，綠蒲向堪把。","家住水東西，浣紗明月下。"]', '["清淺白石灘，綠蒲向堪把。","家住水东西，浣紗明月下。"]', '诗', 'shi', '', NULL, '輞川集 白石灘 王維 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1314168a-6c95-4f24-bf83-8bfb29af429d', '輞川集 北垞', '輞川集 北垞', '0a9829cc-805b-4812-a86a-1b2aee6a69ad', '唐', '["北垞湖水北，雜樹暎朱闌。","逶迤南川水，明滅青林端。"]', '["北垞湖水北，杂樹暎朱闌。","逶迤南川水，明滅青林端。"]', '诗', 'shi', '', NULL, '輞川集 北垞 王維 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('36e09cb4-4fb7-48be-b6c6-c9bd906d9331', '輞川集 竹里館', '輞川集 竹里館', '0a9829cc-805b-4812-a86a-1b2aee6a69ad', '唐', '["獨坐幽篁裏，彈琴復長嘯。","深林人不知，明月來相照。"]', '["独坐幽篁裏，彈琴复长嘯。","深林人不知，明月来相照。"]', '诗', 'shi', '', NULL, '輞川集 竹里館 王維 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7a65977c-bfe6-446d-8dbe-0cb48bcba644', '輞川集 辛夷塢', '輞川集 辛夷塢', '0a9829cc-805b-4812-a86a-1b2aee6a69ad', '唐', '["木末芙蓉花，山中發紅萼。","澗戶寂無人，紛紛開且落。"]', '["木末芙蓉花，山中發紅萼。","澗戶寂無人，紛紛开且落。"]', '诗', 'shi', '', NULL, '輞川集 辛夷塢 王維 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9fc6c345-e30d-4ee4-ac25-a02d5729c085', '輞川集 漆園', '輞川集 漆园', '0a9829cc-805b-4812-a86a-1b2aee6a69ad', '唐', '["古人非傲吏，自闕經世務。","偶寄一微官，婆娑數株樹。"]', '["古人非傲吏，自闕經世務。","偶寄一微官，婆娑數株樹。"]', '诗', 'shi', '', NULL, '輞川集 漆園 王維 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b02b4272-7873-4627-be35-000f8a362ecc', '輞川集 椒園', '輞川集 椒园', '0a9829cc-805b-4812-a86a-1b2aee6a69ad', '唐', '["桂尊迎帝子，杜若贈佳人。","椒漿奠瑤席，欲下雲中君。"]', '["桂尊迎帝子，杜若贈佳人。","椒漿奠瑤席，欲下云中君。"]', '诗', 'shi', '', NULL, '輞川集 椒園 王維 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e4f16516-db22-4a20-90cb-917c66c4afbd', '皇甫嶽雲溪雜題五首 鳥鳴澗', '皇甫嶽云溪杂題五首 鸟鳴澗', '0a9829cc-805b-4812-a86a-1b2aee6a69ad', '唐', '["人閑桂花落，夜靜春山空。","月出驚山鳥，時鳴春澗中。"]', '["人闲桂花落，夜静春山空。","月出驚山鸟，时鳴春澗中。"]', '诗', 'shi', '', NULL, '皇甫嶽雲溪雜題五首 鳥鳴澗 王維 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('92b4d6b3-cb1c-4032-ba7e-b04612817e2d', '皇甫嶽雲溪雜題五首 蓮花塢', '皇甫嶽云溪杂題五首 蓮花塢', '0a9829cc-805b-4812-a86a-1b2aee6a69ad', '唐', '["日日采蓮去，洲長多暮歸。","弄篙莫濺水，畏濕紅蓮衣。"]', '["日日采蓮去，洲长多暮归。","弄篙莫濺水，畏濕紅蓮衣。"]', '诗', 'shi', '', NULL, '皇甫嶽雲溪雜題五首 蓮花塢 王維 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0b6becb8-1b23-4933-8f41-2dff5f58e110', '皇甫嶽雲溪雜題五首 鸕鶿堰', '皇甫嶽云溪杂題五首 鸕鶿堰', '0a9829cc-805b-4812-a86a-1b2aee6a69ad', '唐', '["乍向紅蓮沒，復出清蒲颺。","獨立何䙰褷，銜魚古查上。"]', '["乍向紅蓮沒，复出清蒲颺。","独立何䙰褷，銜鱼古查上。"]', '诗', 'shi', '', NULL, '皇甫嶽雲溪雜題五首 鸕鶿堰 王維 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('86db9c01-05da-4fd9-8986-0ba7c7ca9025', '皇甫嶽雲溪雜題五首 上平田', '皇甫嶽云溪杂題五首 上平田', '0a9829cc-805b-4812-a86a-1b2aee6a69ad', '唐', '["朝耕上平田，暮耕上平田。","借問問津者，寧知沮溺賢。"]', '["朝耕上平田，暮耕上平田。","借问问津者，寧知沮溺賢。"]', '诗', 'shi', '', NULL, '皇甫嶽雲溪雜題五首 上平田 王維 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a2a51013-4177-45f6-a3d4-90b6d3af4d2f', '皇甫嶽雲溪雜題五首 萍池', '皇甫嶽云溪杂題五首 萍池', '0a9829cc-805b-4812-a86a-1b2aee6a69ad', '唐', '["春池深且廣，會待輕舟迴。","靡靡綠萍合，垂楊埽復開。"]', '["春池深且廣，會待轻舟迴。","靡靡綠萍合，垂楊埽复开。"]', '诗', 'shi', '', NULL, '皇甫嶽雲溪雜題五首 萍池 王維 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('bb65f745-f5fc-4335-bf7b-96b5c7d0fa83', '荅裴迪輞口遇雨憶終南山之作', '荅裴迪輞口遇雨憶終南山之作', '0a9829cc-805b-4812-a86a-1b2aee6a69ad', '唐', '["淼淼寒流廣，蒼蒼秋雨晦。","君問終南山，心知白雲外。"]', '["淼淼寒流廣，蒼蒼秋雨晦。","君问終南山，心知白云外。"]', '诗', 'shi', '', NULL, '荅裴迪輞口遇雨憶終南山之作 王維 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('36f58b7b-e1ef-49d9-963b-d10d4930f9e2', '山中寄諸弟妹', '山中寄諸弟妹', '0a9829cc-805b-4812-a86a-1b2aee6a69ad', '唐', '["山中多法侶，禪誦自爲羣。","城郭遙相望，唯應見白雲。"]', '["山中多法侶，禪誦自爲羣。","城郭遙相望，唯應见白云。"]', '诗', 'shi', '', NULL, '山中寄諸弟妹 王維 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c2cf5e61-81ab-4d41-b008-c152daf5db05', '聞裴秀才迪吟詩因戲贈', '闻裴秀才迪吟诗因戲贈', '0a9829cc-805b-4812-a86a-1b2aee6a69ad', '唐', '["猿吟一何苦，愁朝復悲夕。","莫作巫峽聲，腸斷秋江客。"]', '["猿吟一何苦，愁朝复悲夕。","莫作巫峽声，腸斷秋江客。"]', '诗', 'shi', '', NULL, '聞裴秀才迪吟詩因戲贈 王維 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a79e721a-ee73-457f-a43a-0944b33c6140', '贈韋穆十八', '贈韋穆十八', '0a9829cc-805b-4812-a86a-1b2aee6a69ad', '唐', '["與君青眼客，共有白雲心。","不相東山去，日令春草深。"]', '["與君青眼客，共有白云心。","不相东山去，日令春草深。"]', '诗', 'shi', '', NULL, '贈韋穆十八 王維 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c8a4faa6-8666-44f9-b4c9-df78d7af844d', '送別', '送別', '0a9829cc-805b-4812-a86a-1b2aee6a69ad', '唐', '["山中相送罷，日暮掩柴扉。","春草明年綠，王孫歸不歸。"]', '["山中相送罷，日暮掩柴扉。","春草明年綠，王孫归不归。"]', '诗', 'shi', '', NULL, '送別 王維 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c0b9ac13-46ad-4ad3-a541-47c63a2a0998', '臨高臺送黎拾遺', '臨高台送黎拾遺', '0a9829cc-805b-4812-a86a-1b2aee6a69ad', '唐', '["相送臨高臺，川原杳何極。","日暮飛鳥還，行人去不息。"]', '["相送臨高台，川原杳何極。","日暮飞鸟還，行人去不息。"]', '诗', 'shi', '', NULL, '臨高臺送黎拾遺 王維 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('89514eb5-c1c2-4b9b-bd77-19aa44ed09c2', '別輞川別業', '別輞川別業', '0a9829cc-805b-4812-a86a-1b2aee6a69ad', '唐', '["依遲動車馬，惆悵出松蘿。","忍別青山去，其如綠水何。"]', '["依遲动车马，惆悵出松蘿。","忍別青山去，其如綠水何。"]', '诗', 'shi', '', NULL, '別輞川別業 王維 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('126a3a63-ef90-409f-a321-4f43e6b79acf', '崔九弟欲往南山馬上口號與別', '崔九弟欲往南山马上口號與別', '0a9829cc-805b-4812-a86a-1b2aee6a69ad', '唐', '["城隅一分手，幾日還相見。","山中有桂花，莫待花如霰。"]', '["城隅一分手，幾日還相见。","山中有桂花，莫待花如霰。"]', '诗', 'shi', '', NULL, '崔九弟欲往南山馬上口號與別 王維 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ac889211-ebb0-4338-a355-6f54781eabaa', '題友人雲母障子', '題友人云母障子', '0a9829cc-805b-4812-a86a-1b2aee6a69ad', '唐', '["君家雲母障，時向野庭開。","自有山泉入，非因采畫來。"]', '["君家云母障，时向野庭开。","自有山泉入，非因采畫来。"]', '诗', 'shi', '', NULL, '題友人雲母障子 王維 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('bd630ab8-f5bd-416f-a460-bff9a1c857f3', '紅牡丹', '紅牡丹', '0a9829cc-805b-4812-a86a-1b2aee6a69ad', '唐', '["綠豔閑且靜，紅衣淺復深。","花心愁欲斷，春色豈知心。"]', '["綠豔闲且静，紅衣淺复深。","花心愁欲斷，春色豈知心。"]', '诗', 'shi', '', NULL, '紅牡丹 王維 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('56855193-bee7-4ab9-bfc9-29eb35781ea3', '左掖梨花', '左掖梨花', '0a9829cc-805b-4812-a86a-1b2aee6a69ad', '唐', '["閑灑階邊草，輕隨箔外風。","黃鶯弄不足，銜入未央宮。"]', '["闲灑階邊草，轻隨箔外风。","黄鶯弄不足，銜入未央宮。"]', '诗', 'shi', '', NULL, '左掖梨花 王維 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d507c93c-a545-4e4c-aed9-29e01681b4c8', '菩提寺禁口號又示裴迪', '菩提寺禁口號又示裴迪', '0a9829cc-805b-4812-a86a-1b2aee6a69ad', '唐', '["安得捨羅網，拂衣辭世喧。","悠然策藜杖，歸向桃花源。"]', '["安得捨羅網，拂衣辞世喧。","悠然策藜杖，归向桃花源。"]', '诗', 'shi', '', NULL, '菩提寺禁口號又示裴迪 王維 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ded6cef4-a715-48ed-a715-6bb303ccaa6d', '雜詩三首 一', '杂诗三首 一', '0a9829cc-805b-4812-a86a-1b2aee6a69ad', '唐', '["家住孟津河，門對孟津口。","常有江南船，寄書家中否。"]', '["家住孟津河，门对孟津口。","常有江南船，寄书家中否。"]', '诗', 'shi', '', NULL, '雜詩三首 一 王維 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4c7205af-d1e8-48ed-8220-fe095418b95a', '雜詩三首 二', '杂诗三首 二', '0a9829cc-805b-4812-a86a-1b2aee6a69ad', '唐', '["君自故鄉來，應知故鄉事。","來日綺窗前，寒梅着花未。"]', '["君自故乡来，應知故乡事。","来日綺窗前，寒梅着花未。"]', '诗', 'shi', '', NULL, '雜詩三首 二 王維 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7ef54c16-89d7-4a82-8d73-e95fcde76219', '雜詩三首 三', '杂诗三首 三', '0a9829cc-805b-4812-a86a-1b2aee6a69ad', '唐', '["已見寒梅發，復聞啼鳥聲。","心心視春草，畏向階前生。"]', '["已见寒梅發，复闻啼鸟声。","心心視春草，畏向階前生。"]', '诗', 'shi', '', NULL, '雜詩三首 三 王維 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4a48384b-ea4d-462a-b60a-21ce8e97c929', '崔興宗寫真詠', '崔兴宗寫真詠', '0a9829cc-805b-4812-a86a-1b2aee6a69ad', '唐', '["畫君年少時，如今君已老。","今時新識人，知君舊時好。"]', '["畫君年少时，如今君已老。","今时新識人，知君旧时好。"]', '诗', 'shi', '', NULL, '崔興宗寫真詠 王維 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c98ca515-af40-499a-b551-482e6e6cd30b', '山茱萸', '山茱萸', '0a9829cc-805b-4812-a86a-1b2aee6a69ad', '唐', '["朱實山下開，清香寒更發。","幸與叢桂花，窗前向秋月。"]', '["朱實山下开，清香寒更發。","幸與叢桂花，窗前向秋月。"]', '诗', 'shi', '', NULL, '山茱萸 王維 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8baa7c35-9afb-40bf-b5e4-41d9895e2710', '相思', '相思', '0a9829cc-805b-4812-a86a-1b2aee6a69ad', '唐', '["紅豆生南國，秋來發故枝。","願君多采擷，此物最相思。"]', '["紅豆生南国，秋来發故枝。","願君多采擷，此物最相思。"]', '诗', 'shi', '', NULL, '相思 王維 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('93856775-6171-4eb9-986d-75f402a5bc63', '書事', '书事', '0a9829cc-805b-4812-a86a-1b2aee6a69ad', '唐', '["輕陰閣小雨，深院晝慵開。","坐看蒼苔色，欲上人衣來。"]', '["轻陰閣小雨，深院晝慵开。","坐看蒼苔色，欲上人衣来。"]', '诗', 'shi', '', NULL, '書事 王維 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d62dbf49-92b6-4702-91f7-3ba36a7426ed', '哭孟浩然', '哭孟浩然', '0a9829cc-805b-4812-a86a-1b2aee6a69ad', '唐', '["故人不可見，漢水日東流。","借問襄陽老，江山空蔡州。"]', '["故人不可见，漢水日东流。","借问襄陽老，江山空蔡州。"]', '诗', 'shi', '', NULL, '哭孟浩然 王維 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('67a1894f-99ea-4a24-8fcb-6c2a1a746df7', '闕題二首 一', '闕題二首 一', '0a9829cc-805b-4812-a86a-1b2aee6a69ad', '唐', '["荆谿白石出，天寒紅葉稀。","山路元無雨，空翠濕人衣。"]', '["荆谿白石出，天寒紅葉稀。","山路元無雨，空翠濕人衣。"]', '诗', 'shi', '', NULL, '闕題二首 一 王維 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('49ae1cda-2179-4ad8-a417-dcfb7e2d50f4', '闕題二首 二', '闕題二首 二', '0a9829cc-805b-4812-a86a-1b2aee6a69ad', '唐', '["相看不忍發，慘淡暮潮平。","語罷更攜手，月明洲渚生。"]', '["相看不忍發，慘淡暮潮平。","語罷更携手，月明洲渚生。"]', '诗', 'shi', '', NULL, '闕題二首 二 王維 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e14f7266-411e-4174-ba50-1f4dfbda03df', '田園樂七首 一', '田园乐七首 一', '0a9829cc-805b-4812-a86a-1b2aee6a69ad', '唐', '["厭見千門萬戶，經過北里南鄰。","官府鳴珂有底，崆峒散髪何人。"]', '["厭见千门万戶，經過北里南鄰。","官府鳴珂有底，崆峒散髪何人。"]', '诗', 'shi', '', NULL, '田園樂七首 一 王維 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6c2f3e5a-720b-4ba5-99fc-ff8e183d877f', '田園樂七首 二', '田园乐七首 二', '0a9829cc-805b-4812-a86a-1b2aee6a69ad', '唐', '["再見封侯萬戶，立談賜璧一雙。","詎勝耦耕南畝，何如高臥東窗。"]', '["再见封侯万戶，立談賜璧一雙。","詎勝耦耕南畝，何如高臥东窗。"]', '诗', 'shi', '', NULL, '田園樂七首 二 王維 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('56cda434-9d60-4129-986a-63fa53e2717e', '田園樂七首 三', '田园乐七首 三', '0a9829cc-805b-4812-a86a-1b2aee6a69ad', '唐', '["采菱渡頭風急，策杖林西日斜。","杏樹壇邊漁父，桃花源裏人家。"]', '["采菱渡头风急，策杖林西日斜。","杏樹壇邊漁父，桃花源裏人家。"]', '诗', 'shi', '', NULL, '田園樂七首 三 王維 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2cd621d8-f22f-470d-974a-d6ef2892171f', '田園樂七首 四', '田园乐七首 四', '0a9829cc-805b-4812-a86a-1b2aee6a69ad', '唐', '["萋萋春草秋綠，落落長松夏寒。","牛羊自歸村巷，童稚不識衣冠。"]', '["萋萋春草秋綠，落落长松夏寒。","牛羊自归村巷，童稚不識衣冠。"]', '诗', 'shi', '', NULL, '田園樂七首 四 王維 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7eb22383-1e34-4567-9d0c-f65e8f47dcbc', '田園樂七首 五', '田园乐七首 五', '0a9829cc-805b-4812-a86a-1b2aee6a69ad', '唐', '["山下孤煙遠村，天邊獨樹高原。","一瓢顏回陋巷，五柳先生對門。"]', '["山下孤煙远村，天邊独樹高原。","一瓢顏回陋巷，五柳先生对门。"]', '诗', 'shi', '', NULL, '田園樂七首 五 王維 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2316af2e-a85f-47a3-b02a-4ce3bb8a5c1c', '田園樂七首 六', '田园乐七首 六', '0a9829cc-805b-4812-a86a-1b2aee6a69ad', '唐', '["桃紅復含宿雨，柳綠更帶朝煙。","花落家童未埽，鶯啼山客猶眠。"]', '["桃紅复含宿雨，柳綠更带朝煙。","花落家童未埽，鶯啼山客猶眠。"]', '诗', 'shi', '', NULL, '田園樂七首 六 王維 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b7963345-bc64-4b64-a8d7-f316c2fcaf08', '田園樂七首 七', '田园乐七首 七', '0a9829cc-805b-4812-a86a-1b2aee6a69ad', '唐', '["酌酒會臨泉水，抱琴好倚長松。","南園露葵朝折，東谷黃粱夜舂。"]', '["酌酒會臨泉水，抱琴好倚长松。","南园露葵朝折，东谷黄粱夜舂。"]', '诗', 'shi', '', NULL, '田園樂七首 七 王維 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8b9762d3-db7a-4e3c-971a-cbd221d44531', '少年行四首 一', '少年行四首 一', '0a9829cc-805b-4812-a86a-1b2aee6a69ad', '唐', '["新豐美酒斗十千，咸陽遊俠多少年。","相逢意氣爲君飲，繫馬高樓垂柳邊。"]', '["新豐美酒斗十千，咸陽游俠多少年。","相逢意氣爲君饮，繫马高楼垂柳邊。"]', '诗', 'shi', '', NULL, '少年行四首 一 王維 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('38b9bb47-c5d9-47db-8ceb-f559e5ff6360', '少年行四首 二', '少年行四首 二', '0a9829cc-805b-4812-a86a-1b2aee6a69ad', '唐', '["出身仕漢羽林郎，初隨驃騎戰漁陽。","孰知不向邊庭苦，縱死猶聞俠骨香。"]', '["出身仕漢羽林郎，初隨驃騎戰漁陽。","孰知不向邊庭苦，縱死猶闻俠骨香。"]', '诗', 'shi', '', NULL, '少年行四首 二 王維 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('68da728b-4d10-4809-a687-5518098a1e0f', '少年行四首 三', '少年行四首 三', '0a9829cc-805b-4812-a86a-1b2aee6a69ad', '唐', '["一身能擘兩雕弧，虜騎千重只似無。","偏坐金鞍調白羽，紛紛射殺五單于。"]', '["一身能擘兩雕弧，虜騎千重只似無。","偏坐金鞍調白羽，紛紛射殺五單于。"]', '诗', 'shi', '', NULL, '少年行四首 三 王維 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('197fcb93-3d7f-4cf9-b6c4-410b48e7de14', '少年行四首 四', '少年行四首 四', '0a9829cc-805b-4812-a86a-1b2aee6a69ad', '唐', '["漢家君臣歡宴終，高議雲臺論戰功。","天子臨軒賜侯印，將軍佩出明光宮。"]', '["漢家君臣歡宴終，高議云台論戰功。","天子臨軒賜侯印，將軍佩出明光宮。"]', '诗', 'shi', '', NULL, '少年行四首 四 王維 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ed9dd23b-f793-4f7e-bfd8-6ec3ed562883', '贈裴旻將軍', '贈裴旻將軍', '0a9829cc-805b-4812-a86a-1b2aee6a69ad', '唐', '["腰間寶劒七星文，臂上琱弓百戰勳。","見說雲中擒黠虜，始知天上有將軍。"]', '["腰间寶劒七星文，臂上琱弓百戰勳。","见说云中擒黠虜，始知天上有將軍。"]', '诗', 'shi', '', NULL, '贈裴旻將軍 王維 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6bbd1c2c-8c43-4ffb-b7b3-506d74266cee', '九月九日憶山東兄弟', '九月九日憶山东兄弟', '0a9829cc-805b-4812-a86a-1b2aee6a69ad', '唐', '["獨在異鄉爲異客，每逢佳節倍思親。","遙知兄弟登高處，遍插茱萸少一人。"]', '["独在異乡爲異客，每逢佳節倍思親。","遙知兄弟登高处，遍插茱萸少一人。"]', '诗', 'shi', '', NULL, '九月九日憶山東兄弟 王維 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5ec02070-40de-468f-b0bc-398952a3f5e5', '送王尊師歸蜀中拜埽', '送王尊師归蜀中拜埽', '0a9829cc-805b-4812-a86a-1b2aee6a69ad', '唐', '["大羅天上神仙客，濯錦江頭花柳春。","不爲碧雞稱使者，唯令白鶴報鄉人。"]', '["大羅天上神仙客，濯錦江头花柳春。","不爲碧雞稱使者，唯令白鹤報乡人。"]', '诗', 'shi', '', NULL, '送王尊師歸蜀中拜埽 王維 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1575c835-1241-4d7b-99dc-6d700549ac65', '渭城曲', '渭城曲', '0a9829cc-805b-4812-a86a-1b2aee6a69ad', '唐', '["渭城朝雨浥輕塵，客舍青青楊柳春。","勸君更盡一杯酒，西出陽關無故人。"]', '["渭城朝雨浥轻塵，客舍青青楊柳春。","勸君更尽一杯酒，西出陽关無故人。"]', '诗', 'shi', '', NULL, '渭城曲 王維 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5f24766a-64cd-46cb-b588-23cb7ed7cd45', '齊州送祖二', '齊州送祖二', '0a9829cc-805b-4812-a86a-1b2aee6a69ad', '唐', '["送君南浦淚如絲，君向東州使我悲。","爲報故人顦顇盡，如今不似洛陽時。"]', '["送君南浦泪如絲，君向东州使我悲。","爲報故人顦顇尽，如今不似洛陽时。"]', '诗', 'shi', '', NULL, '齊州送祖二 王維 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f22070fb-28bc-405a-ba8b-ca5f053796de', '送韋評事', '送韋評事', '0a9829cc-805b-4812-a86a-1b2aee6a69ad', '唐', '["欲逐將軍取右賢，沙場走馬向居延。","遙知漢使蕭關外，愁見孤城落日邊。"]', '["欲逐將軍取右賢，沙場走马向居延。","遙知漢使蕭关外，愁见孤城落日邊。"]', '诗', 'shi', '', NULL, '送韋評事 王維 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('846980bc-1386-4423-9de6-b96299dff005', '靈雲池送從弟', '靈云池送從弟', '0a9829cc-805b-4812-a86a-1b2aee6a69ad', '唐', '["金杯緩酌清歌轉，畫舸輕移豔舞回。","自歎鶺鴒臨水別，不同鴻鴈向池來。"]', '["金杯緩酌清歌轉，畫舸轻移豔舞回。","自歎鶺鴒臨水別，不同鴻鴈向池来。"]', '诗', 'shi', '', NULL, '靈雲池送從弟 王維 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('231ffdfc-9391-4da4-94e8-e7e9da35925d', '送沈子歸江東', '送沈子归江东', '0a9829cc-805b-4812-a86a-1b2aee6a69ad', '唐', '["楊柳渡頭行客稀，罟師盪槳向臨圻。","唯有相思似春色，江南江北送君歸。"]', '["楊柳渡头行客稀，罟師盪槳向臨圻。","唯有相思似春色，江南江北送君归。"]', '诗', 'shi', '', NULL, '送沈子歸江東 王維 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('cb9611dd-54cd-4786-a742-7f1e83590d47', '與盧員外象過崔處士興宗林亭', '與盧員外象過崔处士兴宗林亭', '0a9829cc-805b-4812-a86a-1b2aee6a69ad', '唐', '["綠樹重陰蓋四鄰，青苔日厚自無塵。","科頭箕踞長松下，白眼看他世上人。"]', '["綠樹重陰蓋四鄰，青苔日厚自無塵。","科头箕踞长松下，白眼看他世上人。"]', '诗', 'shi', '', NULL, '與盧員外象過崔處士興宗林亭 王維 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('018f0c47-778c-4bed-b6b3-e177cfc24a4d', '寒食汜上作', '寒食汜上作', '0a9829cc-805b-4812-a86a-1b2aee6a69ad', '唐', '["廣武城邊逢暮春，汶陽歸客淚沾巾。","落花寂寂啼山鳥，楊柳青青渡水人。"]', '["廣武城邊逢暮春，汶陽归客泪沾巾。","落花寂寂啼山鸟，楊柳青青渡水人。"]', '诗', 'shi', '', NULL, '寒食汜上作 王維 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c7916293-1cd3-430c-abd7-1cda964d805d', '戲題輞川別業', '戲題輞川別業', '0a9829cc-805b-4812-a86a-1b2aee6a69ad', '唐', '["柳條拂地不須折，松樹披雲從更長。","藤花欲暗藏猱子，柏葉初齊養麝香。"]', '["柳條拂地不須折，松樹披云從更长。","藤花欲暗藏猱子，柏葉初齊養麝香。"]', '诗', 'shi', '', NULL, '戲題輞川別業 王維 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3d367cb6-b80e-4650-94d2-c269f0c1c0c5', '戲題盤石', '戲題盤石', '0a9829cc-805b-4812-a86a-1b2aee6a69ad', '唐', '["可憐盤石臨泉水，復有垂楊拂酒杯。","若道春風不解意，何因吹送落花來。"]', '["可怜盤石臨泉水，复有垂楊拂酒杯。","若道春风不解意，何因吹送落花来。"]', '诗', 'shi', '', NULL, '戲題盤石 王維 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('07ddc694-2365-4fa8-88ff-51f98c21eb8a', '寄河上段十六', '寄河上段十六', '0a9829cc-805b-4812-a86a-1b2aee6a69ad', '唐', '["與君相見即相親，聞道君家在孟津。","爲見行舟試借問，客中時有洛陽人。"]', '["與君相见即相親，闻道君家在孟津。","爲见行舟試借问，客中时有洛陽人。"]', '诗', 'shi', '', NULL, '寄河上段十六 王維 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8d6a0fe6-6ba6-46e7-b9ec-a946e34f4451', '菩提寺禁裴迪來相看說逆賊等凝碧池上作音樂供奉人等舉聲便一時淚下私成口號誦示裴迪', '菩提寺禁裴迪来相看说逆賊等凝碧池上作音乐供奉人等舉声便一时泪下私成口號誦示裴迪', '0a9829cc-805b-4812-a86a-1b2aee6a69ad', '唐', '["萬戶傷心生野煙，百僚何日更朝天。","秋槐葉落空宮裏，凝碧池頭奏管弦。"]', '["万戶傷心生野煙，百僚何日更朝天。","秋槐葉落空宮裏，凝碧池头奏管弦。"]', '诗', 'shi', '', NULL, '菩提寺禁裴迪來相看說逆賊等凝碧池上作音樂供奉人等舉聲便一時淚下私成口號誦示裴迪 王維 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f213838d-b51a-46aa-bbac-938e97a130ca', '涼州賽神', '涼州賽神', '0a9829cc-805b-4812-a86a-1b2aee6a69ad', '唐', '["涼州城外少行人，百尺峰頭望虜塵。","健兒擊鼓吹羌笛，共賽城東越騎神。"]', '["涼州城外少行人，百尺峰头望虜塵。","健兒擊鼓吹羌笛，共賽城东越騎神。"]', '诗', 'shi', '', NULL, '涼州賽神 王維 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0ad30318-2c99-4071-9cca-554ec9b3b714', '劇嘲史寰', '劇嘲史寰', '0a9829cc-805b-4812-a86a-1b2aee6a69ad', '唐', '["清風細雨濕梅花，驟馬先過碧玉家。","正值楚王宮裏至，門前初下七香車。"]', '["清风細雨濕梅花，驟马先過碧玉家。","正值楚王宮裏至，门前初下七香车。"]', '诗', 'shi', '', NULL, '劇嘲史寰 王維 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d87b6c44-9bb7-476f-84a5-8b61f9b6a897', '歎白髪', '歎白髪', '0a9829cc-805b-4812-a86a-1b2aee6a69ad', '唐', '["宿昔朱顏成暮齒，須臾白髮變垂髫。","一生幾許傷心事，不向空門何處銷。"]', '["宿昔朱顏成暮齒，須臾白髮变垂髫。","一生幾許傷心事，不向空门何处銷。"]', '诗', 'shi', '', NULL, '歎白髪 王維 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9467ebe1-1199-4266-8bab-19a36e802528', '伊州歌', '伊州歌', '0a9829cc-805b-4812-a86a-1b2aee6a69ad', '唐', '["清風明月苦相思，蕩子從戎十載餘。","征人去日慇懃囑，歸鴈來時數附書。"]', '["清风明月苦相思，蕩子從戎十載餘。","征人去日慇懃囑，归鴈来时數附书。"]', '诗', 'shi', '', NULL, '伊州歌 王維 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c19bb4cf-209a-41e1-976e-12ebd5cf80c9', '送殷四葬', '送殷四葬', '0a9829cc-805b-4812-a86a-1b2aee6a69ad', '唐', '["送君返葬石樓山，松栢蒼蒼賓馭還。","埋骨白雲長已矣，空餘流水向人間。"]', '["送君返葬石楼山，松栢蒼蒼賓馭還。","埋骨白云长已矣，空餘流水向人间。"]', '诗', 'shi', '', NULL, '送殷四葬 王維 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b127c5e6-e6b6-4add-8498-ea680b6777c9', '疑夢', '疑梦', '0a9829cc-805b-4812-a86a-1b2aee6a69ad', '唐', '["莫驚寵辱空憂喜，莫計恩讐浪苦辛。","黃帝孔丘何處問？安知不是夢中身。"]', '["莫驚寵辱空憂喜，莫計恩讐浪苦辛。","黄帝孔丘何处问？安知不是梦中身。"]', '诗', 'shi', '', NULL, '疑夢 王維 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('769d0ad2-d240-43b1-a515-1a26982fcb1e', '句', '句', '0a9829cc-805b-4812-a86a-1b2aee6a69ad', '唐', '["人家在仙掌，雲氣欲生衣。"]', '["人家在仙掌，云氣欲生衣。"]', '诗', 'shi', '', NULL, '句 王維 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6eb8ccd6-e133-49ef-b72d-b6cab287a82c', '古離別', '古離別', '2ade647f-1bae-48ff-94d0-3b438f1df412', '唐', '["下階欲離別，相對映蘭叢。","含辭未及吐，淚落蘭叢中。","高堂靜秋日，羅衣飄暮風。","誰能待明月，迴首見牀空。"]', '["下階欲離別，相对映蘭叢。","含辞未及吐，泪落蘭叢中。","高堂静秋日，羅衣飄暮风。","誰能待明月，迴首见牀空。"]', '诗', 'shi', '', NULL, '古離別 王縉 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0981a458-9ce7-48cf-a772-7bfcf02dac07', '青雀歌', '青雀歌', '2ade647f-1bae-48ff-94d0-3b438f1df412', '唐', '["林間青雀兒，來往翩翩繞一枝。","莫言不解銜環報，但聞君恩今若爲。"]', '["林间青雀兒，来往翩翩繞一枝。","莫言不解銜环報，但闻君恩今若爲。"]', '诗', 'shi', '', NULL, '青雀歌 王縉 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8e1a16be-f7f7-4427-906a-f50539d1d660', '同王昌齡裴迪游青龍寺曇壁上人兄院集和兄維', '同王昌齡裴迪游青龙寺曇壁上人兄院集和兄維', '2ade647f-1bae-48ff-94d0-3b438f1df412', '唐', '["林中空寂舍，階下終南山。","高臥一牀上，迴看六合間。","浮雲幾處滅，飛鳥何時還？","問義天人接，無心世界閑。","誰知大隱者，兄弟自追攀。"]', '["林中空寂舍，階下終南山。","高臥一牀上，迴看六合间。","浮云幾处滅，飞鸟何时還？","问義天人接，無心世界闲。","誰知大隐者，兄弟自追攀。"]', '诗', 'shi', '', NULL, '同王昌齡裴迪游青龍寺曇壁上人兄院集和兄維 王縉 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d7c1ef67-0a2d-4e29-9f2b-eb708b1d0e3c', '別輞川別業', '別輞川別業', '2ade647f-1bae-48ff-94d0-3b438f1df412', '唐', '["山月曉仍在，林風涼不絕。","殷勤如有情，惆悵令人別。"]', '["山月晓仍在，林风涼不絕。","殷勤如有情，惆悵令人別。"]', '诗', 'shi', '', NULL, '別輞川別業 王縉 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ce266c4c-8ea4-4881-8e99-b47e875f57fb', '與盧員外象過崔處士興宗林亭', '與盧員外象過崔处士兴宗林亭', '2ade647f-1bae-48ff-94d0-3b438f1df412', '唐', '["身名不問十年餘，老大誰能更讀書。","林中獨酌鄰家酒，門外時聞長者車。"]', '["身名不问十年餘，老大誰能更读书。","林中独酌鄰家酒，门外时闻长者车。"]', '诗', 'shi', '', NULL, '與盧員外象過崔處士興宗林亭 王縉 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3ed9907e-4a5b-47d6-871a-e44d3a12e110', '九日作', '九日作', '2ade647f-1bae-48ff-94d0-3b438f1df412', '唐', '["莫將邊地比京都，八月嚴霜草已枯。","今日登高樽酒裏，不知能有菊花無。"]', '["莫將邊地比京都，八月嚴霜草已枯。","今日登高樽酒裏，不知能有菊花無。"]', '诗', 'shi', '', NULL, '九日作 王縉 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d9653d68-6f76-49ee-886d-79be414e16aa', '送孫秀才', '送孫秀才', '2ade647f-1bae-48ff-94d0-3b438f1df412', '唐', '["帝城風日好，況復建平家。","玉枕雙紋簟，金盤五色瓜。","山中無魯酒，松下飯胡麻。","莫厭田家苦，歸期遠復賒。"]', '["帝城风日好，況复建平家。","玉枕雙紋簟，金盤五色瓜。","山中無魯酒，松下飯胡麻。","莫厭田家苦，归期远复賒。"]', '诗', 'shi', '', NULL, '送孫秀才 王縉 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('dfc624c2-9767-465d-a4f8-0ebdf0a5d84e', '游悟真寺', '游悟真寺', '2ade647f-1bae-48ff-94d0-3b438f1df412', '唐', '["聞道黃金地，仍開白玉田。","擲山移巨石，呪嶺出飛泉。","猛虎同三徑，愁猨學四禪。","買香然綠桂，乞火蹈紅蓮。","草色搖霞上，松聲泛月邊。","山河窮百二，世界接三千。","梵宇聊憑視，王城遂渺然。","灞陵纔出樹，渭水欲連天。","遠縣分朱郭，孤村起白煙。","望雲思聖主，披霧憶羣賢。","薄宦慚尸素，終身擬尚玄。","誰知草菴客，曾和柏梁篇。"]', '["闻道黄金地，仍开白玉田。","擲山移巨石，呪嶺出飞泉。","猛虎同三徑，愁猨学四禪。","買香然綠桂，乞火蹈紅蓮。","草色搖霞上，松声泛月邊。","山河窮百二，世界接三千。","梵宇聊憑視，王城遂渺然。","灞陵纔出樹，渭水欲連天。","远縣分朱郭，孤村起白煙。","望云思聖主，披霧憶羣賢。","薄宦慚尸素，終身擬尚玄。","誰知草菴客，曾和柏梁篇。"]', '诗', 'shi', '', NULL, '游悟真寺 王縉 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4b90d9ee-d6fb-4542-b97a-4103f36cf0dc', '青龍寺曇壁上人院集', '青龙寺曇壁上人院集', '2cbeff03-918b-4378-8f1d-2f8f6947fd3d', '唐', '["靈境信爲絕，法堂出塵氛。","自然成高致，向下看浮雲。","迤邐峯岫列，參差閭井分。","林端遠堞見，風末疎鐘聞。","吾師久禪寂，在世超人羣。"]', '["靈境信爲絕，法堂出塵氛。","自然成高致，向下看浮云。","迤邐峯岫列，參差閭井分。","林端远堞见，风末疎鐘闻。","吾師久禪寂，在世超人羣。"]', '诗', 'shi', '', NULL, '青龍寺曇壁上人院集 裴迪 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ade16151-3b5d-4df6-9651-ccea2ded6697', '青雀歌', '青雀歌', '2cbeff03-918b-4378-8f1d-2f8f6947fd3d', '唐', '["動息自適性，不曾妄與燕雀羣。","幸忝鵷鸞早相識，何時提攜致青雲。"]', '["动息自適性，不曾妄與燕雀羣。","幸忝鵷鸾早相識，何时提携致青云。"]', '诗', 'shi', '', NULL, '青雀歌 裴迪 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('67603c99-bce1-498b-8942-e6c9414fbfff', '游感化寺曇興上人山院', '游感化寺曇兴上人山院', '2cbeff03-918b-4378-8f1d-2f8f6947fd3d', '唐', '["不遠灞陵邊，安居向十年。","入門穿竹徑，留客聽山泉。","鳥囀深林裏，心閑落照前。","浮名竟何益，從此願棲禪。"]', '["不远灞陵邊，安居向十年。","入门穿竹徑，留客听山泉。","鸟囀深林裏，心闲落照前。","浮名竟何益，從此願棲禪。"]', '诗', 'shi', '', NULL, '游感化寺曇興上人山院 裴迪 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a4119211-2b4f-4c92-ad5b-c66316617f7d', '夏日過青龍寺謁操禪師', '夏日過青龙寺謁操禪師', '2cbeff03-918b-4378-8f1d-2f8f6947fd3d', '唐', '["安禪一室內，左右竹亭幽。","有法知不染，無言誰敢酬。","鳥飛爭向夕，蟬噪已先秋。","煩暑自茲適，清涼何所求。"]', '["安禪一室內，左右竹亭幽。","有法知不染，無言誰敢酬。","鸟飞爭向夕，蟬噪已先秋。","煩暑自茲適，清涼何所求。"]', '诗', 'shi', '', NULL, '夏日過青龍寺謁操禪師 裴迪 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('fce06ca0-8b8f-4ce9-b83b-425e062ecbce', '春日與王右丞過新昌里訪呂逸人不遇', '春日與王右丞過新昌里訪呂逸人不遇', '2cbeff03-918b-4378-8f1d-2f8f6947fd3d', '唐', '["恨不逢君出荷簑，青松白屋更無他。","陶令五男曾不有，蔣生三徑枉相過。","芙蓉曲沼春流滿，薜荔成帷晚靄多。","聞說桃源好迷客，不如高臥眄庭柯。"]', '["恨不逢君出荷簑，青松白屋更無他。","陶令五男曾不有，蔣生三徑枉相過。","芙蓉曲沼春流满，薜荔成帷晚靄多。","闻说桃源好迷客，不如高臥眄庭柯。"]', '诗', 'shi', '', NULL, '春日與王右丞過新昌里訪呂逸人不遇 裴迪 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b34a9b93-5468-4d42-8ba3-31d96800e35f', '輞川集二十首 孟城坳', '輞川集二十首 孟城坳', '2cbeff03-918b-4378-8f1d-2f8f6947fd3d', '唐', '["結廬古城下，時登古城上。","古城非疇昔，今人自來往。"]', '["結廬古城下，时登古城上。","古城非疇昔，今人自来往。"]', '诗', 'shi', '', NULL, '輞川集二十首 孟城坳 裴迪 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('83826cc8-6c57-4077-99a5-229fbf535242', '輞川集二十首 華子岡', '輞川集二十首 华子岡', '2cbeff03-918b-4378-8f1d-2f8f6947fd3d', '唐', '["落日松風起，還家草露晞。","雲光侵履跡，山翠拂人衣。"]', '["落日松风起，還家草露晞。","云光侵履跡，山翠拂人衣。"]', '诗', 'shi', '', NULL, '輞川集二十首 華子岡 裴迪 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7793742e-91e5-4b24-8c53-5acb9abf40c3', '輞川集二十首 文杏館', '輞川集二十首 文杏館', '2cbeff03-918b-4378-8f1d-2f8f6947fd3d', '唐', '["迢迢文杏館，躋攀日已屢。","南嶺與北湖，前看復迴顧。"]', '["迢迢文杏館，躋攀日已屢。","南嶺與北湖，前看复迴顧。"]', '诗', 'shi', '', NULL, '輞川集二十首 文杏館 裴迪 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c8a8c0bc-de30-42bf-855c-580ead6cb836', '輞川集二十首 斤竹嶺', '輞川集二十首 斤竹嶺', '2cbeff03-918b-4378-8f1d-2f8f6947fd3d', '唐', '["明流紆且直，綠篠密復深。","一徑通山路，行歌望舊岑。"]', '["明流紆且直，綠篠密复深。","一徑通山路，行歌望旧岑。"]', '诗', 'shi', '', NULL, '輞川集二十首 斤竹嶺 裴迪 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c8fd9bf2-7c9b-4e6e-8d7b-efc201215317', '輞川集二十首 鹿柴', '輞川集二十首 鹿柴', '2cbeff03-918b-4378-8f1d-2f8f6947fd3d', '唐', '["日夕見寒山，便爲獨往客。","不知深林事，但有麏麚跡。"]', '["日夕见寒山，便爲独往客。","不知深林事，但有麏麚跡。"]', '诗', 'shi', '', NULL, '輞川集二十首 鹿柴 裴迪 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1094b0eb-6b7d-44a6-9163-4d0c20a2735a', '輞川集二十首 木蘭柴', '輞川集二十首 木蘭柴', '2cbeff03-918b-4378-8f1d-2f8f6947fd3d', '唐', '["蒼蒼落日時，鳥聲亂谿水。","緣谿路轉深，幽興何時已。"]', '["蒼蒼落日时，鸟声亂谿水。","緣谿路轉深，幽兴何时已。"]', '诗', 'shi', '', NULL, '輞川集二十首 木蘭柴 裴迪 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4a4900ec-5231-484d-937a-1beca1a5dfa9', '輞川集二十首 茱萸沜', '輞川集二十首 茱萸沜', '2cbeff03-918b-4378-8f1d-2f8f6947fd3d', '唐', '["飄香亂椒桂，布葉間檀欒。","雲日雖迴照，森沈猶自寒。"]', '["飄香亂椒桂，布葉间檀欒。","云日雖迴照，森沈猶自寒。"]', '诗', 'shi', '', NULL, '輞川集二十首 茱萸沜 裴迪 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f9b59f8b-649e-4454-a94a-75bc4d135c11', '輞川集二十首 宮槐陌', '輞川集二十首 宮槐陌', '2cbeff03-918b-4378-8f1d-2f8f6947fd3d', '唐', '["門前宮槐陌，是向欹湖道。","秋來山雨多，落葉無人掃。"]', '["门前宮槐陌，是向欹湖道。","秋来山雨多，落葉無人掃。"]', '诗', 'shi', '', NULL, '輞川集二十首 宮槐陌 裴迪 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('59b3c1c3-f8ab-40a7-a063-026cfc36ed1b', '輞川集二十首 臨湖亭', '輞川集二十首 臨湖亭', '2cbeff03-918b-4378-8f1d-2f8f6947fd3d', '唐', '["當軒彌滉漾，孤月正裴回。","谷口猨聲發，風傳入戶來。"]', '["當軒彌滉漾，孤月正裴回。","谷口猨声發，风傳入戶来。"]', '诗', 'shi', '', NULL, '輞川集二十首 臨湖亭 裴迪 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('efcb469c-0c7a-4ba9-9d04-cdbbddf7dcce', '輞川集二十首 南垞', '輞川集二十首 南垞', '2cbeff03-918b-4378-8f1d-2f8f6947fd3d', '唐', '["孤舟信一泊，南垞湖水岸。","落日下崦嵫，清波殊淼漫。"]', '["孤舟信一泊，南垞湖水岸。","落日下崦嵫，清波殊淼漫。"]', '诗', 'shi', '', NULL, '輞川集二十首 南垞 裴迪 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('de2f613f-be2f-4a1d-96fd-f65d062ad782', '輞川集二十首 欹湖', '輞川集二十首 欹湖', '2cbeff03-918b-4378-8f1d-2f8f6947fd3d', '唐', '["空闊湖水廣，青熒天色同。","艤舟一長嘯，四面來清風。"]', '["空闊湖水廣，青熒天色同。","艤舟一长嘯，四面来清风。"]', '诗', 'shi', '', NULL, '輞川集二十首 欹湖 裴迪 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('90de5ee8-abdd-480a-98bd-0e1605fa462c', '輞川集二十首 柳浪', '輞川集二十首 柳浪', '2cbeff03-918b-4378-8f1d-2f8f6947fd3d', '唐', '["映池同一色，逐吹散如絲。","結陰既得地，何謝陶家時。"]', '["映池同一色，逐吹散如絲。","結陰既得地，何謝陶家时。"]', '诗', 'shi', '', NULL, '輞川集二十首 柳浪 裴迪 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a5860521-866e-4429-b55b-0b5ec10e4ceb', '輞川集二十首 欒家瀨', '輞川集二十首 欒家瀨', '2cbeff03-918b-4378-8f1d-2f8f6947fd3d', '唐', '["瀨聲喧極浦，沿涉向南津。","汎汎鷗鳧渡，時時欲近人。"]', '["瀨声喧極浦，沿涉向南津。","汎汎鷗鳧渡，时时欲近人。"]', '诗', 'shi', '', NULL, '輞川集二十首 欒家瀨 裴迪 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('323950c1-288d-4ace-a2a5-a9e5cb106a23', '輞川集二十首 金屑泉', '輞川集二十首 金屑泉', '2cbeff03-918b-4378-8f1d-2f8f6947fd3d', '唐', '["縈渟澹不流，金碧如可拾。","迎晨含素華，獨往事朝汲。"]', '["縈渟澹不流，金碧如可拾。","迎晨含素华，独往事朝汲。"]', '诗', 'shi', '', NULL, '輞川集二十首 金屑泉 裴迪 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6ab0ff23-712e-4e47-9125-189ecc4a97b6', '輞川集二十首 白石灘', '輞川集二十首 白石灘', '2cbeff03-918b-4378-8f1d-2f8f6947fd3d', '唐', '["跂石復臨水，弄波情未極。","日下川上寒，浮雲澹無色。"]', '["跂石复臨水，弄波情未極。","日下川上寒，浮云澹無色。"]', '诗', 'shi', '', NULL, '輞川集二十首 白石灘 裴迪 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('50dfe307-13f1-4119-9c17-c250160ce72c', '輞川集二十首 北垞', '輞川集二十首 北垞', '2cbeff03-918b-4378-8f1d-2f8f6947fd3d', '唐', '["南山北垞下，結宇臨欹湖。","每欲采樵去，扁舟出菰蒲。"]', '["南山北垞下，結宇臨欹湖。","每欲采樵去，扁舟出菰蒲。"]', '诗', 'shi', '', NULL, '輞川集二十首 北垞 裴迪 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c9c85878-f0a0-4883-8b30-193c1023ca56', '輞川集二十首 竹里館', '輞川集二十首 竹里館', '2cbeff03-918b-4378-8f1d-2f8f6947fd3d', '唐', '["來過竹里館，日與道相親。","出入唯山鳥，幽深無世人。"]', '["来過竹里館，日與道相親。","出入唯山鸟，幽深無世人。"]', '诗', 'shi', '', NULL, '輞川集二十首 竹里館 裴迪 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a6ddecc2-6f13-492c-bf3c-84f31d6ca5ad', '輞川集二十首 辛夷塢', '輞川集二十首 辛夷塢', '2cbeff03-918b-4378-8f1d-2f8f6947fd3d', '唐', '["綠堤春草合，王孫自留玩/。","況有辛夷花，色與芙蓉亂。"]', '["綠堤春草合，王孫自留玩/。","況有辛夷花，色與芙蓉亂。"]', '诗', 'shi', '', NULL, '輞川集二十首 辛夷塢 裴迪 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c5897a87-badf-4b3f-9ae3-e78e8b372711', '輞川集二十首 漆園', '輞川集二十首 漆园', '2cbeff03-918b-4378-8f1d-2f8f6947fd3d', '唐', '["好閑早成性，果此諧宿諾。","今日漆園游，還同莊叟樂。"]', '["好闲早成性，果此諧宿諾。","今日漆园游，還同莊叟乐。"]', '诗', 'shi', '', NULL, '輞川集二十首 漆園 裴迪 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b2ea3aae-b19b-45fc-aa75-3b2d82dea855', '輞川集二十首 椒園', '輞川集二十首 椒园', '2cbeff03-918b-4378-8f1d-2f8f6947fd3d', '唐', '["丹刺罥人衣，芳香留過客。","幸堪調鼎用，願君垂采摘。"]', '["丹刺罥人衣，芳香留過客。","幸堪調鼎用，願君垂采摘。"]', '诗', 'shi', '', NULL, '輞川集二十首 椒園 裴迪 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('235f7fe7-c38e-4ae3-a6b1-61dc243d70e9', '輞口遇雨憶終南山因獻王維', '輞口遇雨憶終南山因獻王維', '2cbeff03-918b-4378-8f1d-2f8f6947fd3d', '唐', '["積雨晦空曲，平沙滅浮彩。","輞水去悠悠，南山復何在。"]', '["積雨晦空曲，平沙滅浮彩。","輞水去悠悠，南山复何在。"]', '诗', 'shi', '', NULL, '輞口遇雨憶終南山因獻王維 裴迪 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('80fe70cd-6e63-48eb-9c1e-ab26330d45d9', '崔九欲往南山馬上口號與別', '崔九欲往南山马上口號與別', '2cbeff03-918b-4378-8f1d-2f8f6947fd3d', '唐', '["歸山深淺去，須盡丘壑美。","莫學武陵人，暫游桃源裏。"]', '["归山深淺去，須尽丘壑美。","莫学武陵人，暫游桃源裏。"]', '诗', 'shi', '', NULL, '崔九欲往南山馬上口號與別 裴迪 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d167e7a6-27cd-4e62-896c-4f370d0f1ac0', '與盧員外象過崔處士興宗林亭', '與盧員外象過崔处士兴宗林亭', '2cbeff03-918b-4378-8f1d-2f8f6947fd3d', '唐', '["喬柯門裏自成陰，散髪窗中曾不簪。","逍遙且喜從吾事，榮寵從來非我心。"]', '["喬柯门裏自成陰，散髪窗中曾不簪。","逍遙且喜從吾事，榮寵從来非我心。"]', '诗', 'shi', '', NULL, '與盧員外象過崔處士興宗林亭 裴迪 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2800ce85-c57a-44f4-97a2-7556f4ef6599', '西塔寺陸羽茶泉', '西塔寺陸羽茶泉', '2cbeff03-918b-4378-8f1d-2f8f6947fd3d', '唐', '["竟陵西塔寺，蹤跡尚空虛。","不獨支公住，曾經陸羽居。","草堂荒產蛤，茶井冷生魚。","一汲清泠水，高風味有餘。"]', '["竟陵西塔寺，蹤跡尚空虛。","不独支公住，曾經陸羽居。","草堂荒產蛤，茶井冷生鱼。","一汲清泠水，高风味有餘。"]', '诗', 'shi', '', NULL, '西塔寺陸羽茶泉 裴迪 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4341fe0b-1ecc-42bd-9ba1-1f8e5747487a', '同王右丞送瑗公南歸', '同王右丞送瑗公南归', 'ca0e7cda-2f10-4c00-a9a1-bd13a222aa5d', '唐', '["行苦神亦秀，泠然谿上松。","銅瓶與竹杖，來自祝融峯。","常願入靈嶽，藏經訪遺蹤。","南歸見長老，且爲說心胸。"]', '["行苦神亦秀，泠然谿上松。","銅瓶與竹杖，来自祝融峯。","常願入靈嶽，藏經訪遺蹤。","南归见长老，且爲说心胸。"]', '诗', 'shi', '', NULL, '同王右丞送瑗公南歸 崔興宗 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('aea66f01-b52d-4465-a4fc-957be819260f', '青雀歌', '青雀歌', 'ca0e7cda-2f10-4c00-a9a1-bd13a222aa5d', '唐', '["青扈繞青林，翩翾陋體一微禽。","不應常在藩籬下，他日凌雲誰見心。"]', '["青扈繞青林，翩翾陋體一微禽。","不應常在藩籬下，他日凌云誰见心。"]', '诗', 'shi', '', NULL, '青雀歌 崔興宗 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('eccc5785-e6b3-4163-97cd-220197deb69f', '和王維敕賜百官櫻桃', '和王維敕賜百官櫻桃', 'ca0e7cda-2f10-4c00-a9a1-bd13a222aa5d', '唐', '["未央朝謁正逶迤，天上櫻桃錫此時。","朱實初傳九華殿，繁花舊雜萬年枝。","未勝晏子江南橘，莫比潘家大谷梨。","聞道令人好顏色，神農本草自應知。"]', '["未央朝謁正逶迤，天上櫻桃錫此时。","朱實初傳九华殿，繁花旧杂万年枝。","未勝晏子江南橘，莫比潘家大谷梨。","闻道令人好顏色，神農本草自應知。"]', '诗', 'shi', '', NULL, '和王維敕賜百官櫻桃 崔興宗 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2da5559c-7539-479d-b13b-6d75c85666e7', '留別王維', '留別王維', 'ca0e7cda-2f10-4c00-a9a1-bd13a222aa5d', '唐', '["駐馬欲分襟，清寒御溝上。","前山景氣佳，獨往還惆悵。"]', '["駐马欲分襟，清寒御溝上。","前山景氣佳，独往還惆悵。"]', '诗', 'shi', '', NULL, '留別王維 崔興宗 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e28c6884-bd9c-454d-afe6-8a25ade368c1', '酬王維盧象見過林亭', '酬王維盧象见過林亭', 'ca0e7cda-2f10-4c00-a9a1-bd13a222aa5d', '唐', '["窮巷空林常閉關，悠然獨臥對前山。","今朝忽枉嵇生駕，倒屣開門遙解顏。"]', '["窮巷空林常閉关，悠然独臥对前山。","今朝忽枉嵇生駕，倒屣开门遙解顏。"]', '诗', 'shi', '', NULL, '酬王維盧象見過林亭 崔興宗 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b267adc5-95ed-480d-aa91-4fbbcd274037', '送大理正攝御史判涼州別駕', '送大理正攝御史判涼州別駕', 'dd54760d-e494-4203-8973-dc3166763b6b', '唐', '["天子念西疆，咨君去不遑。","垂銀棘庭印，持斧柏臺綱。","雪下天山白，泉枯塞草黃。","佇聞河隴外，還繼海沂康。"]', '["天子念西疆，咨君去不遑。","垂銀棘庭印，持斧柏台綱。","雪下天山白，泉枯塞草黄。","佇闻河隴外，還繼海沂康。"]', '诗', 'shi', '', NULL, '送大理正攝御史判涼州別駕 苑咸 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('39657608-2f0c-4348-b4bb-f2fd51107487', '酬王維', '酬王維', 'dd54760d-e494-4203-8973-dc3166763b6b', '唐', '["蓮花梵字本從天，華省仙郎早悟禪。","三點成伊猶有想，一觀如幻自忘筌。","爲文已變當時體，入用還推間氣賢。","應同羅漢無名欲，故作馮唐老歲年。"]', '["蓮花梵字本從天，华省仙郎早悟禪。","三点成伊猶有想，一观如幻自忘筌。","爲文已变當时體，入用還推间氣賢。","應同羅漢無名欲，故作馮唐老歲年。"]', '诗', 'shi', '', NULL, '酬王維 苑咸 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('10a0aedc-4b39-494b-a36c-28c6df28a668', '尋西山隱者不遇', '尋西山隐者不遇', '848118cd-09ab-4bb1-a9f0-c87d2f8e18e0', '唐', '["絕頂一茅茨，直[上]三十里。","扣關無僮僕，窺室唯案几。","若非巾柴車，應是釣秋水。","差池不相見，黽勉空仰止。","草色新雨中，松聲晚牕裏。","及茲契幽絕，自足蕩心耳。","雖無賓主意，頗得清淨理。","興盡方下山，何必待之子。"]', '["絕頂一茅茨，直[上]三十里。","扣关無僮僕，窺室唯案几。","若非巾柴车，應是釣秋水。","差池不相见，黽勉空仰止。","草色新雨中，松声晚牕裏。","及茲契幽絕，自足蕩心耳。","雖無賓主意，頗得清淨理。","兴尽方下山，何必待之子。"]', '诗', 'shi', '', NULL, '尋西山隱者不遇 丘爲 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9aeb5732-c7ee-479b-9d29-0db95e051ddd', '題農父廬舍', '題農父廬舍', '848118cd-09ab-4bb1-a9f0-c87d2f8e18e0', '唐', '["東風何時至，已綠湖上山。","湖上春已早，田家日不閑。","溝塍流水處，耒耜平蕪間。","薄暮飯牛罷，歸來還閉關。"]', '["东风何时至，已綠湖上山。","湖上春已早，田家日不闲。","溝塍流水处，耒耜平蕪间。","薄暮飯牛罷，归来還閉关。"]', '诗', 'shi', '', NULL, '題農父廬舍 丘爲 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('eb438c61-efde-4ba3-80ea-a90d58368f72', '泛若耶谿', '泛若耶谿', '848118cd-09ab-4bb1-a9f0-c87d2f8e18e0', '唐', '["結廬若耶裏，左右若耶水。","無日不釣魚，有時向城市。","溪中水流急，渡口水流寬。","每得樵風便，往來殊不難。","一川草長綠，四時那得辨。","短褐衣妻兒，餘糧及雞犬。","日暮鳥雀稀，稚子呼牛歸。","住處無鄰里，柴門獨掩扉。"]', '["結廬若耶裏，左右若耶水。","無日不釣鱼，有时向城市。","溪中水流急，渡口水流寬。","每得樵风便，往来殊不难。","一川草长綠，四时那得辨。","短褐衣妻兒，餘糧及雞犬。","日暮鸟雀稀，稚子呼牛归。","住处無鄰里，柴门独掩扉。"]', '诗', 'shi', '', NULL, '泛若耶谿 丘爲 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6e77adaa-1c48-4a70-9214-b4be3c39ce41', '湖中寄王侍御', '湖中寄王侍御', '848118cd-09ab-4bb1-a9f0-c87d2f8e18e0', '唐', '["日日湖水上，好登湖上樓。","終年不向郭，過午始梳頭。","嘗自愛桮酒，得無相獻酬。","小僮能膾鯉，少妾事蓮舟。","每有南浦信，仍期後月遊。","方春轉搖蕩，孤興時淹留。","驄馬真傲吏，翛然無所求。","晨趨玉階下，心許滄江流。","少別如昨日，何言經數秋。","應知方外事，獨往非悠悠。"]', '["日日湖水上，好登湖上楼。","終年不向郭，過午始梳头。","嘗自愛桮酒，得無相獻酬。","小僮能膾鯉，少妾事蓮舟。","每有南浦信，仍期後月游。","方春轉搖蕩，孤兴时淹留。","驄马真傲吏，翛然無所求。","晨趨玉階下，心許滄江流。","少別如昨日，何言經數秋。","應知方外事，独往非悠悠。"]', '诗', 'shi', '', NULL, '湖中寄王侍御 丘爲 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('bcbfee0c-818c-4c2d-9f42-5473a2d25457', '登潤州城', '登潤州城', '848118cd-09ab-4bb1-a9f0-c87d2f8e18e0', '唐', '["天末江城晚，登臨客望迷。","春潮平島嶼，殘雨隔虹蜺。","鳥與孤帆遠，煙和獨樹低。","鄉山何處是？目斷廣陵西。"]', '["天末江城晚，登臨客望迷。","春潮平島嶼，殘雨隔虹蜺。","鸟與孤帆远，煙和独樹低。","乡山何处是？目斷廣陵西。"]', '诗', 'shi', '', NULL, '登潤州城 丘爲 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8d4ccd4d-33e5-467a-9590-053ae27a1289', '尋廬山崔徵君', '尋廬山崔徵君', '848118cd-09ab-4bb1-a9f0-c87d2f8e18e0', '唐', '["日高雞犬靜，門掩向寒塘。","夜竹深茅宇，秋亭冷石牀。","住山年已遠，服藥壽偏長。","虛棄浮生者，相逢益自傷。"]', '["日高雞犬静，门掩向寒塘。","夜竹深茅宇，秋亭冷石牀。","住山年已远，服藥壽偏长。","虛棄浮生者，相逢益自傷。"]', '诗', 'shi', '', NULL, '尋廬山崔徵君 丘爲 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1876768c-2bb3-4589-a6e4-ade42d5d28ce', '留別王維', '留別王維', '848118cd-09ab-4bb1-a9f0-c87d2f8e18e0', '唐', '["歸鞍白雲外，繚繞出前山。","今日又明日，自知心不閑。","親勞簪組送，欲趂鶯花還。","一步一回首，遲遲向近關。"]', '["归鞍白云外，繚繞出前山。","今日又明日，自知心不闲。","親勞簪組送，欲趂鶯花還。","一步一回首，遲遲向近关。"]', '诗', 'shi', '', NULL, '留別王維 丘爲 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('cc73e0d8-14e1-4dcb-9c58-b41c46396b59', '竹下殘雪', '竹下殘雪', '848118cd-09ab-4bb1-a9f0-c87d2f8e18e0', '唐', '["一點消未盡，孤月在竹陰。","晴光夜轉瑩，寒氣曉仍深。","還對讀書牖，且關乘興心。","已能依此地，終不傍瑤琴。"]', '["一点消未尽，孤月在竹陰。","晴光夜轉瑩，寒氣晓仍深。","還对读书牖，且关乘兴心。","已能依此地，終不傍瑤琴。"]', '诗', 'shi', '', NULL, '竹下殘雪 丘爲 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1391ad55-9a12-4b97-aad5-9cce3b49c785', '送閻校書之越', '送閻校书之越', '848118cd-09ab-4bb1-a9f0-c87d2f8e18e0', '唐', '["南入剡中路，草雲應轉微。","湖邊好花照，山口細泉飛。","此地饒古跡，世人多忘歸。","經年松雪在，永日世情稀。","芸閣應相望，芳時不可違。"]', '["南入剡中路，草云應轉微。","湖邊好花照，山口細泉飞。","此地饒古跡，世人多忘归。","經年松雪在，永日世情稀。","芸閣應相望，芳时不可違。"]', '诗', 'shi', '', NULL, '送閻校書之越 丘爲 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('eb0a4da3-927c-4575-8591-438f17253756', '省試夏日可畏', '省試夏日可畏', '848118cd-09ab-4bb1-a9f0-c87d2f8e18e0', '唐', '["赫赫溫風扇，炎炎夏日徂。","火威馳迥野，畏景爍遙途。","勢矯翔陽翰，功分造化爐。","禁城千品燭，黃道一輪孤。","落照頻空簟，餘暉卷夕梧。","如何倦遊子，中路獨踟躕。"]', '["赫赫溫风扇，炎炎夏日徂。","火威驰迥野，畏景爍遙途。","勢矯翔陽翰，功分造化爐。","禁城千品燭，黄道一輪孤。","落照頻空簟，餘暉卷夕梧。","如何倦游子，中路独踟躕。"]', '诗', 'shi', '', NULL, '省試夏日可畏 丘爲 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6bb164b4-b9d3-4d23-b54b-e71e3535ddc7', '左掖梨花', '左掖梨花', '848118cd-09ab-4bb1-a9f0-c87d2f8e18e0', '唐', '["冷豔全欺雪，餘香乍入衣。","春風且莫定，吹向玉階飛。"]', '["冷豔全欺雪，餘香乍入衣。","春风且莫定，吹向玉階飞。"]', '诗', 'shi', '', NULL, '左掖梨花 丘爲 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('288561f3-ad9b-4a2d-a311-8db418792aae', '渡漢江', '渡漢江', '848118cd-09ab-4bb1-a9f0-c87d2f8e18e0', '唐', '["漾舟漢江上，挂席候風生。","臨汎何容與，愛此江水清。","蘆洲隱遙嶂，露日隱孤城。","自顧疎野性，難忘鷗鳥情。","聊復與時顧，暫欲解塵纓。","跋涉非吾願，虛懷浩已盈。"]', '["漾舟漢江上，挂席候风生。","臨汎何容與，愛此江水清。","蘆洲隐遙嶂，露日隐孤城。","自顧疎野性，难忘鷗鸟情。","聊复與时顧，暫欲解塵纓。","跋涉非吾願，虛懷浩已盈。"]', '诗', 'shi', '', NULL, '渡漢江 丘爲 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('fff7158d-1a9d-4eb0-9851-66a5098ef74b', '冬至下寄舍弟時應赴入京', '冬至下寄舍弟时應赴入京', '848118cd-09ab-4bb1-a9f0-c87d2f8e18e0', '唐', '["去去知未遠，依依甚初別。","他鄉至下心，昨夜堦前雪。","終日讀書仍少孤，家貧兄弟未當途。","適遠纔過宿舂料，相隨惟一平頭奴。","男兒出門事四海，立身世業文章在。","莫漫憶柴扉，駟馬高車朝紫微。","江南驛使不曾斷，迎前爲爾非春衣。"]', '["去去知未远，依依甚初別。","他乡至下心，昨夜堦前雪。","終日读书仍少孤，家貧兄弟未當途。","適远纔過宿舂料，相隨惟一平头奴。","男兒出门事四海，立身世業文章在。","莫漫憶柴扉，駟马高车朝紫微。","江南驛使不曾斷，迎前爲爾非春衣。"]', '诗', 'shi', '', NULL, '冬至下寄舍弟時應赴入京 丘爲 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('269ffb18-fb0e-4dfc-88d8-afbf8456335c', '送晁補闕歸日本國', '送晁補闕归日本国', 'e2145c1a-bc24-4285-aa39-82e74424db5b', '唐', '["西掖承休澣，東隅返故林。","來稱郯子學，歸是越人吟。","馬上秋郊遠，舟中曙海陰。","知君懷魏闕，萬里獨搖心。"]', '["西掖承休澣，东隅返故林。","来稱郯子学，归是越人吟。","马上秋郊远，舟中曙海陰。","知君懷魏闕，万里独搖心。"]', '诗', 'shi', '', NULL, '送晁補闕歸日本國 趙驊 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('fa7fda27-632a-4003-a2ca-8ae208ebe088', '古遊俠呈軍中諸將', '古游俠呈軍中諸將', 'c91ae931-2891-49b6-9175-74c9bc65e201', '唐', '["少年負膽氣，好勇復知機。","仗劍出門去，孤城逢合圍。","殺人遼水上，走馬漁陽歸。","錯落金鎖甲，蒙茸貂鼠衣。","還家行且獵，弓矢速如飛。","地迥鷹犬疾，草深狐兔肥。","腰間帶兩綬，轉盼生光輝。","顧謂今日戰，何如隨建威。"]', '["少年負膽氣，好勇复知機。","仗劍出门去，孤城逢合圍。","殺人遼水上，走马漁陽归。","錯落金鎖甲，蒙茸貂鼠衣。","還家行且獵，弓矢速如飞。","地迥鷹犬疾，草深狐兔肥。","腰间带兩綬，轉盼生光輝。","顧謂今日戰，何如隨建威。"]', '诗', 'shi', '', NULL, '古遊俠呈軍中諸將 崔顥 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('caf365b6-0a8a-4942-855a-604245683caa', '贈輕車', '贈轻车', 'c91ae931-2891-49b6-9175-74c9bc65e201', '唐', '["悠悠遠行歸，經春涉長道。","幽冀桑始青，洛陽蠶欲老。","憶昨戎馬地，別時心草草。","烽火從北來，邊城閉常早。","平生少相遇，未得展懷抱。","今日杯酒間，見君交情好。"]', '["悠悠远行归，經春涉长道。","幽冀桑始青，洛陽蠶欲老。","憶昨戎马地，別时心草草。","烽火從北来，邊城閉常早。","平生少相遇，未得展懷抱。","今日杯酒间，见君交情好。"]', '诗', 'shi', '', NULL, '贈輕車 崔顥 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b4f8fa89-5d72-40d7-94a7-d437e0a5169f', '贈王威古', '贈王威古', 'c91ae931-2891-49b6-9175-74c9bc65e201', '唐', '["三十羽林將，出身常事邊。","春風吹淺草，獵騎何翩翩。","插羽兩相顧，鳴弓新上弦。","射麋入深谷，飲馬投荒泉。","馬上共傾酒，野中聊割鮮。","相看未及飲，雜虜寇幽燕。","烽火去不息，胡塵高際天。","長驅救東北，戰解城亦全。","報國行赴難，古來皆共然。"]', '["三十羽林將，出身常事邊。","春风吹淺草，獵騎何翩翩。","插羽兩相顧，鳴弓新上弦。","射麋入深谷，饮马投荒泉。","马上共傾酒，野中聊割鲜。","相看未及饮，杂虜寇幽燕。","烽火去不息，胡塵高際天。","长驱救东北，戰解城亦全。","報国行赴难，古来皆共然。"]', '诗', 'shi', '', NULL, '贈王威古 崔顥 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4abcebca-f810-4eeb-bf45-d5727af37353', '贈懷一上人', '贈懷一上人', 'c91ae931-2891-49b6-9175-74c9bc65e201', '唐', '["法師東南秀，世實豪家子。","削髮十二年，誦經峨眉裏。","自此照羣蒙，卓然爲道雄。","觀生盡入妄，悟有皆成空。","淨體無衆染，苦心歸妙宗。","一朝敕書至，召入承明宮。","說法金殿裏，焚香清禁中。","傳燈遍都邑，杖錫遊王公。","天子揖妙道，羣僚趨下風。","我法本無著，時來出林壑。","因心得化城，隨病皆與藥。","上啓黃屋心，下除蒼生縛。","一從入君門，說法無朝昏。","帝作轉輪王，師爲持戒尊。","軒風灑甘露，佛雨生慈根。","但有滅度理，而生開濟恩。","復聞江海曲，好殺成風俗。","帝曰我上人，爲除羶腥欲。","是日發西秦，東南至蘄春。","風將衡桂接，地與吳楚鄰。","舊少清信士，實多漁獵人。","一聞吾師至，捨網江湖濱。","作禮懺前惡，潔誠期後因。","因成日既久，事濟身不守。","更出淮楚間，復來荆河口。","荆河馬卿岑，茲地近道林。","入講鳥常狎，坐禪獸不侵。","都非緣未盡，曾是教所任。","故我一來事，永承微妙音。","竹房見衣鉢，松宇清身心。","早悔業至淺，晚成計可尋。","善哉遠公義，清淨如黃金。"]', '["法師东南秀，世實豪家子。","削髮十二年，誦經峨眉裏。","自此照羣蒙，卓然爲道雄。","观生尽入妄，悟有皆成空。","淨體無衆染，苦心归妙宗。","一朝敕书至，召入承明宮。","说法金殿裏，焚香清禁中。","傳灯遍都邑，杖錫游王公。","天子揖妙道，羣僚趨下风。","我法本無著，时来出林壑。","因心得化城，隨病皆與藥。","上啓黄屋心，下除蒼生縛。","一從入君门，说法無朝昏。","帝作轉輪王，師爲持戒尊。","軒风灑甘露，佛雨生慈根。","但有滅度理，而生开濟恩。","复闻江海曲，好殺成风俗。","帝曰我上人，爲除羶腥欲。","是日發西秦，东南至蘄春。","风將衡桂接，地與吳楚鄰。","旧少清信士，實多漁獵人。","一闻吾師至，捨網江湖濱。","作禮懺前惡，潔誠期後因。","因成日既久，事濟身不守。","更出淮楚间，复来荆河口。","荆河马卿岑，茲地近道林。","入講鸟常狎，坐禪獸不侵。","都非緣未尽，曾是教所任。","故我一来事，永承微妙音。","竹房见衣鉢，松宇清身心。","早悔業至淺，晚成計可尋。","善哉远公義，清淨如黄金。"]', '诗', 'shi', '', NULL, '贈懷一上人 崔顥 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2912b483-5f2b-43a7-babf-98a67cac7662', '遊天竺寺', '游天竺寺', 'c91ae931-2891-49b6-9175-74c9bc65e201', '唐', '["晨登天竺山，山殿朝陽曉。","厓泉爭噴薄，江岫相縈繞。","直上孤頂高，平看衆峰小。","南州十二月，地暖冰雪少。","青翠滿寒山，藤蘿覆冬沼。","花龕瀑布側，青壁石林杪。","鳴鐘集人天，施飯聚猨鳥。","洗意歸清淨，澄心悟空了。","始知世上人，萬物一何擾。"]', '["晨登天竺山，山殿朝陽晓。","厓泉爭噴薄，江岫相縈繞。","直上孤頂高，平看衆峰小。","南州十二月，地暖冰雪少。","青翠满寒山，藤蘿覆冬沼。","花龕瀑布側，青壁石林杪。","鳴鐘集人天，施飯聚猨鸟。","洗意归清淨，澄心悟空了。","始知世上人，万物一何擾。"]', '诗', 'shi', '', NULL, '遊天竺寺 崔顥 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b48414ae-ff62-4084-8e48-0afdb1ec5f92', '入若耶溪', '入若耶溪', 'c91ae931-2891-49b6-9175-74c9bc65e201', '唐', '["輕舟去何疾，已到雲林境。","起坐魚鳥間，動搖山水影。","巖中響自答，溪裏言彌靜。","事事令人幽，停橈向餘景。"]', '["轻舟去何疾，已到云林境。","起坐鱼鸟间，动搖山水影。","巖中响自答，溪裏言彌静。","事事令人幽，停橈向餘景。"]', '诗', 'shi', '', NULL, '入若耶溪 崔顥 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('62a772c1-f4b3-4e81-a9c9-fd8289d9bbd0', '雜詩', '杂诗', 'c91ae931-2891-49b6-9175-74c9bc65e201', '唐', '["可憐青銅鏡，挂在白玉堂。","玉堂有美女，嬌弄明月光。","羅袖拂金鵲，綵屏點紅妝。","妝罷含情坐，春風桃李香。"]', '["可怜青銅镜，挂在白玉堂。","玉堂有美女，嬌弄明月光。","羅袖拂金鵲，綵屏点紅妝。","妝罷含情坐，春风桃李香。"]', '诗', 'shi', '', NULL, '雜詩 崔顥 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('086c86b3-f7dc-46a1-abc1-79b1a7cd5c8d', '結定襄郡獄效陶體', '結定襄郡獄效陶體', 'c91ae931-2891-49b6-9175-74c9bc65e201', '唐', '["我在河東時，使往定襄里。","定襄諸小兒，爭訟紛城市。","長老莫敢言，太守不能理。","謗書盈几案，文墨相填委。","牽引肆中翁，追呼田家子。","我來折此獄，五聽辨疑似。","小大必以情，未嘗施鞭箠。","是時三月暮，遍野農桑起。","里巷鳴春鳩，田園引流水。","此鄉多雜俗，戎夏殊音旨。","顧問邊塞人，勞情曷云已。"]', '["我在河东时，使往定襄里。","定襄諸小兒，爭訟紛城市。","长老莫敢言，太守不能理。","謗书盈几案，文墨相填委。","牽引肆中翁，追呼田家子。","我来折此獄，五听辨疑似。","小大必以情，未嘗施鞭箠。","是时三月暮，遍野農桑起。","里巷鳴春鳩，田园引流水。","此乡多杂俗，戎夏殊音旨。","顧问邊塞人，勞情曷云已。"]', '诗', 'shi', '', NULL, '結定襄郡獄效陶體 崔顥 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('626e8a4f-da45-45a2-9846-192bfd74b29d', '長安道', '长安道', 'c91ae931-2891-49b6-9175-74c9bc65e201', '唐', '["長安甲第高入雲，誰家居住霍將軍。","日晚朝迴擁賓從，路傍揖拜何紛紛。","莫言炙手手可熱，須臾火盡灰亦滅。","莫言貧賤即可欺，人生富貴自有時。","一朝天子賜眼色，世上悠悠應始知。"]', '["长安甲第高入云，誰家居住霍將軍。","日晚朝迴擁賓從，路傍揖拜何紛紛。","莫言炙手手可熱，須臾火尽灰亦滅。","莫言貧賤即可欺，人生富貴自有时。","一朝天子賜眼色，世上悠悠應始知。"]', '诗', 'shi', '', NULL, '長安道 崔顥 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('caae3e7c-229e-4620-be4f-3a541d27d10d', '行路難', '行路难', 'c91ae931-2891-49b6-9175-74c9bc65e201', '唐', '["君不見建章宮中金明枝，萬萬長條拂地垂。","二月三月花如霰，九重幽深君不見。","豔彩朝含四寶宮，香風旦入朝雲殿。","漢家宮女春未闌，愛此芳香朝暮看。","看來看去心不忘，攀折將安鏡臺上。","雙雙素手剪不成，兩兩紅妝笑相向。","建章昨夜起春風，一花飛落長信宮。","長信麗人見花泣，憶此珍樹何嗟及。","我昔初在昭陽時，朝攀暮折登玉墀。","只言歲歲長相對，不悟今朝遙相思。"]', '["君不见建章宮中金明枝，万万长條拂地垂。","二月三月花如霰，九重幽深君不见。","豔彩朝含四寶宮，香风旦入朝云殿。","漢家宮女春未闌，愛此芳香朝暮看。","看来看去心不忘，攀折將安镜台上。","雙雙素手剪不成，兩兩紅妝笑相向。","建章昨夜起春风，一花飞落长信宮。","长信丽人见花泣，憶此珍樹何嗟及。","我昔初在昭陽时，朝攀暮折登玉墀。","只言歲歲长相对，不悟今朝遙相思。"]', '诗', 'shi', '', NULL, '行路難 崔顥 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('870e3d7e-233c-4ceb-99ba-f71702a0a809', '孟門行', '孟门行', 'c91ae931-2891-49b6-9175-74c9bc65e201', '唐', '["黃雀銜黃花，翩翩傍簷隙。","本擬報君恩，如何反彈射。","金罍美酒滿座春，平原愛才多衆賓。","滿堂盡是忠義士，何意得有讒諛人。","諛言反覆那可道，能令君心不自保。","北園新栽桃李枝，根株未固何轉移。","成陰結實君自取，若問傍人那得知。"]', '["黄雀銜黄花，翩翩傍簷隙。","本擬報君恩，如何反彈射。","金罍美酒满座春，平原愛才多衆賓。","满堂尽是忠義士，何意得有讒諛人。","諛言反覆那可道，能令君心不自保。","北园新栽桃李枝，根株未固何轉移。","成陰結實君自取，若问傍人那得知。"]', '诗', 'shi', '', NULL, '孟門行 崔顥 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('fed02b0e-1351-48cd-aa27-b14f6231b6de', '渭城少年行', '渭城少年行', 'c91ae931-2891-49b6-9175-74c9bc65e201', '唐', '["洛陽三月梨花飛，秦地行人春憶歸。","揚鞭走馬城南陌，朝逢驛使秦川客。","驛使前日發章臺，傳道長安春早來。","棠梨宮中燕初至，葡萄館裏花正開。","念此使人歸更早，三月便達長安道。","長安道上春可憐，搖風蕩日曲江邊。","萬戶樓臺臨渭水，五陵花柳滿秦川。","秦川寒食盛繁華，遊子春來不見家。","鬬雞下杜塵初合，走馬章臺日半斜。","章臺帝城稱貴里，青樓日晚歌鐘起。","貴里豪家白馬驕，五陵年少不相饒。","雙雙挾彈來金市，兩兩鳴鞭上渭橋。","渭城橋頭酒新熟，金鞍白馬誰家宿。","可憐錦瑟箏琵琶，玉壺清酒就倡家。","小婦春來不解羞，嬌歌一曲楊柳花。"]', '["洛陽三月梨花飞，秦地行人春憶归。","揚鞭走马城南陌，朝逢驛使秦川客。","驛使前日發章台，傳道长安春早来。","棠梨宮中燕初至，葡萄館裏花正开。","念此使人归更早，三月便達长安道。","长安道上春可怜，搖风蕩日曲江邊。","万戶楼台臨渭水，五陵花柳满秦川。","秦川寒食盛繁华，游子春来不见家。","鬬雞下杜塵初合，走马章台日半斜。","章台帝城稱貴里，青楼日晚歌鐘起。","貴里豪家白马驕，五陵年少不相饒。","雙雙挾彈来金市，兩兩鳴鞭上渭橋。","渭城橋头酒新熟，金鞍白马誰家宿。","可怜錦瑟箏琵琶，玉壺清酒就倡家。","小婦春来不解羞，嬌歌一曲楊柳花。"]', '诗', 'shi', '', NULL, '渭城少年行 崔顥 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('bc702506-923c-4555-a124-a12b9c4bfb04', '盧姬篇', '盧姬篇', 'c91ae931-2891-49b6-9175-74c9bc65e201', '唐', '["盧姬少小魏王家，綠鬢紅脣桃李花。","魏王綺樓十二重，水晶簾箔繡芙蓉。","白玉欄干金作柱，樓上朝朝學歌舞。","前堂後堂羅袖人，南窗北窗花發春。","翠幌珠簾鬬絲管，一彈一奏雲欲斷。","君王日晚下朝歸，鳴環佩玉生光輝。","人生今日得嬌貴，誰道盧姬身細微。"]', '["盧姬少小魏王家，綠鬢紅脣桃李花。","魏王綺楼十二重，水晶簾箔繡芙蓉。","白玉欄干金作柱，楼上朝朝学歌舞。","前堂後堂羅袖人，南窗北窗花發春。","翠幌珠簾鬬絲管，一彈一奏云欲斷。","君王日晚下朝归，鳴环佩玉生光輝。","人生今日得嬌貴，誰道盧姬身細微。"]', '诗', 'shi', '', NULL, '盧姬篇 崔顥 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9b0d1abc-7a10-4a1d-bf12-b8bf9be0f9a0', '江畔老人愁', '江畔老人愁', 'c91ae931-2891-49b6-9175-74c9bc65e201', '唐', '["江南年少十八九，乘舟欲渡青溪口。","青溪口邊一老翁，鬢眉皓白已衰朽。","自言家代仕梁陳，垂朱拖紫三十人。","兩朝出將復入相，五世疊鼓乘朱輪。","父兄三葉皆尚主，子女四代爲妃嬪。","南山賜田接御苑，北宮甲第連紫宸。","直言榮華未休歇，不覺山崩海將竭。","兵戈亂入建康城，煙火連燒未央闕。","衣冠士子陷鋒刃，良將名臣盡埋沒。","山川改易失市朝，衢路縱橫填白骨。","老人此時尚少年，脫身走得投海邊。","罷兵歲餘未敢出，去鄉三載方來旋。","蓬蒿忘却五城宅，草木不識青谿田。","雖然得歸到鄉土，零丁貧賤長辛苦。","采樵屢入歷陽山，刈稻常過新林浦。","少年欲知老人歲，豈知今年一百五。","君今少壯我已衰，我昔少年君不睹。","人生貴賤各有時，莫見羸老相輕欺。","感君相問爲君說，說罷不覺令人悲。"]', '["江南年少十八九，乘舟欲渡青溪口。","青溪口邊一老翁，鬢眉皓白已衰朽。","自言家代仕梁陳，垂朱拖紫三十人。","兩朝出將复入相，五世叠鼓乘朱輪。","父兄三葉皆尚主，子女四代爲妃嬪。","南山賜田接御苑，北宮甲第連紫宸。","直言榮华未休歇，不覺山崩海將竭。","兵戈亂入建康城，煙火連燒未央闕。","衣冠士子陷鋒刃，良將名臣尽埋沒。","山川改易失市朝，衢路縱橫填白骨。","老人此时尚少年，脫身走得投海邊。","罷兵歲餘未敢出，去乡三載方来旋。","蓬蒿忘却五城宅，草木不識青谿田。","雖然得归到乡土，零丁貧賤长辛苦。","采樵屢入歷陽山，刈稻常過新林浦。","少年欲知老人歲，豈知今年一百五。","君今少壯我已衰，我昔少年君不睹。","人生貴賤各有时，莫见羸老相轻欺。","感君相问爲君说，说罷不覺令人悲。"]', '诗', 'shi', '', NULL, '江畔老人愁 崔顥 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d4aa078e-4ffc-4198-9110-6019fa6fe7ee', '邯鄲宮人怨', '邯鄲宮人怨', 'c91ae931-2891-49b6-9175-74c9bc65e201', '唐', '["邯鄲陌上三月春，暮行逢見一婦人。","自言鄉里本燕趙，少小隨家西入秦。","母兄憐愛無儔侶，五歲名爲阿嬌女。","七歲丰茸好顏色，八歲黠惠能言語。","十三兄弟教詩書，十五青樓學歌舞。","我家青樓臨道傍，紗窗綺幔暗聞香。","日暮笙歌君駐馬，春日妝梳妾斷腸。","不用城南使君壻，本求三十侍中郎。","何知漢帝好容色，玉輦攜登歸建章。","建章宮殿不知數，萬戶千門深且長。","百堵塗椒接青瑣，九華閣道連洞房。","水晶簾箔雲母扇，琉璃窗牖玳瑁牀。","歲歲年年奉歡宴，嬌貴榮華誰不羨。","恩情莫比陳皇后，寵愛全勝趙飛燕。","瑤房侍寢世莫知，金屋更衣人不見。","誰言一朝復一日，君王棄世市朝變。","宮車出葬茂陵田，賤妾獨留長信殿。","一朝太子升至尊，宮中人事如掌翻。","同時侍女見讒毀，後來新人莫敢言。","兄弟印綬皆被奪，昔年賞賜不復存。","一旦放歸舊鄉里，乘車垂淚還入門。","父母愍我曾富貴，嫁與西舍金王孫。","念此翻覆復何道，百年盛衰誰能保。","憶昨尚如春日花，悲今已作秋時草。","少年去去莫停鞭，人生萬事由上天。","非我今日獨如此，古今歇薄皆共然。"]', '["邯鄲陌上三月春，暮行逢见一婦人。","自言乡里本燕趙，少小隨家西入秦。","母兄怜愛無儔侶，五歲名爲阿嬌女。","七歲丰茸好顏色，八歲黠惠能言語。","十三兄弟教诗书，十五青楼学歌舞。","我家青楼臨道傍，紗窗綺幔暗闻香。","日暮笙歌君駐马，春日妝梳妾斷腸。","不用城南使君壻，本求三十侍中郎。","何知漢帝好容色，玉輦携登归建章。","建章宮殿不知數，万戶千门深且长。","百堵塗椒接青瑣，九华閣道連洞房。","水晶簾箔云母扇，琉璃窗牖玳瑁牀。","歲歲年年奉歡宴，嬌貴榮华誰不羨。","恩情莫比陳皇后，寵愛全勝趙飞燕。","瑤房侍寢世莫知，金屋更衣人不见。","誰言一朝复一日，君王棄世市朝变。","宮车出葬茂陵田，賤妾独留长信殿。","一朝太子升至尊，宮中人事如掌翻。","同时侍女见讒毀，後来新人莫敢言。","兄弟印綬皆被奪，昔年賞賜不复存。","一旦放归旧乡里，乘车垂泪還入门。","父母愍我曾富貴，嫁與西舍金王孫。","念此翻覆复何道，百年盛衰誰能保。","憶昨尚如春日花，悲今已作秋时草。","少年去去莫停鞭，人生万事由上天。","非我今日独如此，古今歇薄皆共然。"]', '诗', 'shi', '', NULL, '邯鄲宮人怨 崔顥 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5d60c870-b3f3-4a18-8d5e-584533f24e9e', '川上女', '川上女', 'c91ae931-2891-49b6-9175-74c9bc65e201', '唐', '["川上女，晚妝鮮。","日落青渚試輕檝，汀長花滿正迴船。","暮來浪起風轉緊，自言此去橫塘近。","綠江無伴夜獨行，獨行心緒愁無盡。"]', '["川上女，晚妝鲜。","日落青渚試轻檝，汀长花满正迴船。","暮来浪起风轉緊，自言此去橫塘近。","綠江無伴夜独行，独行心緒愁無尽。"]', '诗', 'shi', '', NULL, '川上女 崔顥 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2d5567c6-a8c1-4531-a2ef-f0e9531061bb', '鴈門胡人歌', '鴈门胡人歌', 'c91ae931-2891-49b6-9175-74c9bc65e201', '唐', '["高山代郡東接燕，鴈門胡人家近邊。","解放胡鷹逐塞鳥，能將代馬獵秋田。","山頭野火寒多燒，雨裏孤峰濕作煙。","聞道遼西無鬬戰，時時醉向酒家眠。"]', '["高山代郡东接燕，鴈门胡人家近邊。","解放胡鷹逐塞鸟，能將代马獵秋田。","山头野火寒多燒，雨裏孤峰濕作煙。","闻道遼西無鬬戰，时时醉向酒家眠。"]', '诗', 'shi', '', NULL, '鴈門胡人歌 崔顥 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d0f5cd79-3d6f-4958-abc5-ab19729fccab', '代閨人答輕薄少年', '代閨人答轻薄少年', 'c91ae931-2891-49b6-9175-74c9bc65e201', '唐', '["妾家近隔鳳凰池，粉壁紗窗楊柳垂。","本期漢代金吾壻，誤嫁長安遊俠兒。","兒家夫壻多輕薄，借客探丸重然諾。","平明挾彈入新豐，日晚揮鞭出長樂。","青絲白馬冶遊園，能使行人駐馬看。","自矜陌上繁華盛，不念閨中花鳥闌。","花間陌上春將晚，走馬鬬雞猶未返。","三時出望無消息，一去那知行近遠。","桃李花開覆井欄，朱樓落日捲簾看。","愁來欲奏相思曲，抱得秦箏不忍彈。"]', '["妾家近隔鳳凰池，粉壁紗窗楊柳垂。","本期漢代金吾壻，誤嫁长安游俠兒。","兒家夫壻多轻薄，借客探丸重然諾。","平明挾彈入新豐，日晚揮鞭出长乐。","青絲白马冶游园，能使行人駐马看。","自矜陌上繁华盛，不念閨中花鸟闌。","花间陌上春將晚，走马鬬雞猶未返。","三时出望無消息，一去那知行近远。","桃李花开覆井欄，朱楼落日捲簾看。","愁来欲奏相思曲，抱得秦箏不忍彈。"]', '诗', 'shi', '', NULL, '代閨人答輕薄少年 崔顥 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2702a1f6-bbac-4c86-90c1-1436804046b8', '七夕', '七夕', 'c91ae931-2891-49b6-9175-74c9bc65e201', '唐', '["長安城中月如練，家家此夜持針線。","仙裙玉佩空自知，天上人間不相見。","長信深陰夜轉幽，瑤堦金閣數螢流。","班姬此夕愁無限，河漢三更看斗牛。"]', '["长安城中月如練，家家此夜持針線。","仙裙玉佩空自知，天上人间不相见。","长信深陰夜轉幽，瑤堦金閣數螢流。","班姬此夕愁無限，河漢三更看斗牛。"]', '诗', 'shi', '', NULL, '七夕 崔顥 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d3e4b2ee-f3fe-466f-a391-964efd13eb0b', '長門怨', '长门怨', 'c91ae931-2891-49b6-9175-74c9bc65e201', '唐', '["君王寵初歇，棄妾長門宮。","紫殿青苔滿，高樓明月空。","夜愁生枕席，春意罷簾櫳。","泣盡無人問，容華落鏡中。"]', '["君王寵初歇，棄妾长门宮。","紫殿青苔满，高楼明月空。","夜愁生枕席，春意罷簾櫳。","泣尽無人问，容华落镜中。"]', '诗', 'shi', '', NULL, '長門怨 崔顥 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e084dced-a458-4721-aca9-f7c668a0e5a7', '王家少婦', '王家少婦', 'c91ae931-2891-49b6-9175-74c9bc65e201', '唐', '["十五嫁王昌，盈盈入畫堂。","自矜年最少，復倚壻爲郎。","舞愛前谿綠，歌憐子夜長。","閑來鬬百草，度日不成妝。"]', '["十五嫁王昌，盈盈入畫堂。","自矜年最少，复倚壻爲郎。","舞愛前谿綠，歌怜子夜长。","闲来鬬百草，度日不成妝。"]', '诗', 'shi', '', NULL, '王家少婦 崔顥 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7939cb25-46f7-4c07-80f4-e38cea026602', '岐王席觀妓', '岐王席观妓', 'c91ae931-2891-49b6-9175-74c9bc65e201', '唐', '["二月春來半，宮中日漸長。","柳垂金屋煖，花發玉樓香。","拂匣先臨鏡，調笙更炙簧。","還將歌舞態，只擬奉君王。"]', '["二月春来半，宮中日漸长。","柳垂金屋煖，花發玉楼香。","拂匣先臨镜，調笙更炙簧。","還將歌舞態，只擬奉君王。"]', '诗', 'shi', '', NULL, '岐王席觀妓 崔顥 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e3b557f1-e7f7-4522-9eac-b3045ef4de2a', '上巳', '上巳', 'c91ae931-2891-49b6-9175-74c9bc65e201', '唐', '["巳日帝城春，傾都祓禊晨。","停車須傍水，奏樂要驚塵。","弱柳障行騎，浮橋擁看人。","猶言日尚早，更向九龍津。"]', '["巳日帝城春，傾都祓禊晨。","停车須傍水，奏乐要驚塵。","弱柳障行騎，浮橋擁看人。","猶言日尚早，更向九龙津。"]', '诗', 'shi', '', NULL, '上巳 崔顥 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('117aeb95-316c-4841-95fa-99fe405f5bb8', '贈梁州張都督', '贈梁州張都督', 'c91ae931-2891-49b6-9175-74c9bc65e201', '唐', '["聞君爲漢將，虜騎罷南侵。","出塞清沙漠，還家拜羽林。","風霜臣節苦，歲月主恩深。","爲語西河使，知余報國心。"]', '["闻君爲漢將，虜騎罷南侵。","出塞清沙漠，還家拜羽林。","风霜臣節苦，歲月主恩深。","爲語西河使，知余報国心。"]', '诗', 'shi', '', NULL, '贈梁州張都督 崔顥 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('04a613bf-b268-4b75-9b4d-77bf3490f1c9', '贈盧八象', '贈盧八象', 'c91ae931-2891-49b6-9175-74c9bc65e201', '唐', '["客從巴水渡，傳爾泝行舟。","是日風波霽，高堂雨半收。","青山滿蜀道，綠水向荆州。","不作書相問，誰能慰別愁。"]', '["客從巴水渡，傳爾泝行舟。","是日风波霽，高堂雨半收。","青山满蜀道，綠水向荆州。","不作书相问，誰能慰別愁。"]', '诗', 'shi', '', NULL, '贈盧八象 崔顥 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6b8258d9-5cc5-4bde-9768-94b3e9e9ef39', '題潼關樓', '題潼关楼', 'c91ae931-2891-49b6-9175-74c9bc65e201', '唐', '["客行逢雨霽，歇馬上津樓。","山勢雄三輔，關門扼九州。","川從陝路去，河遶華陰流。","向晚登臨處，風煙萬里愁。"]', '["客行逢雨霽，歇马上津楼。","山勢雄三輔，关门扼九州。","川從陝路去，河遶华陰流。","向晚登臨处，风煙万里愁。"]', '诗', 'shi', '', NULL, '題潼關樓 崔顥 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b6646529-868b-4b18-85b2-0e39c7171005', '題沈隱侯八詠樓', '題沈隐侯八詠楼', 'c91ae931-2891-49b6-9175-74c9bc65e201', '唐', '["梁日東陽守，爲樓望越中。","綠窗明月在，青史古人空。","江靜聞山狖，川長數塞鴻。","登臨白雲晚，流恨此遺風。"]', '["梁日东陽守，爲楼望越中。","綠窗明月在，青史古人空。","江静闻山狖，川长數塞鴻。","登臨白云晚，流恨此遺风。"]', '诗', 'shi', '', NULL, '題沈隱侯八詠樓 崔顥 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7f7c00be-7da2-42b5-8465-806de1d0414b', '晚入汴水', '晚入汴水', 'c91ae931-2891-49b6-9175-74c9bc65e201', '唐', '["昨晚南行楚，今朝北泝河。","客愁能幾日，鄉路漸無多。","晴景搖津樹，春風起棹歌。","長淮亦已盡，寧復畏潮波。"]', '["昨晚南行楚，今朝北泝河。","客愁能幾日，乡路漸無多。","晴景搖津樹，春风起棹歌。","长淮亦已尽，寧复畏潮波。"]', '诗', 'shi', '', NULL, '晚入汴水 崔顥 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d374479f-b077-4bcb-baea-30b804709138', '發錦沙村', '發錦沙村', 'c91ae931-2891-49b6-9175-74c9bc65e201', '唐', '["北上途未半，南行歲已闌。","孤舟下建德，江水入新安。","海近山常雨，谿深地早寒。","行行泊不可，須及子陵灘。"]', '["北上途未半，南行歲已闌。","孤舟下建德，江水入新安。","海近山常雨，谿深地早寒。","行行泊不可，須及子陵灘。"]', '诗', 'shi', '', NULL, '發錦沙村 崔顥 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('89873bcc-ae02-40f3-a288-583573acfc96', '送單于裴都護赴西河', '送單于裴都護赴西河', 'c91ae931-2891-49b6-9175-74c9bc65e201', '唐', '["征馬去翩翩，城秋月正圓。","單于莫近塞，都護欲臨邊。","漢驛通煙火，胡沙乏井泉。","功成須獻捷，未必去經年。"]', '["征马去翩翩，城秋月正圓。","單于莫近塞，都護欲臨邊。","漢驛通煙火，胡沙乏井泉。","功成須獻捷，未必去經年。"]', '诗', 'shi', '', NULL, '送單于裴都護赴西河 崔顥 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2188f98e-d5f0-4740-b94b-e1497a3619ee', '黃鶴樓', '黄鹤楼', 'c91ae931-2891-49b6-9175-74c9bc65e201', '唐', '["昔人已乘白雲去，此地空餘黃鶴樓。","黃鶴一去不復返，白雲千載空悠悠。","晴川歷歷漢陽樹，春草萋萋鸚鵡洲。","日暮鄉關何處是，煙波江上使人愁。"]', '["昔人已乘白云去，此地空餘黄鹤楼。","黄鹤一去不复返，白云千載空悠悠。","晴川歷歷漢陽樹，春草萋萋鸚鵡洲。","日暮乡关何处是，煙波江上使人愁。"]', '诗', 'shi', '', NULL, '黃鶴樓 崔顥 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('39b2954c-04df-4561-ad6e-f4ddbae0db1e', '行經華陰', '行經华陰', 'c91ae931-2891-49b6-9175-74c9bc65e201', '唐', '["岧嶤太華俯咸京，天外三峰削不成。","武帝祠前雲欲散，仙人掌上雨初晴。","河山北枕秦關險，驛樹西連漢畤平。","借問路傍名利客，無如此處學長生。"]', '["岧嶤太华俯咸京，天外三峰削不成。","武帝祠前云欲散，仙人掌上雨初晴。","河山北枕秦关險，驛樹西連漢畤平。","借问路傍名利客，無如此处学长生。"]', '诗', 'shi', '', NULL, '行經華陰 崔顥 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6ab6d4a2-cebc-4d9b-994c-f3e95fb6e98a', '相逢行', '相逢行', 'c91ae931-2891-49b6-9175-74c9bc65e201', '唐', '["妾年初二八，家住洛橋頭。","玉戶臨馳道，朱門近御溝。","使君何假問，夫壻大長秋。","女弟新承寵，諸兄近拜侯。","春生百子殿，花發五城樓。","出入千門裏，年年樂未休。"]', '["妾年初二八，家住洛橋头。","玉戶臨驰道，朱门近御溝。","使君何假问，夫壻大长秋。","女弟新承寵，諸兄近拜侯。","春生百子殿，花發五城楼。","出入千门裏，年年乐未休。"]', '诗', 'shi', '', NULL, '相逢行 崔顥 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('228cc6fa-c659-4ee8-a9c9-9242ae570970', '遼西作', '遼西作', 'c91ae931-2891-49b6-9175-74c9bc65e201', '唐', '["燕郊芳歲晚，殘雪凍邊城。","四月青草合，遼陽春水生。","胡人正牧馬，漢將日徵兵。","露重寶刀濕，沙虛金鼓鳴。","寒衣著已盡，春服與誰成。","寄語洛陽使，爲傳邊塞情。"]', '["燕郊芳歲晚，殘雪凍邊城。","四月青草合，遼陽春水生。","胡人正牧马，漢將日徵兵。","露重寶刀濕，沙虛金鼓鳴。","寒衣著已尽，春服與誰成。","寄語洛陽使，爲傳邊塞情。"]', '诗', 'shi', '', NULL, '遼西作 崔顥 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c115c820-4001-45ac-8612-c7b58d4a86f9', '奉和許給事夜直簡諸公', '奉和許給事夜直簡諸公', 'c91ae931-2891-49b6-9175-74c9bc65e201', '唐', '["西掖黃樞近，東曹紫禁連。","地因才子拜，人用省郎遷。","夜直千門靜，河明萬象懸。","建章宵漏急，閶闔曉鐘傳。","寵列貂蟬位，恩深侍從年。","九重初起草，五夜即成篇。","顧己無官次，循涯但自憐。","遠陪蘭署作，空此仰神仙。"]', '["西掖黄樞近，东曹紫禁連。","地因才子拜，人用省郎遷。","夜直千门静，河明万象懸。","建章宵漏急，閶闔晓鐘傳。","寵列貂蟬位，恩深侍從年。","九重初起草，五夜即成篇。","顧己無官次，循涯但自怜。","远陪蘭署作，空此仰神仙。"]', '诗', 'shi', '', NULL, '奉和許給事夜直簡諸公 崔顥 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ed672ad2-1a5b-4bc5-b0e1-5ed1ea49dc1e', '舟行入剡', '舟行入剡', 'c91ae931-2891-49b6-9175-74c9bc65e201', '唐', '["鳴棹下東陽，回舟入剡鄉。","青山行不盡，綠水去何長。","地氣秋仍濕，江風晚漸涼。","山梅猶作雨，谿橘未知霜。","謝客文逾盛，林公未可忘。","多慚越中好，流恨閱時芳。"]', '["鳴棹下东陽，回舟入剡乡。","青山行不尽，綠水去何长。","地氣秋仍濕，江风晚漸涼。","山梅猶作雨，谿橘未知霜。","謝客文逾盛，林公未可忘。","多慚越中好，流恨閱时芳。"]', '诗', 'shi', '', NULL, '舟行入剡 崔顥 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('40c9280d-c221-4d4e-bc63-86c853be15bf', '澄水如鑑', '澄水如鑑', 'c91ae931-2891-49b6-9175-74c9bc65e201', '唐', '["聖賢將立喻，上善貯情深。","潔白依全德，澄清有片心。","澆浮知不撓，濫濁固難侵。","方寸懸高鑑，生涯詎陸沈。","對泉能自誡，如鏡靜相臨。","廉慎傳家政，流芳合古今。"]', '["聖賢將立喻，上善貯情深。","潔白依全德，澄清有片心。","澆浮知不撓，濫濁固难侵。","方寸懸高鑑，生涯詎陸沈。","对泉能自誡，如镜静相臨。","廉慎傳家政，流芳合古今。"]', '诗', 'shi', '', NULL, '澄水如鑑 崔顥 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c39225f9-16b2-4713-a11c-d7030ec3b1c9', '長干曲四首 一', '长干曲四首 一', 'c91ae931-2891-49b6-9175-74c9bc65e201', '唐', '["君家何處住？妾住在橫塘。","停船暫借問，或恐是同鄉。"]', '["君家何处住？妾住在橫塘。","停船暫借问，或恐是同乡。"]', '诗', 'shi', '', NULL, '長干曲四首 一 崔顥 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4a732464-35a5-4ffc-94d0-37d653eef2a1', '長干曲四首 二', '长干曲四首 二', 'c91ae931-2891-49b6-9175-74c9bc65e201', '唐', '["家臨九江水，來去九江側。","同是長干人，自小不相識。"]', '["家臨九江水，来去九江側。","同是长干人，自小不相識。"]', '诗', 'shi', '', NULL, '長干曲四首 二 崔顥 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('88c46a8d-d2b8-415d-9bae-1de77f2bfddd', '長干曲四首 三', '长干曲四首 三', 'c91ae931-2891-49b6-9175-74c9bc65e201', '唐', '["下渚多風浪，蓮舟漸覺稀。","那能不相待，獨自逆潮歸。"]', '["下渚多风浪，蓮舟漸覺稀。","那能不相待，独自逆潮归。"]', '诗', 'shi', '', NULL, '長干曲四首 三 崔顥 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9f5f18e9-b433-48c2-9a89-fa1056b74e3a', '長干曲四首 四', '长干曲四首 四', 'c91ae931-2891-49b6-9175-74c9bc65e201', '唐', '["三江潮水急，五湖風浪湧。","由來花性輕，莫畏蓮舟重。"]', '["三江潮水急，五湖风浪湧。","由来花性轻，莫畏蓮舟重。"]', '诗', 'shi', '', NULL, '長干曲四首 四 崔顥 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8d0784dc-e386-4237-8022-d24d8ae96d05', '維揚送友還蘇州', '維揚送友還蘇州', 'c91ae931-2891-49b6-9175-74c9bc65e201', '唐', '["長安南下幾程途，得到邗溝弔綠蕪。","渚畔鱸魚舟上釣，羨君歸老向東吳。"]', '["长安南下幾程途，得到邗溝弔綠蕪。","渚畔鱸鱼舟上釣，羨君归老向东吳。"]', '诗', 'shi', '', NULL, '維揚送友還蘇州 崔顥 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('fcde35d4-d776-498b-aee7-8f7f178df255', '古意二首 一', '古意二首 一', 'ad0c2f94-fc30-4693-aa87-4aeabcf876de', '唐', '["夫差日淫放，舉國求妃嬪。","自謂得王寵，代間無美人。","碧羅象天閣，坐輦乘芳春。","宮女數千騎，常遊江水濱。","年深玉顏老，時薄花妝新。","拭淚下金殿，嬌多不顧身。","生前妬歌舞，死後同灰塵。","冢墓令人哀，哀於銅雀臺。"]', '["夫差日淫放，舉国求妃嬪。","自謂得王寵，代间無美人。","碧羅象天閣，坐輦乘芳春。","宮女數千騎，常游江水濱。","年深玉顏老，时薄花妝新。","拭泪下金殿，嬌多不顧身。","生前妬歌舞，死後同灰塵。","冢墓令人哀，哀於銅雀台。"]', '诗', 'shi', '', NULL, '古意二首 一 祖詠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8ea0f553-cc8f-46b8-9a68-d1a80a71939d', '古意二首 二', '古意二首 二', 'ad0c2f94-fc30-4693-aa87-4aeabcf876de', '唐', '["楚王竟何去，獨自留巫山。","偏使世人見，迢迢江漢間。","駐舟春谿裏，誓願拜靈顏。","夢寐覩神女，金沙鳴珮環。","閑豔絕世姿，令人氣力微。","含笑默不語，化作朝雲飛。"]', '["楚王竟何去，独自留巫山。","偏使世人见，迢迢江漢间。","駐舟春谿裏，誓願拜靈顏。","梦寐覩神女，金沙鳴珮环。","闲豔絕世姿，令人氣力微。","含笑默不語，化作朝云飞。"]', '诗', 'shi', '', NULL, '古意二首 二 祖詠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7d75943b-6a3a-4b5b-9aa7-bf78d26be182', '渡淮河寄平一', '渡淮河寄平一', 'ad0c2f94-fc30-4693-aa87-4aeabcf876de', '唐', '["天色混波濤，岸陰匝村墅。","微微漢祖廟，隱隱江陵渚。","雲樹森已重，時明鬱相拒。"]', '["天色混波濤，岸陰匝村墅。","微微漢祖廟，隐隐江陵渚。","云樹森已重，时明鬱相拒。"]', '诗', 'shi', '', NULL, '渡淮河寄平一 祖詠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7e6fcfbc-5fa7-49b3-b34d-82006fa958e5', '歸汝墳山莊留別盧象', '归汝墳山莊留別盧象', 'ad0c2f94-fc30-4693-aa87-4aeabcf876de', '唐', '["淹留歲將[晏]，久廢南山期。","舊業不見棄，還山從此辭。","漚麻入南澗，刈麥向東菑。","對酒雞黍熟，閉門風雪時。","非君一延首，誰慰遙相思。"]', '["淹留歲將[晏]，久廢南山期。","旧業不见棄，還山從此辞。","漚麻入南澗，刈麦向东菑。","对酒雞黍熟，閉门风雪时。","非君一延首，誰慰遙相思。"]', '诗', 'shi', '', NULL, '歸汝墳山莊留別盧象 祖詠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('af12f90e-1f84-4b72-aacb-0a85933f67d8', '夕次圃田店', '夕次圃田店', 'ad0c2f94-fc30-4693-aa87-4aeabcf876de', '唐', '["前路入鄭郊，尚經百餘里。","馬煩時欲歇，客歸程未已。","落日桑柘陰，遙村煙火起。","西還不遑宿，中夜渡涇水。"]', '["前路入鄭郊，尚經百餘里。","马煩时欲歇，客归程未已。","落日桑柘陰，遙村煙火起。","西還不遑宿，中夜渡涇水。"]', '诗', 'shi', '', NULL, '夕次圃田店 祖詠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('39893b55-0af2-4090-98b9-c7eea69663df', '田家即事', '田家即事', 'ad0c2f94-fc30-4693-aa87-4aeabcf876de', '唐', '["舊居東臯上，左右俯荒村。","樵路前傍嶺，田家遙對門。","歡娛始披拂，愜意在郊原。","餘霽蕩川霧，新秋仍晝昏。","攀條憩林麓，引水開泉源。","稼穡豈云倦，桑麻今正繁。","方求靜者賞，偶與潛夫論。","雞黍何必具，吾心知道尊。"]', '["旧居东臯上，左右俯荒村。","樵路前傍嶺，田家遙对门。","歡娛始披拂，愜意在郊原。","餘霽蕩川霧，新秋仍晝昏。","攀條憩林麓，引水开泉源。","稼穡豈云倦，桑麻今正繁。","方求静者賞，偶與潛夫論。","雞黍何必具，吾心知道尊。"]', '诗', 'shi', '', NULL, '田家即事 祖詠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('cfcc81e1-e1a5-4138-87c4-a58eac0c0076', '扈從御宿池', '扈從御宿池', 'ad0c2f94-fc30-4693-aa87-4aeabcf876de', '唐', '["君王既巡狩，輦道入秦京。","遠樹低槍壘，孤峯入幔城。","寒疎清禁漏，夜警羽林兵。","誰念迷方客，長懷魏闕情。"]', '["君王既巡狩，輦道入秦京。","远樹低槍壘，孤峯入幔城。","寒疎清禁漏，夜警羽林兵。","誰念迷方客，长懷魏闕情。"]', '诗', 'shi', '', NULL, '扈從御宿池 祖詠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a0606067-a985-4ce7-b1a4-7a2764e78ee8', '贈苗發員外', '贈苗發員外', 'ad0c2f94-fc30-4693-aa87-4aeabcf876de', '唐', '["宿雨朝來歇，空山天氣清。","盤雲雙鶴下，隔水一蟬鳴。","古道黃花落，平蕪赤燒生。","茂陵雖有病，猶得伴君行。"]', '["宿雨朝来歇，空山天氣清。","盤云雙鹤下，隔水一蟬鳴。","古道黄花落，平蕪赤燒生。","茂陵雖有病，猶得伴君行。"]', '诗', 'shi', '', NULL, '贈苗發員外 祖詠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('85f22040-1449-4dd7-bfe5-9674db1faa0a', '答王維留宿', '答王維留宿', 'ad0c2f94-fc30-4693-aa87-4aeabcf876de', '唐', '["四年不相見，相見復何爲。","握手言未畢，却令傷別離。","升堂還駐馬，酌醴便呼兒。","語嘿自相對，安用傍人知。"]', '["四年不相见，相见复何爲。","握手言未畢，却令傷別離。","升堂還駐马，酌醴便呼兒。","語嘿自相对，安用傍人知。"]', '诗', 'shi', '', NULL, '答王維留宿 祖詠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7b6ae1ac-edf2-4c8b-867f-cbcf098a45a5', '長樂驛留別盧象裴總', '长乐驛留別盧象裴總', 'ad0c2f94-fc30-4693-aa87-4aeabcf876de', '唐', '["朝來已握手，宿別更傷心。","灞水行人渡，商山驛路深。","故情君且足，謫宦我難任。","直道皆如此，誰能淚滿襟。"]', '["朝来已握手，宿別更傷心。","灞水行人渡，商山驛路深。","故情君且足，謫宦我难任。","直道皆如此，誰能泪满襟。"]', '诗', 'shi', '', NULL, '長樂驛留別盧象裴總 祖詠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('12ed2359-fa68-40fa-aeac-a00e3189892d', '送劉高郵棁使入都', '送劉高郵棁使入都', 'ad0c2f94-fc30-4693-aa87-4aeabcf876de', '唐', '["常聞積歸思，昨夜又兼秋。","鄉路京華遠，王程江水流。","吳歌喧兩岸，楚客醉孤舟。","漸覺潮初上，悽然多暮愁。"]', '["常闻積归思，昨夜又兼秋。","乡路京华远，王程江水流。","吳歌喧兩岸，楚客醉孤舟。","漸覺潮初上，悽然多暮愁。"]', '诗', 'shi', '', NULL, '送劉高郵棁使入都 祖詠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('de5e4d03-d660-4da2-bf4e-1db97a7ab281', '宴吳王宅', '宴吳王宅', 'ad0c2f94-fc30-4693-aa87-4aeabcf876de', '唐', '["吳王承國寵，列第禁城東。","連夜徵詞客，當春試舞童。","砌分池水岸，牕度竹林風。","更待西園月，金尊樂未終。"]', '["吳王承国寵，列第禁城东。","連夜徵词客，當春試舞童。","砌分池水岸，牕度竹林风。","更待西园月，金尊乐未終。"]', '诗', 'shi', '', NULL, '宴吳王宅 祖詠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('669c6ad1-70fa-48e9-9a54-35d35610c204', '觀華嶽', '观华嶽', 'ad0c2f94-fc30-4693-aa87-4aeabcf876de', '唐', '["西入秦關口，南瞻驛路連。","彩雲生闕下，松樹到祠邊。","作鎮當官道，雄都俯大川。","蓮峯徑上處，彷彿有神仙。"]', '["西入秦关口，南瞻驛路連。","彩云生闕下，松樹到祠邊。","作鎮當官道，雄都俯大川。","蓮峯徑上处，彷彿有神仙。"]', '诗', 'shi', '', NULL, '觀華嶽 祖詠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('875a466e-3eca-4713-9bbc-de9355c4ede3', '泗上馮使君南樓作', '泗上馮使君南楼作', 'ad0c2f94-fc30-4693-aa87-4aeabcf876de', '唐', '["井邑連淮泗，南樓向晚過。","望灘沙鷺起，尋岸浴童歌。","近海雲偏出，兼秋雨更多。","明晨擬回棹，鄉思恨風波。"]', '["井邑連淮泗，南楼向晚過。","望灘沙鷺起，尋岸浴童歌。","近海云偏出，兼秋雨更多。","明晨擬回棹，乡思恨风波。"]', '诗', 'shi', '', NULL, '泗上馮使君南樓作 祖詠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('094290fb-5df1-4277-a3e5-a9d321fdfc1e', '蘇氏別業', '蘇氏別業', 'ad0c2f94-fc30-4693-aa87-4aeabcf876de', '唐', '["別業居幽處，到來生隱心。","南山當戶牖，灃水映園林。","屋覆經冬雪，庭昏未夕陰。","寥寥人境外，閑坐聽春禽。"]', '["別業居幽处，到来生隐心。","南山當戶牖，灃水映园林。","屋覆經冬雪，庭昏未夕陰。","寥寥人境外，闲坐听春禽。"]', '诗', 'shi', '', NULL, '蘇氏別業 祖詠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('90652c8c-0dbc-4eae-8e27-edd71d621b92', '汝墳別業', '汝墳別業', 'ad0c2f94-fc30-4693-aa87-4aeabcf876de', '唐', '["失路農爲業，移家到汝墳。","獨愁常廢卷，多病久離羣。","鳥雀垂窻柳，虹霓出澗雲。","山中無外事，樵唱有時聞。"]', '["失路農爲業，移家到汝墳。","独愁常廢卷，多病久離羣。","鸟雀垂窻柳，虹霓出澗云。","山中無外事，樵唱有时闻。"]', '诗', 'shi', '', NULL, '汝墳別業 祖詠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d397f8cb-15aa-4f2f-b219-701143cc8a8d', '陸渾水亭', '陸渾水亭', 'ad0c2f94-fc30-4693-aa87-4aeabcf876de', '唐', '["晝眺伊川曲，巖間霽色明。","淺沙平有路，流水漫無聲。","浴鳥沿波聚，潛魚觸釣驚。","更憐春岸綠，幽意滿前楹。"]', '["晝眺伊川曲，巖间霽色明。","淺沙平有路，流水漫無声。","浴鸟沿波聚，潛鱼觸釣驚。","更怜春岸綠，幽意满前楹。"]', '诗', 'shi', '', NULL, '陸渾水亭 祖詠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f5c208b5-2519-4f27-bbc7-b40989770878', '過鄭曲', '過鄭曲', 'ad0c2f94-fc30-4693-aa87-4aeabcf876de', '唐', '["路向榮川谷，晴來望盡通。","細煙生水上，圓月在舟中。","岸勢迷行客，秋聲亂草蟲。","旅懷勞自慰，淅淅有涼風。"]', '["路向榮川谷，晴来望尽通。","細煙生水上，圓月在舟中。","岸勢迷行客，秋声亂草蟲。","旅懷勞自慰，淅淅有涼风。"]', '诗', 'shi', '', NULL, '過鄭曲 祖詠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('20e22daf-a545-4517-98ae-ded485dde817', '宿陳留李少府揆廳', '宿陳留李少府揆廳', 'ad0c2f94-fc30-4693-aa87-4aeabcf876de', '唐', '["相知有叔卿，訟簡夜彌清。","旅泊倦愁臥，堂空聞曙更。","風簾搖燭影，秋雨帶蟲聲。","歸思那堪說，悠悠限洛城。"]', '["相知有叔卿，訟簡夜彌清。","旅泊倦愁臥，堂空闻曙更。","风簾搖燭影，秋雨带蟲声。","归思那堪说，悠悠限洛城。"]', '诗', 'shi', '', NULL, '宿陳留李少府揆廳 祖詠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0656e444-ea22-4f09-a0aa-397e204ea5a9', '題韓少府水亭', '題韓少府水亭', 'ad0c2f94-fc30-4693-aa87-4aeabcf876de', '唐', '["梅福幽棲處，佳期不忘還。","鳥吟當戶竹，花繞傍池山。","水氣侵階冷，松陰覆座閑。","寧知武陵趣，宛在市朝間。"]', '["梅福幽棲处，佳期不忘還。","鸟吟當戶竹，花繞傍池山。","水氣侵階冷，松陰覆座闲。","寧知武陵趣，宛在市朝间。"]', '诗', 'shi', '', NULL, '題韓少府水亭 祖詠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('019312e6-a9e8-4ba7-a66e-2e11838403f3', '題遠公經臺', '題远公經台', 'ad0c2f94-fc30-4693-aa87-4aeabcf876de', '唐', '["蘭若無人到，真僧出復稀。","苔侵行道席，雲濕坐禪衣。","澗鼠緣香案，山蟬噪竹扉。","世間長不見，寧止暫忘歸。"]', '["蘭若無人到，真僧出复稀。","苔侵行道席，云濕坐禪衣。","澗鼠緣香案，山蟬噪竹扉。","世间长不见，寧止暫忘归。"]', '诗', 'shi', '', NULL, '題遠公經臺 祖詠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5d79e014-ba3f-430a-b0c2-a5224d032904', '中峯居喜見苗發', '中峯居喜见苗發', 'ad0c2f94-fc30-4693-aa87-4aeabcf876de', '唐', '["自得中峰住，深林亦閉關。","經秋無客到，入夜有僧還。","暗澗泉聲小，荒岡樹影閑。","高窻不可望，星月滿空山。"]', '["自得中峰住，深林亦閉关。","經秋無客到，入夜有僧還。","暗澗泉声小，荒岡樹影闲。","高窻不可望，星月满空山。"]', '诗', 'shi', '', NULL, '中峯居喜見苗發 祖詠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('076912b3-7157-481a-a955-2bf4f35c928c', '江南旅情', '江南旅情', 'ad0c2f94-fc30-4693-aa87-4aeabcf876de', '唐', '["楚山不可極，歸路但蕭條。","海色晴看雨，江聲夜聽潮。","劒留南斗近，書寄北風遙。","爲報空潭橘，無媒寄洛橋。"]', '["楚山不可極，归路但蕭條。","海色晴看雨，江声夜听潮。","劒留南斗近，书寄北风遙。","爲報空潭橘，無媒寄洛橋。"]', '诗', 'shi', '', NULL, '江南旅情 祖詠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9b188774-5b9b-47e3-b91a-2df0e8b60a7c', '泊揚子津', '泊揚子津', 'ad0c2f94-fc30-4693-aa87-4aeabcf876de', '唐', '["纔入維揚郡，鄉關此路遙。","林藏初過雨，風退欲歸潮。","江火明沙岸，雲帆礙浦橋。","客衣今日薄，寒氣近來饒。"]', '["纔入維揚郡，乡关此路遙。","林藏初過雨，风退欲归潮。","江火明沙岸，云帆礙浦橋。","客衣今日薄，寒氣近来饒。"]', '诗', 'shi', '', NULL, '泊揚子津 祖詠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e5bf3b92-7b85-462f-ad14-2a46edc0e73e', '晚泊金陵水亭', '晚泊金陵水亭', 'ad0c2f94-fc30-4693-aa87-4aeabcf876de', '唐', '["江亭當廢國，秋景倍蕭騷。","夕照明殘壘，寒潮漲古濠。","就田看鶴大，隔水見僧高。","無限前朝事，醒吟易覺勞。"]', '["江亭當廢国，秋景倍蕭騷。","夕照明殘壘，寒潮漲古濠。","就田看鹤大，隔水见僧高。","無限前朝事，醒吟易覺勞。"]', '诗', 'shi', '', NULL, '晚泊金陵水亭 祖詠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a28adab8-eaed-46eb-862b-7768e8c7079e', '七夕', '七夕', 'ad0c2f94-fc30-4693-aa87-4aeabcf876de', '唐', '["閨女求天女，更闌意未闌。","玉庭開粉席，羅袖捧金盤。","向月穿針易，臨風整線難。","不知誰得巧，明旦試相看。"]', '["閨女求天女，更闌意未闌。","玉庭开粉席，羅袖捧金盤。","向月穿針易，臨风整線难。","不知誰得巧，明旦試相看。"]', '诗', 'shi', '', NULL, '七夕 祖詠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6beb5cc2-ae49-4e23-952a-1cb92fa11512', '望薊門', '望薊门', 'ad0c2f94-fc30-4693-aa87-4aeabcf876de', '唐', '["燕臺一望客心驚，簫鼓喧喧漢將營。","萬里寒光生積雪，三邊曙色動危旌。","沙場烽火連胡月，海畔雲山擁薊城。","少小雖非投筆吏，論功還欲請長纓。"]', '["燕台一望客心驚，簫鼓喧喧漢將營。","万里寒光生積雪，三邊曙色动危旌。","沙場烽火連胡月，海畔云山擁薊城。","少小雖非投笔吏，論功還欲請长纓。"]', '诗', 'shi', '', NULL, '望薊門 祖詠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b458b829-a8a7-4325-82f2-678e0c93fb7f', '家園夜坐寄郭微', '家园夜坐寄郭微', 'ad0c2f94-fc30-4693-aa87-4aeabcf876de', '唐', '["前堦微雨歇，開戶散窺林。","月出夜方淺，水涼池更深。","餘風生竹樹，清露薄衣襟。","遇物遂遙歎，懷人滋遠心。","依稀成夢想，影響絕徽音。","誰念窮居者，明時嗟陸沈。"]', '["前堦微雨歇，开戶散窺林。","月出夜方淺，水涼池更深。","餘风生竹樹，清露薄衣襟。","遇物遂遙歎，懷人滋远心。","依稀成梦想，影响絕徽音。","誰念窮居者，明时嗟陸沈。"]', '诗', 'shi', '', NULL, '家園夜坐寄郭微 祖詠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('53de2321-a23d-49b9-84d6-822713c3dee4', '酬汴州李別駕贈', '酬汴州李別駕贈', 'ad0c2f94-fc30-4693-aa87-4aeabcf876de', '唐', '["秋風多客思，行旅厭艱辛。","自洛非才子，遊梁得主人。","文章參末議，榮賤豈同倫。","歎逝逢三演，懷賢憶四真。","情因恩舊好，契託死生親。","所媿能投贈，清言益潤身。"]', '["秋风多客思，行旅厭艱辛。","自洛非才子，游梁得主人。","文章參末議，榮賤豈同倫。","歎逝逢三演，懷賢憶四真。","情因恩旧好，契託死生親。","所媿能投贈，清言益潤身。"]', '诗', 'shi', '', NULL, '酬汴州李別駕贈 祖詠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('82f66261-c88c-4823-b28e-0ef5b1b291cd', '清明宴司勳劉郎中別業', '清明宴司勳劉郎中別業', 'ad0c2f94-fc30-4693-aa87-4aeabcf876de', '唐', '["田家復近臣，行樂不違親。","霽日園林好，清明煙火新。","以文長會友，唯德自成鄰。","池照窻陰晚，杯香藥味春。","簷前花覆地，竹外鳥窺人。","何必桃源裏，深居作隱淪。"]', '["田家复近臣，行乐不違親。","霽日园林好，清明煙火新。","以文长會友，唯德自成鄰。","池照窻陰晚，杯香藥味春。","簷前花覆地，竹外鸟窺人。","何必桃源裏，深居作隐淪。"]', '诗', 'shi', '', NULL, '清明宴司勳劉郎中別業 祖詠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('57431a69-8bd2-493d-a83c-53e7449f6834', '汝墳秋同仙州王長史翰聞百舌鳥', '汝墳秋同仙州王长史翰闻百舌鸟', 'ad0c2f94-fc30-4693-aa87-4aeabcf876de', '唐', '["秋天聞好鳥，驚起出簾帷。","却念殊方月，能鳴已後時。","遷喬誠可早，出谷此何遲。","顧影慙無對，懷羣空所思。","淒涼歲欲晚，蕭索燕將辭。","留聽未終曲，彌令心獨悲。","高飛憑力致，巧囀任天姿。","返覆知而靜，間關斷若遺。","花繁上林路，霜落汝川湄。","且長凌風翮，乘春自有期。"]', '["秋天闻好鸟，驚起出簾帷。","却念殊方月，能鳴已後时。","遷喬誠可早，出谷此何遲。","顧影慙無对，懷羣空所思。","淒涼歲欲晚，蕭索燕將辞。","留听未終曲，彌令心独悲。","高飞憑力致，巧囀任天姿。","返覆知而静，间关斷若遺。","花繁上林路，霜落汝川湄。","且长凌风翮，乘春自有期。"]', '诗', 'shi', '', NULL, '汝墳秋同仙州王長史翰聞百舌鳥 祖詠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9f597a8a-e251-4c46-8079-8270f24cd34c', '送丘爲下第', '送丘爲下第', 'ad0c2f94-fc30-4693-aa87-4aeabcf876de', '唐', '["滄江一身客，獻賦空十年。","明主豈能好，今人誰舉賢。","國門稅征駕，旅食謀歸旋。","皦日媚春水，綠蘋香客船。","無媒既不達，予亦思歸田。"]', '["滄江一身客，獻賦空十年。","明主豈能好，今人誰舉賢。","国门稅征駕，旅食謀归旋。","皦日媚春水，綠蘋香客船。","無媒既不達，予亦思归田。"]', '诗', 'shi', '', NULL, '送丘爲下第 祖詠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('58f5c1c1-fe8d-4475-b394-c68013ebd2ff', '贈苗發員外', '贈苗發員外', 'ad0c2f94-fc30-4693-aa87-4aeabcf876de', '唐', '["朱戶敞高扉，青槐礙落暉。","八龍乘慶重，三虎遞朝歸。","坐竹人聲絕，橫琴鳥語稀。","花慙潘岳貌，年稱老萊衣。","葉暗朱櫻熟，絲長粉蝶飛。","應憐魯儒賤，空與故山違。"]', '["朱戶敞高扉，青槐礙落暉。","八龙乘慶重，三虎遞朝归。","坐竹人声絕，橫琴鸟語稀。","花慙潘岳貌，年稱老萊衣。","葉暗朱櫻熟，絲长粉蝶飞。","應怜魯儒賤，空與故山違。"]', '诗', 'shi', '', NULL, '贈苗發員外 祖詠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('491be4cd-418f-423a-94bf-cf97fba6fea7', '寄王長史', '寄王长史', 'ad0c2f94-fc30-4693-aa87-4aeabcf876de', '唐', '["汝潁俱宿好，往來託層巒。","終日何寂寞，繞籬生蕙蘭。"]', '["汝潁俱宿好，往来託層巒。","終日何寂寞，繞籬生蕙蘭。"]', '诗', 'shi', '', NULL, '寄王長史 祖詠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5eae5172-49fa-46f0-89a9-fa4261f928f1', '別怨', '別怨', 'ad0c2f94-fc30-4693-aa87-4aeabcf876de', '唐', '["送別到中流，秋船倚渡頭。","相看尚不遠，未可即回舟。"]', '["送別到中流，秋船倚渡头。","相看尚不远，未可即回舟。"]', '诗', 'shi', '', NULL, '別怨 祖詠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b4780bd1-1703-4bce-a801-d5ed566826b5', '終南望餘雪', '終南望餘雪', 'ad0c2f94-fc30-4693-aa87-4aeabcf876de', '唐', '["終南陰嶺秀，積雪浮雲端。","林表明霽色，城中增暮寒。"]', '["終南陰嶺秀，積雪浮云端。","林表明霽色，城中增暮寒。"]', '诗', 'shi', '', NULL, '終南望餘雪 祖詠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9fda363f-0256-488d-bf60-a1a7250aee6c', '句', '句', 'ad0c2f94-fc30-4693-aa87-4aeabcf876de', '唐', '["不知疊嶂夜來雨，清曉石楠花亂流。"]', '["不知叠嶂夜来雨，清晓石楠花亂流。"]', '诗', 'shi', '', NULL, '句 祖詠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c28945b1-db29-432b-85ce-ddc66101a12d', '湘夫人', '湘夫人', 'e7091833-f8c1-44a0-ae16-cf52c39c60f1', '唐', '["九嶷日已暮，三湘雲復愁。","窅靄羅袂色，潺湲江水流。","佳期來北渚，捐佩在芳洲。"]', '["九嶷日已暮，三湘云复愁。","窅靄羅袂色，潺湲江水流。","佳期来北渚，捐佩在芳洲。"]', '诗', 'shi', '', NULL, '湘夫人 李頎 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('bdf3a5d1-3079-43a7-93eb-b77bdff46f9d', '塞下曲', '塞下曲', 'e7091833-f8c1-44a0-ae16-cf52c39c60f1', '唐', '["黃雲雁門郡，日暮風沙裏。","千騎黑貂裘，皆稱羽林子。","金笳吹朔雪，鐵馬嘶雲水。","帳下飲蒲萄，平生寸心是。"]', '["黄云雁门郡，日暮风沙裏。","千騎黑貂裘，皆稱羽林子。","金笳吹朔雪，鐵马嘶云水。","帳下饮蒲萄，平生寸心是。"]', '诗', 'shi', '', NULL, '塞下曲 李頎 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('752d1ba0-6bc4-408e-b07a-757fcc653f7b', '古塞下曲', '古塞下曲', 'e7091833-f8c1-44a0-ae16-cf52c39c60f1', '唐', '["行人朝走馬，直指薊城傍。","薊城通漠北，萬里別吾鄉。","海上千烽火，沙中百戰場。","軍書發上郡，春色度河陽。","褭褭漢宮柳，青青胡地桑。","琵琶出塞曲，橫笛斷君腸。"]', '["行人朝走马，直指薊城傍。","薊城通漠北，万里別吾乡。","海上千烽火，沙中百戰場。","軍书發上郡，春色度河陽。","褭褭漢宮柳，青青胡地桑。","琵琶出塞曲，橫笛斷君腸。"]', '诗', 'shi', '', NULL, '古塞下曲 李頎 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5667797f-6e78-4ef2-b041-6af59b44a0c2', '漁父歌', '漁父歌', 'e7091833-f8c1-44a0-ae16-cf52c39c60f1', '唐', '["白首何老人，蓑笠蔽其身。","避世長不仕，釣魚清江濱。","浦沙明濯足，山月靜垂綸。","寓宿湍與瀨，行歌秋復春。","持竿湘岸竹，爇火蘆洲薪。","綠水飯香稻，青荷包紫鱗。","於中還自樂，所欲全吾真。","而笑獨醒者，臨流多苦辛。"]', '["白首何老人，蓑笠蔽其身。","避世长不仕，釣鱼清江濱。","浦沙明濯足，山月静垂綸。","寓宿湍與瀨，行歌秋复春。","持竿湘岸竹，爇火蘆洲薪。","綠水飯香稻，青荷包紫鱗。","於中還自乐，所欲全吾真。","而笑独醒者，臨流多苦辛。"]', '诗', 'shi', '', NULL, '漁父歌 李頎 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6f460078-ac6f-47bf-b189-abb2bdc73ef9', '東京寄萬楚', '东京寄万楚', 'e7091833-f8c1-44a0-ae16-cf52c39c60f1', '唐', '["濩落久無用，隱身甘采薇。","仍聞薄宦者，還事田家衣。","潁水日夜流，故人相見稀。","春山不可望，黃鳥東南飛。","濯足豈長往，一樽聊可依。","了然潭上月，適我胷中機。","在昔同門友，如今出處非。","優遊白虎殿，偃息青瑣闈。","且有薦君表，當看攜手歸。","寄書不待面，蘭茝空芳菲。"]', '["濩落久無用，隐身甘采薇。","仍闻薄宦者，還事田家衣。","潁水日夜流，故人相见稀。","春山不可望，黄鸟东南飞。","濯足豈长往，一樽聊可依。","了然潭上月，適我胷中機。","在昔同门友，如今出处非。","優游白虎殿，偃息青瑣闈。","且有薦君表，當看携手归。","寄书不待面，蘭茝空芳菲。"]', '诗', 'shi', '', NULL, '東京寄萬楚 李頎 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4cc5bce5-f928-4b20-b197-10a45c33e94a', '寄焦鍊師', '寄焦鍊師', 'e7091833-f8c1-44a0-ae16-cf52c39c60f1', '唐', '["得道凡百歲，燒丹惟一身。","悠悠孤峰頂，日見三花春。","白鶴翠微裏，黃精幽澗濱。","始知世上客，不及山中人。","仙境若在夢，朝雲如可親。","何由覩顏色，揮手謝風塵。"]', '["得道凡百歲，燒丹惟一身。","悠悠孤峰頂，日见三花春。","白鹤翠微裏，黄精幽澗濱。","始知世上客，不及山中人。","仙境若在梦，朝云如可親。","何由覩顏色，揮手謝风塵。"]', '诗', 'shi', '', NULL, '寄焦鍊師 李頎 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('96b9e04a-62fc-4192-af6b-71b7dddb3fc5', '望鳴臯山白雲寄洛陽盧主簿', '望鳴臯山白云寄洛陽盧主簿', 'e7091833-f8c1-44a0-ae16-cf52c39c60f1', '唐', '["飲馬伊水中，白雲鳴臯上。","氛氳山絕頂，行子時一望。","照日龍虎姿，攢空冰雪狀。","嵡嵸殊未已，崚嶒忽相向。","皎皎橫綠林，霏霏澹青嶂。","遠映村更失，孤高鶴來傍。","勝氣欣有逢，仙遊且難訪。","故人吏京劇，每事多閑放。","室畫峨眉峯，心格洞庭浪。","惜哉清興裏，不見予所尚。"]', '["饮马伊水中，白云鳴臯上。","氛氳山絕頂，行子时一望。","照日龙虎姿，攢空冰雪狀。","嵡嵸殊未已，崚嶒忽相向。","皎皎橫綠林，霏霏澹青嶂。","远映村更失，孤高鹤来傍。","勝氣欣有逢，仙游且难訪。","故人吏京劇，每事多闲放。","室畫峨眉峯，心格洞庭浪。","惜哉清兴裏，不见予所尚。"]', '诗', 'shi', '', NULL, '望鳴臯山白雲寄洛陽盧主簿 李頎 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a83f4910-6850-485d-afb8-4fd181db58e7', '寄萬齊融', '寄万齊融', 'e7091833-f8c1-44a0-ae16-cf52c39c60f1', '唐', '["名高不擇仕，委世隨虛舟。","小邑常歎屈，故鄉行可遊。","青楓半村戶，香稻盈田疇。","爲政日清淨，何人同海鷗。","搖巾北林夕，把菊東山秋。","對酒池雲滿，向家湖水流。","岸陰止鳴鵠，山色映潛虯。","靡靡俗中理，蕭蕭川上幽。","昔年至吳郡，常隱臨江樓。","我有一書札，因之芳杜洲。"]', '["名高不擇仕，委世隨虛舟。","小邑常歎屈，故乡行可游。","青楓半村戶，香稻盈田疇。","爲政日清淨，何人同海鷗。","搖巾北林夕，把菊东山秋。","对酒池云满，向家湖水流。","岸陰止鳴鵠，山色映潛虯。","靡靡俗中理，蕭蕭川上幽。","昔年至吳郡，常隐臨江楼。","我有一书札，因之芳杜洲。"]', '诗', 'shi', '', NULL, '寄萬齊融 李頎 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b319c3ce-bca6-48c0-b619-ab9ec41aab54', '贈張旭', '贈張旭', 'e7091833-f8c1-44a0-ae16-cf52c39c60f1', '唐', '["張公性嗜酒，豁達無所營。","皓首窮草隸，時稱太湖精。","露頂據胡牀，長呌三五聲。","興來灑素壁，揮筆如流星。","下舍風蕭條，寒草滿戶庭。","問家何所有，生事如浮萍。","左手持蟹螯，右手執丹經。","瞪目視霄漢，不知醉與醒。","諸賓且方坐，旭日臨東城。","荷葉裹江魚，白甌貯香秔。","微祿心不屑，放神於八紘。","時人不識者，即是安期生。"]', '["張公性嗜酒，豁達無所營。","皓首窮草隸，时稱太湖精。","露頂據胡牀，长呌三五声。","兴来灑素壁，揮笔如流星。","下舍风蕭條，寒草满戶庭。","问家何所有，生事如浮萍。","左手持蟹螯，右手執丹經。","瞪目視霄漢，不知醉與醒。","諸賓且方坐，旭日臨东城。","荷葉裹江鱼，白甌貯香秔。","微祿心不屑，放神於八紘。","时人不識者，即是安期生。"]', '诗', 'shi', '', NULL, '贈張旭 李頎 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e51a3ce2-cc8f-424a-a54c-43b4052eb172', '贈蘇明府', '贈蘇明府', 'e7091833-f8c1-44a0-ae16-cf52c39c60f1', '唐', '["蘇君年幾許，狀貌如玉童。","采藥傍梁宋，共言隨日翁。","常辭小縣宰，一往東山東。","不復有家室，悠悠人世中。","子孫皆老死，相識悲轉蓬。","髮白還更黑，身輕行若風。","汎然無所繫，心與孤雲同。","出入雖一杖，安然知始終。","願聞素女事，去采山花叢。","誘我爲弟子，逍遙尋葛洪。"]', '["蘇君年幾許，狀貌如玉童。","采藥傍梁宋，共言隨日翁。","常辞小縣宰，一往东山东。","不复有家室，悠悠人世中。","子孫皆老死，相識悲轉蓬。","髮白還更黑，身轻行若风。","汎然無所繫，心與孤云同。","出入雖一杖，安然知始終。","願闻素女事，去采山花叢。","誘我爲弟子，逍遙尋葛洪。"]', '诗', 'shi', '', NULL, '贈蘇明府 李頎 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f244e07a-9f1b-4bf2-957f-8c2ae2d78809', '登首陽山謁夷齊廟', '登首陽山謁夷齊廟', 'e7091833-f8c1-44a0-ae16-cf52c39c60f1', '唐', '["古人已不見，喬木竟誰過。","寂寞首陽山，白雲空復多。","蒼苔歸地骨，皓首采薇歌。","畢命無怨色，成仁其若何。","我來入遺廟，時候微清和。","落日弔山鬼，回風吹女蘿。","石崖向西豁，引領望黃河。","千里一飛鳥，孤光東逝波。","驅車層城路，惆悵此巖阿。"]', '["古人已不见，喬木竟誰過。","寂寞首陽山，白云空复多。","蒼苔归地骨，皓首采薇歌。","畢命無怨色，成仁其若何。","我来入遺廟，时候微清和。","落日弔山鬼，回风吹女蘿。","石崖向西豁，引領望黄河。","千里一飞鸟，孤光东逝波。","驱车層城路，惆悵此巖阿。"]', '诗', 'shi', '', NULL, '登首陽山謁夷齊廟 李頎 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8563597c-df86-421a-9aa8-03e029995e2c', '謁張果先生', '謁張果先生', 'e7091833-f8c1-44a0-ae16-cf52c39c60f1', '唐', '["先生谷神者，甲子焉能計。","自說軒轅師，于今幾千歲。","寓遊城郭裏，浪跡希夷際。","應物雲無心，逢時舟不繫。","餐霞斷火粒，野服兼荷製。","白雪淨肌膚，青松養身世。","韜精殊豹隱，鍊骨同蟬蛻。","忽去不知誰，偶來寧有契。","二儀齊壽考，六合隨休憩。","彭耼猶嬰孩，松期且微細。","嘗聞穆天子，更憶漢皇帝。","親屈萬乘尊，將窮四海裔。","車徒徧草木，錦帛招談說。","八駿空往還，三山轉虧蔽。","吾君感至德，玄老欣來詣。","受籙金殿開，清齋玉堂閉。","笙歌迎拜首，羽帳崇嚴衞。","禁柳垂香鑪，宮花拂仙袂。","祈年寶祚廣，致福蒼生惠。","何必待龍髯，鼎成方取濟。"]', '["先生谷神者，甲子焉能計。","自说軒轅師，于今幾千歲。","寓游城郭裏，浪跡希夷際。","應物云無心，逢时舟不繫。","餐霞斷火粒，野服兼荷製。","白雪淨肌膚，青松養身世。","韜精殊豹隐，鍊骨同蟬蛻。","忽去不知誰，偶来寧有契。","二儀齊壽考，六合隨休憩。","彭耼猶嬰孩，松期且微細。","嘗闻穆天子，更憶漢皇帝。","親屈万乘尊，將窮四海裔。","车徒徧草木，錦帛招談说。","八駿空往還，三山轉虧蔽。","吾君感至德，玄老欣来詣。","受籙金殿开，清斋玉堂閉。","笙歌迎拜首，羽帳崇嚴衞。","禁柳垂香鑪，宮花拂仙袂。","祈年寶祚廣，致福蒼生惠。","何必待龙髯，鼎成方取濟。"]', '诗', 'shi', '', NULL, '謁張果先生 李頎 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('26953709-a8f3-4944-863e-cb446b59e85f', '光上座廊下衆山五韻', '光上座廊下衆山五韻', 'e7091833-f8c1-44a0-ae16-cf52c39c60f1', '唐', '["名嶽在廡下，吾師居一牀。","每聞楞伽經，只對清翠光。","百谷聚雪色，莓苔侵屋梁。","氣盤古壁轉，勢引幽堦長。","願遊薜葉下，日見金鑪香。"]', '["名嶽在廡下，吾師居一牀。","每闻楞伽經，只对清翠光。","百谷聚雪色，莓苔侵屋梁。","氣盤古壁轉，勢引幽堦长。","願游薜葉下，日见金鑪香。"]', '诗', 'shi', '', NULL, '光上座廊下衆山五韻 李頎 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8ab5c0f7-3552-47db-972c-966aef096c68', '九月九日劉十八東堂集', '九月九日劉十八东堂集', 'e7091833-f8c1-44a0-ae16-cf52c39c60f1', '唐', '["風俗尚九日，此情安可忘。","菊花辟惡酒，湯餅茱萸香。","雲入授衣假，風吹閑宇涼。","主人盡歡意，林景晝微茫。","清切晚砧動，東西歸鳥行。","淹留悵爲別，日醉秋雲光。"]', '["风俗尚九日，此情安可忘。","菊花辟惡酒，湯餅茱萸香。","云入授衣假，风吹闲宇涼。","主人尽歡意，林景晝微茫。","清切晚砧动，东西归鸟行。","淹留悵爲別，日醉秋云光。"]', '诗', 'shi', '', NULL, '九月九日劉十八東堂集 李頎 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9b92e0d6-89ed-4d59-b017-cea38d70ac1d', '宋少府東谿泛舟', '宋少府东谿泛舟', 'e7091833-f8c1-44a0-ae16-cf52c39c60f1', '唐', '["登岸還入舟，水禽驚笑語。","晚葉低衆色，濕雲帶殘暑。","落日乘醉歸，溪流復幾許。"]', '["登岸還入舟，水禽驚笑語。","晚葉低衆色，濕云带殘暑。","落日乘醉归，溪流复幾許。"]', '诗', 'shi', '', NULL, '宋少府東谿泛舟 李頎 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('084dd7b8-1ae4-44c7-af74-7890a1d8b817', '與諸公遊濟瀆泛舟', '與諸公游濟瀆泛舟', 'e7091833-f8c1-44a0-ae16-cf52c39c60f1', '唐', '["濟水出王屋，其源來不窮。","洑泉數眼沸，平地流清通。","皇帝崇祀典，詔書視三公。","分官禱靈廟，奠璧沈河宮。","神應每如荅，松篁氣葱蘢。","蒼螭送飛雨，赤鯉噴迴風。","灑酒布瑤席，吹簫下玉童。","玄冥掌陰事，祝史告年豐。","百谷趨潭底，三光懸鏡中。","淺深露沙石，蘋藻生虛空。","晚景臨汎美，亭臯輕靄紅。","晴山傍舟楫，白鷺驚絲桐。","我本家潁北，開門見維嵩。","焉知松峰外，又有天壇東。","左手正接䍦，浩歌眄青穹。","夷猶傲清吏，偃仰狎漁翁。","對此川上閑，非君誰與同。","霜凝遠村渚，月靜蒹葭叢。","茲境信難遇，爲歡殊未終。","淹留悵言別，煙嶼夕微濛。"]', '["濟水出王屋，其源来不窮。","洑泉數眼沸，平地流清通。","皇帝崇祀典，詔书視三公。","分官禱靈廟，奠璧沈河宮。","神應每如荅，松篁氣葱蘢。","蒼螭送飞雨，赤鯉噴迴风。","灑酒布瑤席，吹簫下玉童。","玄冥掌陰事，祝史告年豐。","百谷趨潭底，三光懸镜中。","淺深露沙石，蘋藻生虛空。","晚景臨汎美，亭臯轻靄紅。","晴山傍舟楫，白鷺驚絲桐。","我本家潁北，开门见維嵩。","焉知松峰外，又有天壇东。","左手正接䍦，浩歌眄青穹。","夷猶傲清吏，偃仰狎漁翁。","对此川上闲，非君誰與同。","霜凝远村渚，月静蒹葭叢。","茲境信难遇，爲歡殊未終。","淹留悵言別，煙嶼夕微濛。"]', '诗', 'shi', '', NULL, '與諸公遊濟瀆泛舟 李頎 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('913eeddf-2223-49e4-b04a-6d266420b8b4', '送綦毋三謁房給事', '送綦毋三謁房給事', 'e7091833-f8c1-44a0-ae16-cf52c39c60f1', '唐', '["夫子大名下，家無鍾石儲。","惜哉湖海上，曾校蓬萊書。","外物非本意，此生空澹如。","所思但乘興，遠適唯單車。","高道時坎坷，故交願吹噓。","徒言青瑣闥，不愛承明廬。","百里人戶滿，片言爭訟疎。","手持蓮花經，目送飛鳥餘。","晚景南路別，炎雲中伏初。","此行儻不遂，歸食蘆洲魚。"]', '["夫子大名下，家無鍾石儲。","惜哉湖海上，曾校蓬萊书。","外物非本意，此生空澹如。","所思但乘兴，远適唯單车。","高道时坎坷，故交願吹噓。","徒言青瑣闥，不愛承明廬。","百里人戶满，片言爭訟疎。","手持蓮花經，目送飞鸟餘。","晚景南路別，炎云中伏初。","此行儻不遂，归食蘆洲鱼。"]', '诗', 'shi', '', NULL, '送綦毋三謁房給事 李頎 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5d1a07c5-1b42-4e2d-8e4e-bfcd0205fb5d', '送劉四', '送劉四', 'e7091833-f8c1-44a0-ae16-cf52c39c60f1', '唐', '["愛君少岐嶷，高視白雲鄉。","九歲能屬文，謁帝遊明光。","奉詔赤墀下，拜爲童子郎。","爾來屢遷易，三度尉洛陽。","洛陽十二門，官寺鬱相望。","青槐羅四面，淥水貫中央。","聽訟破秋毫，應物利干將。","辭滿如脫屣，立言無否臧。","歲暮風雪暗，秦中川路長。","行人飲臘酒，立馬帶晨霜。","生事豈須問，故園寒草荒。","從今署右職，莫笑在農桑。"]', '["愛君少岐嶷，高視白云乡。","九歲能屬文，謁帝游明光。","奉詔赤墀下，拜爲童子郎。","爾来屢遷易，三度尉洛陽。","洛陽十二门，官寺鬱相望。","青槐羅四面，淥水貫中央。","听訟破秋毫，應物利干將。","辞满如脫屣，立言無否臧。","歲暮风雪暗，秦中川路长。","行人饮臘酒，立马带晨霜。","生事豈須问，故园寒草荒。","從今署右職，莫笑在農桑。"]', '诗', 'shi', '', NULL, '送劉四 李頎 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c882b85c-c30f-4170-818c-6aaca98c2c56', '送裴騰', '送裴腾', 'e7091833-f8c1-44a0-ae16-cf52c39c60f1', '唐', '["養德爲衆許，森然此丈夫。","放情白雲外，爽氣連虯鬚。","衡鏡合知子，公心誰謂無。","還令不得意，單馬遂長驅。","桑野蠶忙時，憐君久踟躕。","新晴荷卷葉，孟夏雉將雛。","令弟爲縣尹，高城汾水隅。","相將簿領閑，倚望恆峰孤。","香露團百草，紫梨分萬株。","歸來授衣假，莫使故園蕪。"]', '["養德爲衆許，森然此丈夫。","放情白云外，爽氣連虯鬚。","衡镜合知子，公心誰謂無。","還令不得意，單马遂长驱。","桑野蠶忙时，怜君久踟躕。","新晴荷卷葉，孟夏雉將雛。","令弟爲縣尹，高城汾水隅。","相將簿領闲，倚望恆峰孤。","香露團百草，紫梨分万株。","归来授衣假，莫使故园蕪。"]', '诗', 'shi', '', NULL, '送裴騰 李頎 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1d8a6b43-688d-4ba7-8086-84896e70fd46', '送司農崔丞', '送司農崔丞', 'e7091833-f8c1-44a0-ae16-cf52c39c60f1', '唐', '["黃鸝鳴官寺，香草色未已。","同時皆省郎，而我獨留此。","維監太倉粟，常對府小史。","清陰羅廣庭，政事如流水。","奉使往長安，今承朝野歡。","宰臣應記識，明主必遷官。","塞外貔將虎，池中鴛與鸞。","詞人洞簫賦，公子鵕䴊冠。","邑里春方晚，昆明花欲闌。","行行取高位，當使路傍看。"]', '["黄鸝鳴官寺，香草色未已。","同时皆省郎，而我独留此。","維監太倉粟，常对府小史。","清陰羅廣庭，政事如流水。","奉使往长安，今承朝野歡。","宰臣應記識，明主必遷官。","塞外貔將虎，池中鴛與鸾。","词人洞簫賦，公子鵕䴊冠。","邑里春方晚，昆明花欲闌。","行行取高位，當使路傍看。"]', '诗', 'shi', '', NULL, '送司農崔丞 李頎 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('33fae014-571f-48d1-87c4-9d5c95e3fd99', '送崔侍御赴京', '送崔侍御赴京', 'e7091833-f8c1-44a0-ae16-cf52c39c60f1', '唐', '["綠槐蔭長路，駿馬垂青絲。","柱史謁承明，翩翩將有期。","千官大朝日，奏事臨赤墀。","肅肅儀仗裏，風生鷹隼姿。","一從登甲科，三拜皆憲司。","按俗又如此，爲郎何太遲。","送君暮春月，花落城南陲。","惜別醉芳草，前山勞夢思。"]', '["綠槐蔭长路，駿马垂青絲。","柱史謁承明，翩翩將有期。","千官大朝日，奏事臨赤墀。","肅肅儀仗裏，风生鷹隼姿。","一從登甲科，三拜皆憲司。","按俗又如此，爲郎何太遲。","送君暮春月，花落城南陲。","惜別醉芳草，前山勞梦思。"]', '诗', 'shi', '', NULL, '送崔侍御赴京 李頎 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('cce21b17-efea-42eb-8fc8-37ae7799efb7', '春送從叔遊襄陽', '春送從叔游襄陽', 'e7091833-f8c1-44a0-ae16-cf52c39c60f1', '唐', '["言別恨非一，棄置我宗英。","向用五經笥，今爲千里行。","裹糧顧庭草，羸馬詰朝鳴。","斗酒對寒食，雜花宜晚晴。","春衣采洲路，夜飲南陽城。","客夢峴山曉，漁歌江水清。","楚俗少相知，遠遊難稱情。","同人應館穀，刺史在郊迎。","只合侍丹扆，翻令辭上京。","時方春欲暮，歎息向流鶯。"]', '["言別恨非一，棄置我宗英。","向用五經笥，今爲千里行。","裹糧顧庭草，羸马詰朝鳴。","斗酒对寒食，杂花宜晚晴。","春衣采洲路，夜饮南陽城。","客梦峴山晓，漁歌江水清。","楚俗少相知，远游难稱情。","同人應館穀，刺史在郊迎。","只合侍丹扆，翻令辞上京。","时方春欲暮，歎息向流鶯。"]', '诗', 'shi', '', NULL, '春送從叔遊襄陽 李頎 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('bd82a5d7-3a57-4e23-9241-de29fe14e4a6', '贈別高三十五', '贈別高三十五', 'e7091833-f8c1-44a0-ae16-cf52c39c60f1', '唐', '["五十無產業，心輕百萬資。","屠酤亦與羣，不問君是誰。","飲酒或垂釣，狂歌兼詠詩。","焉知漢高士，莫識越鴟夷。","寄跡棲霞山，蓬頭睢水湄。","忽然辟命下，衆謂趨丹墀。","沐浴著賜衣，西來馬行遲。","能令相府重，且有函關期。","僶俛從寸祿，舊遊梁宋時。","皤皤邑中叟，相候鬢如絲。","官舍柳林靜，河梁杏葉滋。","摘芳雲景[晏]，把手秋蟬悲。","小縣情未愜，折腰君莫辭。","吾觀主人意，不久召京師。"]', '["五十無產業，心轻百万資。","屠酤亦與羣，不问君是誰。","饮酒或垂釣，狂歌兼詠诗。","焉知漢高士，莫識越鴟夷。","寄跡棲霞山，蓬头睢水湄。","忽然辟命下，衆謂趨丹墀。","沐浴著賜衣，西来马行遲。","能令相府重，且有函关期。","僶俛從寸祿，旧游梁宋时。","皤皤邑中叟，相候鬢如絲。","官舍柳林静，河梁杏葉滋。","摘芳云景[晏]，把手秋蟬悲。","小縣情未愜，折腰君莫辞。","吾观主人意，不久召京師。"]', '诗', 'shi', '', NULL, '贈別高三十五 李頎 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('fd7cd1a8-1b91-42b9-99e8-86be0d63f433', '崔五宅送劉跂入京', '崔五宅送劉跂入京', 'e7091833-f8c1-44a0-ae16-cf52c39c60f1', '唐', '["行人惜寸景，繫馬暫留歡。","昨日辭小沛，何時到長安。","鄉中飲酒禮，客裏行路難。","清洛雲鴻度，故關風日寒。","維將道可樂，不念身無官。","生事東山遠，田園芳歲闌。","東歸余謝病，西去子加餐。","宋伯非徒爾，明時正可干。","躬耕守貧賤，失計在林端。","宿昔奉顏色，慙無雙玉盤。"]', '["行人惜寸景，繫马暫留歡。","昨日辞小沛，何时到长安。","乡中饮酒禮，客裏行路难。","清洛云鴻度，故关风日寒。","維將道可乐，不念身無官。","生事东山远，田园芳歲闌。","东归余謝病，西去子加餐。","宋伯非徒爾，明时正可干。","躬耕守貧賤，失計在林端。","宿昔奉顏色，慙無雙玉盤。"]', '诗', 'shi', '', NULL, '崔五宅送劉跂入京 李頎 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('262f0dbe-9391-437d-aac3-26afc0fb0733', '送馬錄事赴永陽', '送马錄事赴永陽', 'e7091833-f8c1-44a0-ae16-cf52c39c60f1', '唐', '["子爲郡從事，主印清淮邊。","談笑一州裏，從容羣吏先。","手持三尺令，遣決如流泉。","太守既相許，諸公誰不然。","孤城連海樹，萬室帶山烟。","春日谿湖淨，芳洲葭菼連。","炊秔蟹螯熟，下筯鱸魚鮮。","野鶴宿簷際，楚雲飛面前。","聽歌送離曲，且駐木蘭船。","贈爾八行字，當聞佳政傳。"]', '["子爲郡從事，主印清淮邊。","談笑一州裏，從容羣吏先。","手持三尺令，遣決如流泉。","太守既相許，諸公誰不然。","孤城連海樹，万室带山烟。","春日谿湖淨，芳洲葭菼連。","炊秔蟹螯熟，下筯鱸鱼鲜。","野鹤宿簷際，楚云飞面前。","听歌送離曲，且駐木蘭船。","贈爾八行字，當闻佳政傳。"]', '诗', 'shi', '', NULL, '送馬錄事赴永陽 李頎 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ea33eb99-eb29-4334-b8f4-a88622fc8c1e', '臨別送張諲入蜀', '臨別送張諲入蜀', 'e7091833-f8c1-44a0-ae16-cf52c39c60f1', '唐', '["出門便爲客，惘然悲徒御。","四海維一身，茫茫欲何去？","經山復歷水，百恨將千慮。","劒閣望梁州，是君斷腸處。","孤雲傷客心，落日感君深。","夢裏蒹葭渚，天邊橘柚林。","蜀江流不測，蜀路險難尋。","木有相思號，猿多愁苦音。","莫向愚山隱，愚山地非近。","故鄉可歸來，眼見芳菲盡。"]', '["出门便爲客，惘然悲徒御。","四海維一身，茫茫欲何去？","經山复歷水，百恨將千慮。","劒閣望梁州，是君斷腸处。","孤云傷客心，落日感君深。","梦裏蒹葭渚，天邊橘柚林。","蜀江流不測，蜀路險难尋。","木有相思號，猿多愁苦音。","莫向愚山隐，愚山地非近。","故乡可归来，眼见芳菲尽。"]', '诗', 'shi', '', NULL, '臨別送張諲入蜀 李頎 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ddb67b2a-3bbe-4547-b7e0-01ccfa746cea', '送王昌齡', '送王昌齡', 'e7091833-f8c1-44a0-ae16-cf52c39c60f1', '唐', '["漕水東去遠，送君多暮情。","淹留野寺出，向背孤山明。","前望數千里，中無蒲稗生。","夕陽滿舟檝，但愛微波清。","舉酒林月上，解衣沙鳥鳴。","夜來蓮花界，夢裏金陵城。","歎息此離別，悠悠江海行。"]', '["漕水东去远，送君多暮情。","淹留野寺出，向背孤山明。","前望數千里，中無蒲稗生。","夕陽满舟檝，但愛微波清。","舉酒林月上，解衣沙鸟鳴。","夜来蓮花界，梦裏金陵城。","歎息此離別，悠悠江海行。"]', '诗', 'shi', '', NULL, '送王昌齡 李頎 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0f58192e-1519-4c9d-a66b-278395c4869d', '留別王盧二拾遺', '留別王盧二拾遺', 'e7091833-f8c1-44a0-ae16-cf52c39c60f1', '唐', '["此別不可道，此心當報誰。","春風灞水上，飲馬桃花時。","誤作好文士，只令遊宦遲。","留書下朝客，我有故山期。"]', '["此別不可道，此心當報誰。","春风灞水上，饮马桃花时。","誤作好文士，只令游宦遲。","留书下朝客，我有故山期。"]', '诗', 'shi', '', NULL, '留別王盧二拾遺 李頎 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('03edf446-52b4-4ede-baeb-d5f484388a9c', '贈別穆元林', '贈別穆元林', 'e7091833-f8c1-44a0-ae16-cf52c39c60f1', '唐', '["貳職久辭滿，藏名三十年。","丹墀策頻獻，白首官不遷。","明主日徵士，吏曹何忽賢。","空懷濟世業，欲棹滄浪船。","舉酒洛門外，送君春海邊。","彼鄉有令弟，小邑試烹鮮。","轉浦雲壑媚，涉江花島連。","綠芳暗楚水，白鳥飛吳烟。","贈贐亦奚貴，流亂期早旋。","金閨會通籍，生事豈徒然。"]', '["貳職久辞满，藏名三十年。","丹墀策頻獻，白首官不遷。","明主日徵士，吏曹何忽賢。","空懷濟世業，欲棹滄浪船。","舉酒洛门外，送君春海邊。","彼乡有令弟，小邑試烹鲜。","轉浦云壑媚，涉江花島連。","綠芳暗楚水，白鸟飞吳烟。","贈贐亦奚貴，流亂期早旋。","金閨會通籍，生事豈徒然。"]', '诗', 'shi', '', NULL, '贈別穆元林 李頎 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d6b908f8-4a90-4fc9-8ba7-cab0ca3a9525', '不調歸東川別業', '不調归东川別業', 'e7091833-f8c1-44a0-ae16-cf52c39c60f1', '唐', '["寸祿言可取，託身將見遺。","慙無匹夫志，悔與名山辭。","紱冕謝知己，林園多後時。","葛巾方濯足，蔬食但垂帷。","十室對河岸，漁樵祗在茲。","青郊香杜若，白水映茅茨。","晝景徹雲樹，夕陰澄古逵。","渚花獨開晚，田鶴靜飛遲。","且復樂生事，前賢爲我師。","清歌聊鼓楫，永日望佳期。"]', '["寸祿言可取，託身將见遺。","慙無匹夫志，悔與名山辞。","紱冕謝知己，林园多後时。","葛巾方濯足，蔬食但垂帷。","十室对河岸，漁樵祗在茲。","青郊香杜若，白水映茅茨。","晝景徹云樹，夕陰澄古逵。","渚花独开晚，田鹤静飞遲。","且复乐生事，前賢爲我師。","清歌聊鼓楫，永日望佳期。"]', '诗', 'shi', '', NULL, '不調歸東川別業 李頎 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2a8c0c7d-a5e6-4b75-bc91-27db46d10514', '晚歸東園', '晚归东园', 'e7091833-f8c1-44a0-ae16-cf52c39c60f1', '唐', '["出郭喜見山，東行亦未遠。","夕陽帶歸路，靄靄秋稼晚。","樵者乘霽歸，野夫及星飯。","請謝朱輪客，垂竿不復返。"]', '["出郭喜见山，东行亦未远。","夕陽带归路，靄靄秋稼晚。","樵者乘霽归，野夫及星飯。","請謝朱輪客，垂竿不复返。"]', '诗', 'shi', '', NULL, '晚歸東園 李頎 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('030bc8a8-cd23-4ef6-892f-bd7bf9b9f574', '龍門西峰曉望劉十八不至', '龙门西峰晓望劉十八不至', 'e7091833-f8c1-44a0-ae16-cf52c39c60f1', '唐', '["春臺臨永路，跂足望行子。","片片雲觸峯，離離鳥渡水。","叢林遠山上，霽景雜花裏。","不見攜手人，下山采綠芷。"]', '["春台臨永路，跂足望行子。","片片云觸峯，離離鸟渡水。","叢林远山上，霽景杂花裏。","不见携手人，下山采綠芷。"]', '诗', 'shi', '', NULL, '龍門西峰曉望劉十八不至 李頎 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6aa7fd69-3fcb-4563-89bf-36b03deb963f', '裴尹東溪別業', '裴尹东溪別業', 'e7091833-f8c1-44a0-ae16-cf52c39c60f1', '唐', '["公才廊廟器，官亞河南守。","別墅臨都門，驚湍激前後。","舊交與羣從，十日一攜手。","幅巾望寒山，長嘯對高柳。","清歡信可尚，散吏亦何有。","岸雪清城陰，水光遠林首。","閑觀野人筏，或飲川上酒。","幽雲澹徘徊，白鷺飛左右。","庭竹垂臥內，村烟隔南阜。","始知物外情，簪紱同芻狗。"]', '["公才廊廟器，官亞河南守。","別墅臨都门，驚湍激前後。","旧交與羣從，十日一携手。","幅巾望寒山，长嘯对高柳。","清歡信可尚，散吏亦何有。","岸雪清城陰，水光远林首。","闲观野人筏，或饮川上酒。","幽云澹徘徊，白鷺飞左右。","庭竹垂臥內，村烟隔南阜。","始知物外情，簪紱同芻狗。"]', '诗', 'shi', '', NULL, '裴尹東溪別業 李頎 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4919a496-5692-4730-9364-f49584465567', '無盡上人東林禪居', '無尽上人东林禪居', 'e7091833-f8c1-44a0-ae16-cf52c39c60f1', '唐', '["草堂每多暇，時謁山僧門。","所對但羣木，終朝無一言。","我心愛流水，此地臨清源。","含吐山上日，蔽虧松外村。","孤峯隔身世，百衲老寒暄。","禪戶積朝雪，花龕來暮猿。","顧余守耕稼，十載隱田園。","蘿篠慰舂汲，巖潭恣討論。","洩雲豈知限，至道莫探元。","且願啓關鎖，於焉微尚存。"]', '["草堂每多暇，时謁山僧门。","所对但羣木，終朝無一言。","我心愛流水，此地臨清源。","含吐山上日，蔽虧松外村。","孤峯隔身世，百衲老寒暄。","禪戶積朝雪，花龕来暮猿。","顧余守耕稼，十載隐田园。","蘿篠慰舂汲，巖潭恣討論。","洩云豈知限，至道莫探元。","且願啓关鎖，於焉微尚存。"]', '诗', 'shi', '', NULL, '無盡上人東林禪居 李頎 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e33894c8-b607-4ee3-a08b-94ce8e159a47', '題綦毋校書別業', '題綦毋校书別業', 'e7091833-f8c1-44a0-ae16-cf52c39c60f1', '唐', '["常稱挂冠吏，昨日歸滄洲。","行客暮帆遠，主人庭樹秋。","豈伊問天命，但欲爲山遊。","萬物我何有，白雲空自幽。","蕭條江海上，日夕見丹丘。","生事非漁釣，賞心隨去留。","惜哉曠微月，欲濟無輕舟。","倏忽令人老，相思河水流。"]', '["常稱挂冠吏，昨日归滄洲。","行客暮帆远，主人庭樹秋。","豈伊问天命，但欲爲山游。","万物我何有，白云空自幽。","蕭條江海上，日夕见丹丘。","生事非漁釣，賞心隨去留。","惜哉曠微月，欲濟無轻舟。","倏忽令人老，相思河水流。"]', '诗', 'shi', '', NULL, '題綦毋校書別業 李頎 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('54dd54ea-8d4b-4872-9990-51bee11135e1', '題盧道士房', '題盧道士房', 'e7091833-f8c1-44a0-ae16-cf52c39c60f1', '唐', '["秋砧響落木，共坐茅君家。","惟見兩童子，林前汲井華。","空壇靜白日，神鼎飛丹砂。","麈尾拂霜草，金鈴搖霽霞。","上章人世隔，看[弈]桐陰斜。","稽首問仙要，黃精堪餌花。"]', '["秋砧响落木，共坐茅君家。","惟见兩童子，林前汲井华。","空壇静白日，神鼎飞丹砂。","麈尾拂霜草，金鈴搖霽霞。","上章人世隔，看[弈]桐陰斜。","稽首问仙要，黄精堪餌花。"]', '诗', 'shi', '', NULL, '題盧道士房 李頎 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d69db332-54ab-4736-b29a-2aa858ba5666', '題神力師院', '題神力師院', 'e7091833-f8c1-44a0-ae16-cf52c39c60f1', '唐', '["大師神傑貌，五嶽森禪房。","堅持日月珠，豁見滄江長。","隨病拔諸苦，致身如法王。","階庭藥草徧，飯食天花香。","樹色向高閣，晝陰橫半牆。","每聞第一義，心淨琉璃光。"]', '["大師神傑貌，五嶽森禪房。","堅持日月珠，豁见滄江长。","隨病拔諸苦，致身如法王。","階庭藥草徧，飯食天花香。","樹色向高閣，晝陰橫半牆。","每闻第一義，心淨琉璃光。"]', '诗', 'shi', '', NULL, '題神力師院 李頎 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9291dfae-21bb-44af-aac4-d3c3021b3679', '題僧房雙桐', '題僧房雙桐', 'e7091833-f8c1-44a0-ae16-cf52c39c60f1', '唐', '["青桐雙拂日，傍帶凌霄花。","綠葉傳僧磬，清陰潤井華。","誰能事音律，焦尾蔡邕家。"]', '["青桐雙拂日，傍带凌霄花。","綠葉傳僧磬，清陰潤井华。","誰能事音律，焦尾蔡邕家。"]', '诗', 'shi', '', NULL, '題僧房雙桐 李頎 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('bce4276d-3417-4536-8561-c80315567bf1', '粲公院各賦一物得初荷', '粲公院各賦一物得初荷', 'e7091833-f8c1-44a0-ae16-cf52c39c60f1', '唐', '["微風和衆草，大葉長圓陰。","晴露珠共合，夕陽花映深。","從來不著水，清淨本因心。"]', '["微风和衆草，大葉长圓陰。","晴露珠共合，夕陽花映深。","從来不著水，清淨本因心。"]', '诗', 'shi', '', NULL, '粲公院各賦一物得初荷 李頎 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a2b1ed12-6ad1-482d-ae96-618d70c82f19', '李兵曹壁畫山水各賦得桂水帆', '李兵曹壁畫山水各賦得桂水帆', 'e7091833-f8c1-44a0-ae16-cf52c39c60f1', '唐', '["片帆浮桂水，落日天涯時。","飛鳥看共度，閑雲相與遲。","長波無曉夜，泛泛欲何之。"]', '["片帆浮桂水，落日天涯时。","飞鸟看共度，闲云相與遲。","长波無晓夜，泛泛欲何之。"]', '诗', 'shi', '', NULL, '李兵曹壁畫山水各賦得桂水帆 李頎 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('dee01ede-afc6-440b-841a-3cd8c26a33f6', '題合歡', '題合歡', 'e7091833-f8c1-44a0-ae16-cf52c39c60f1', '唐', '["開花復卷葉，豔眼又驚心。","蝶遶西枝露，風披東幹陰。","黃衫漂細蘂，時拂女郎砧。"]', '["开花复卷葉，豔眼又驚心。","蝶遶西枝露，风披东幹陰。","黄衫漂細蘂，时拂女郎砧。"]', '诗', 'shi', '', NULL, '題合歡 李頎 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('bea6f283-8f90-49b5-8842-1cb906816548', '古從軍行', '古從軍行', 'e7091833-f8c1-44a0-ae16-cf52c39c60f1', '唐', '["白日登山望烽火，黃昏飲馬傍交河。","行人刁斗風沙暗，公主琵琶幽怨多。","野雲萬里無城郭，雨雪紛紛連大漠。","胡鴈哀鳴夜夜飛，胡兒眼淚雙雙落。","聞道玉門猶被遮，應將性命逐輕車。","年年戰骨埋荒外，空見蒲桃入漢家。"]', '["白日登山望烽火，黄昏饮马傍交河。","行人刁斗风沙暗，公主琵琶幽怨多。","野云万里無城郭，雨雪紛紛連大漠。","胡鴈哀鳴夜夜飞，胡兒眼泪雙雙落。","闻道玉门猶被遮，應將性命逐轻车。","年年戰骨埋荒外，空见蒲桃入漢家。"]', '诗', 'shi', '', NULL, '古從軍行 李頎 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('fd7beda9-a386-4117-bb7f-c1f6df62dd16', '行路難', '行路难', 'e7091833-f8c1-44a0-ae16-cf52c39c60f1', '唐', '["漢家名臣楊德祖，四代五公享茅土。","父子兄弟綰銀黃，躍馬鳴珂朝建章。","火浣單衣繡方領，茱萸錦帶玉盤囊。","賓客填街復滿座，片言出口生輝光。","世人逐勢爭奔走，瀝膽墮肝惟恐後。","當時一顧登青雲，自謂生死長隨君。","一朝謝病還鄉里，窮巷蒼苔絕知己。","秋風落葉閉重門，昨日論交竟誰是。","薄俗嗟嗟難重陳，深山麋鹿可爲鄰。","魯連所以蹈東海，古往今來稱達人。"]', '["漢家名臣楊德祖，四代五公享茅土。","父子兄弟綰銀黄，躍马鳴珂朝建章。","火浣單衣繡方領，茱萸錦带玉盤囊。","賓客填街复满座，片言出口生輝光。","世人逐勢爭奔走，瀝膽墮肝惟恐後。","當时一顧登青云，自謂生死长隨君。","一朝謝病還乡里，窮巷蒼苔絕知己。","秋风落葉閉重门，昨日論交竟誰是。","薄俗嗟嗟难重陳，深山麋鹿可爲鄰。","魯連所以蹈东海，古往今来稱達人。"]', '诗', 'shi', '', NULL, '行路難 李頎 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('eb91e314-0451-46a4-b1ec-9fbde0987d8d', '緩歌行', '緩歌行', 'e7091833-f8c1-44a0-ae16-cf52c39c60f1', '唐', '["小來託身攀貴遊，傾財破產無所憂。","暮擬經過石渠署，朝將出入銅龍樓。","結交杜陵輕薄子，謂言可生復可死。","一沈一浮會有時，棄我翻然如脫屣。","男兒立身須自強，十年閉戶潁水陽。","業就功成見明主，擊鐘鼎食坐華堂。","二八蛾眉梳墮馬，美酒清歌曲房下。","文昌宮中賜錦衣，長安陌上退朝歸。","五陵賓從莫敢視，三省官僚揖者稀。","早知今日讀書是，悔作從前任俠非。"]', '["小来託身攀貴游，傾財破產無所憂。","暮擬經過石渠署，朝將出入銅龙楼。","結交杜陵轻薄子，謂言可生复可死。","一沈一浮會有时，棄我翻然如脫屣。","男兒立身須自強，十年閉戶潁水陽。","業就功成见明主，擊鐘鼎食坐华堂。","二八蛾眉梳墮马，美酒清歌曲房下。","文昌宮中賜錦衣，长安陌上退朝归。","五陵賓從莫敢視，三省官僚揖者稀。","早知今日读书是，悔作從前任俠非。"]', '诗', 'shi', '', NULL, '緩歌行 李頎 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7d906794-b4d1-4922-9c59-eee5b19602ad', '琴歌', '琴歌', 'e7091833-f8c1-44a0-ae16-cf52c39c60f1', '唐', '["主人有酒歡今夕，請奏鳴琴廣陵客。","月照城頭烏半飛，霜淒萬樹風入衣。","銅鑪華燭燭增輝，初彈淥水後楚妃。","一聲已動物皆靜，四座無言星欲稀。","清淮奉使千餘里，敢告雲山從此始。"]', '["主人有酒歡今夕，請奏鳴琴廣陵客。","月照城头烏半飞，霜淒万樹风入衣。","銅鑪华燭燭增輝，初彈淥水後楚妃。","一声已动物皆静，四座無言星欲稀。","清淮奉使千餘里，敢告云山從此始。"]', '诗', 'shi', '', NULL, '琴歌 李頎 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5d85a4dd-bcfd-4a2b-9752-679fe76c46c6', '放歌行荅從弟墨卿', '放歌行荅從弟墨卿', 'e7091833-f8c1-44a0-ae16-cf52c39c60f1', '唐', '["小來好文恥學武，世上功名不解取。","雖沾寸祿已後時，徒欲出身事明主。","柏梁賦詩不及宴，長楸走馬誰相數。","歛迹俛眉心自甘，高歌擊節聲半苦。","由是蹉跎一老夫，養雞牧豕東城隅。","空歌漢代蕭相國，肯事霍家馮子都。","徒爾當年聲籍籍，濫作詞林兩京客。","故人斗酒安陵橋，黃鳥春風洛陽陌。","吾家令弟才不羈，五言破的人共推。","興來逸氣若濤湧，千里長江歸海時。","別離短景何蕭索，佳句相思能間作。","舉頭遙望魯陽山，木葉紛紛向人落。"]', '["小来好文恥学武，世上功名不解取。","雖沾寸祿已後时，徒欲出身事明主。","柏梁賦诗不及宴，长楸走马誰相數。","歛迹俛眉心自甘，高歌擊節声半苦。","由是蹉跎一老夫，養雞牧豕东城隅。","空歌漢代蕭相国，肯事霍家馮子都。","徒爾當年声籍籍，濫作词林兩京客。","故人斗酒安陵橋，黄鸟春风洛陽陌。","吾家令弟才不羈，五言破的人共推。","兴来逸氣若濤湧，千里长江归海时。","別離短景何蕭索，佳句相思能间作。","舉头遙望魯陽山，木葉紛紛向人落。"]', '诗', 'shi', '', NULL, '放歌行荅從弟墨卿 李頎 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('db5c92b9-ba8c-4ffd-be09-b31293cdca71', '王母歌', '王母歌', 'e7091833-f8c1-44a0-ae16-cf52c39c60f1', '唐', '["武皇齋戒承華殿，端拱須臾王母見。","霓旌照耀麒麟車，羽蓋淋漓孔雀扇。","手指交梨遣帝食，可以長生臨宇縣。","頭上復戴九星冠，總領玉童坐南面。","欲聞要言今告汝，帝乃焚香請此語。","若能鍊魄去三尸，後當見我天皇所。","顧謂侍女董雙成，酒闌可奏雲和笙。","紅霞白日儼不動，七龍五鳳紛相迎。","惜哉志驕神不悅，歎息馬蹄與車轍。","複道歌鐘杳將暮，深宮桃李花成雪。","爲看青玉五枝燈，蟠螭吐火光欲絕。"]', '["武皇斋戒承华殿，端拱須臾王母见。","霓旌照耀麒麟车，羽蓋淋漓孔雀扇。","手指交梨遣帝食，可以长生臨宇縣。","头上复戴九星冠，總領玉童坐南面。","欲闻要言今告汝，帝乃焚香請此語。","若能鍊魄去三尸，後當见我天皇所。","顧謂侍女董雙成，酒闌可奏云和笙。","紅霞白日儼不动，七龙五鳳紛相迎。","惜哉志驕神不悅，歎息马蹄與车轍。","複道歌鐘杳將暮，深宮桃李花成雪。","爲看青玉五枝灯，蟠螭吐火光欲絕。"]', '诗', 'shi', '', NULL, '王母歌 李頎 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e464d1b5-c5cf-4d9f-9c0c-98e0c914638a', '鮫人歌', '鮫人歌', 'e7091833-f8c1-44a0-ae16-cf52c39c60f1', '唐', '["鮫人潛織水底居，側身上下隨遊魚。","輕綃文綵不可識，夜夜澄波連月色。","有時寄宿來城市，海島青冥無極已。","泣珠報恩君莫辭，今年相見明年期。","始知萬族無不有，百尺深泉架戶牖。","鳥沒空山誰復望，一望雲濤堪白首。"]', '["鮫人潛织水底居，側身上下隨游鱼。","轻綃文綵不可識，夜夜澄波連月色。","有时寄宿来城市，海島青冥無極已。","泣珠報恩君莫辞，今年相见明年期。","始知万族無不有，百尺深泉架戶牖。","鸟沒空山誰复望，一望云濤堪白首。"]', '诗', 'shi', '', NULL, '鮫人歌 李頎 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('fbba1d53-59a3-437f-946d-fdf3a5e846d5', '夏宴張兵曹東堂', '夏宴張兵曹东堂', 'e7091833-f8c1-44a0-ae16-cf52c39c60f1', '唐', '["重林華屋堪避暑，況乃烹鮮會佳客。","主人三十朝大夫，滿座森然見矛戟。","北窓臥簟連心花，竹裏蟬鳴西日斜。","羽扇搖風却珠汗，玉盆貯水割甘瓜。","雲峰峨峨自冰雪，坐對芳樽不知熱。","醉來但挂葛巾眠，莫道明朝有離別。"]', '["重林华屋堪避暑，況乃烹鲜會佳客。","主人三十朝大夫，满座森然见矛戟。","北窓臥簟連心花，竹裏蟬鳴西日斜。","羽扇搖风却珠汗，玉盆貯水割甘瓜。","云峰峨峨自冰雪，坐对芳樽不知熱。","醉来但挂葛巾眠，莫道明朝有離別。"]', '诗', 'shi', '', NULL, '夏宴張兵曹東堂 李頎 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b6935798-aee3-4f7c-896e-916a1f15357d', '同張員外諲詶荅之作', '同張員外諲詶荅之作', 'e7091833-f8c1-44a0-ae16-cf52c39c60f1', '唐', '["洛中高士日沈冥，手自灌園方帶經。","王湛牀頭見周易，長康傳裏好丹青。","鶡冠葛屨無名位，博[弈]賦詩聊遣意。","清言只到衞家兒，用筆能誇鍾太尉。","東籬二月種蘭蓀，窮巷人稀鳥雀喧。","聞道郎官問生事，肯令鬢髮老柴門。"]', '["洛中高士日沈冥，手自灌园方带經。","王湛牀头见周易，长康傳裏好丹青。","鶡冠葛屨無名位，博[弈]賦诗聊遣意。","清言只到衞家兒，用笔能誇鍾太尉。","东籬二月種蘭蓀，窮巷人稀鸟雀喧。","闻道郎官问生事，肯令鬢髮老柴门。"]', '诗', 'shi', '', NULL, '同張員外諲詶荅之作 李頎 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('74d2df66-8cd6-4b4e-9a07-cafda38b5182', '欲之新鄉荅崔顥綦毋潛', '欲之新乡荅崔顥綦毋潛', 'e7091833-f8c1-44a0-ae16-cf52c39c60f1', '唐', '["數年作吏家屢空，誰道黑頭成老翁。","男兒在世無產業，行子出門如轉蓬。","吾屬交歡此何夕，南家擣衣動歸客。","銅鑪將炙相歡飲，星宿縱橫露華白。","寒風卷葉度滹沱，飛雪布地悲峨峨。","孤城日落見棲鳥，馬上時聞漁者歌。","明朝東路把君手，臘日辭君期歲首。","自知寂寞無去思，敢望縣人致牛酒。"]', '["數年作吏家屢空，誰道黑头成老翁。","男兒在世無產業，行子出门如轉蓬。","吾屬交歡此何夕，南家擣衣动归客。","銅鑪將炙相歡饮，星宿縱橫露华白。","寒风卷葉度滹沱，飞雪布地悲峨峨。","孤城日落见棲鸟，马上时闻漁者歌。","明朝东路把君手，臘日辞君期歲首。","自知寂寞無去思，敢望縣人致牛酒。"]', '诗', 'shi', '', NULL, '欲之新鄉荅崔顥綦毋潛 李頎 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7501fdb6-d229-4121-8914-1002ed2d50cb', '荅高三十五留別便呈于十一', '荅高三十五留別便呈于十一', 'e7091833-f8c1-44a0-ae16-cf52c39c60f1', '唐', '["累薦賢良皆不就，家近陳留訪耆舊。","韓康雖復在人間，王霸終思隱巖竇。","清冷池水灌園蔬，萬物滄江心澹如。","妻子歡同五株柳，雲山老對一牀書。","昨日公車見三事，明君賜衣遣爲吏。","懷章不使郡邸驚，待詔初從闕庭至。","散誕由來自不羈，低頭授職爾何爲。","故園壁挂烏紗帽，官舍塵生白接䍦。","寄書寂寂於陵子，蓬蒿沒身胡不仕。","藜羹被褐環堵中，歲晚將貽故人恥。"]', '["累薦賢良皆不就，家近陳留訪耆旧。","韓康雖复在人间，王霸終思隐巖竇。","清冷池水灌园蔬，万物滄江心澹如。","妻子歡同五株柳，云山老对一牀书。","昨日公车见三事，明君賜衣遣爲吏。","懷章不使郡邸驚，待詔初從闕庭至。","散誕由来自不羈，低头授職爾何爲。","故园壁挂烏紗帽，官舍塵生白接䍦。","寄书寂寂於陵子，蓬蒿沒身胡不仕。","藜羹被褐环堵中，歲晚將貽故人恥。"]', '诗', 'shi', '', NULL, '荅高三十五留別便呈于十一 李頎 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('afdb6bb1-f626-4f2c-9ee7-b367f304cbeb', '送康洽入京進樂府歌', '送康洽入京進乐府歌', 'e7091833-f8c1-44a0-ae16-cf52c39c60f1', '唐', '["識子十年何不遇，只愛歡遊兩京路。","朝吟左氏嬌女篇，夜誦相如美人賦。","長安春物舊相宜，小苑蒲萄花滿枝。","柳色偏濃九華殿，鶯聲醉殺五陵兒。","曳裾此日從何所，中貴由來盡相許。","白裌春衫仙吏贈，烏皮隱几臺郎與。","新詩樂府唱堪愁，御妓應傳鳷鵲樓。","西上雖因長公主，終須一見曲陵侯。"]', '["識子十年何不遇，只愛歡游兩京路。","朝吟左氏嬌女篇，夜誦相如美人賦。","长安春物旧相宜，小苑蒲萄花满枝。","柳色偏濃九华殿，鶯声醉殺五陵兒。","曳裾此日從何所，中貴由来尽相許。","白裌春衫仙吏贈，烏皮隐几台郎與。","新诗乐府唱堪愁，御妓應傳鳷鵲楼。","西上雖因长公主，終須一见曲陵侯。"]', '诗', 'shi', '', NULL, '送康洽入京進樂府歌 李頎 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('11847814-ef85-40fa-971c-1dfb87957696', '送劉十', '送劉十', 'e7091833-f8c1-44a0-ae16-cf52c39c60f1', '唐', '["三十不官亦不娶，時人焉識道高下。","房中唯有老氏經，櫪上空餘少遊馬。","往來嵩華與函秦，放歌一曲前山春。","西林獨鶴引閑步，南澗飛泉清角巾。","前年上書不得意，歸臥東窓兀然醉。","諸兄相繼掌青史，第五之名齊驃騎。","烹葵摘果告我行，落日夏雲縱復橫。","聞道謝安掩口笑，知君不免爲蒼生。"]', '["三十不官亦不娶，时人焉識道高下。","房中唯有老氏經，櫪上空餘少游马。","往来嵩华與函秦，放歌一曲前山春。","西林独鹤引闲步，南澗飞泉清角巾。","前年上书不得意，归臥东窓兀然醉。","諸兄相繼掌青史，第五之名齊驃騎。","烹葵摘果告我行，落日夏云縱复橫。","闻道謝安掩口笑，知君不免爲蒼生。"]', '诗', 'shi', '', NULL, '送劉十 李頎 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b7f92ab3-747f-4a3e-a4c2-3c228fecd9f6', '送王道士還山', '送王道士還山', 'e7091833-f8c1-44a0-ae16-cf52c39c60f1', '唐', '["嵩陽道士餐柏實，居處三花對石室。","心窮伏火陽精丹，口誦淮王萬畢術。","自言神訣不可求，我師聞之玄圃遊。","出入彤庭佩金印，承恩赫赫如王侯。","雙峰樹下曾受業，應傳肘後長生法。","吾聞仙地多後身，安知不是具茨人。","玉膏清泠瀑泉水，白雲谿中日方此。","後今不見數十年，鬢髮顏容只如是。","先生捨我欲何歸，竹杖黃裳登翠微。","當有巖前白蝙蝠，迎君日暮雙來飛。"]', '["嵩陽道士餐柏實，居处三花对石室。","心窮伏火陽精丹，口誦淮王万畢術。","自言神訣不可求，我師闻之玄圃游。","出入彤庭佩金印，承恩赫赫如王侯。","雙峰樹下曾受業，應傳肘後长生法。","吾闻仙地多後身，安知不是具茨人。","玉膏清泠瀑泉水，白云谿中日方此。","後今不见數十年，鬢髮顏容只如是。","先生捨我欲何归，竹杖黄裳登翠微。","當有巖前白蝙蝠，迎君日暮雙来飞。"]', '诗', 'shi', '', NULL, '送王道士還山 李頎 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('109f25f7-3fa6-4290-ae88-1f5b88f7af81', '別梁鍠', '別梁鍠', 'e7091833-f8c1-44a0-ae16-cf52c39c60f1', '唐', '["梁生倜儻心不羈，途窮氣蓋長安兒。","回頭轉眄似鵰鶚，有志飛鳴人豈知。","雖云四十無祿位，曾與大軍掌書記。","抗辭請刃誅部曲，作色論兵犯二帥。","一言不合龍頟侯，擊劒拂衣從此棄。","朝朝飲酒黃公壚，脫帽露頂爭叫呼。","庭中犢鼻昔嘗挂，懷裏琅玕今在無。","時人見子多落魄，共笑狂歌非遠圖。","忽然遣躍紫騮馬，還是昂藏一丈夫。","洛陽城頭曉霜白，層冰峨峨滿川澤。","但聞行路吟新詩，不歎舉家無擔石。","莫言貧賤長可欺，覆簣成山當有時。","莫言富歸長可託，木槿朝看暮還落。","不見古時塞上翁，倚伏由來任天作。","去去滄波勿復陳，五湖三江愁殺人。"]', '["梁生倜儻心不羈，途窮氣蓋长安兒。","回头轉眄似鵰鶚，有志飞鳴人豈知。","雖云四十無祿位，曾與大軍掌书記。","抗辞請刃誅部曲，作色論兵犯二帥。","一言不合龙頟侯，擊劒拂衣從此棄。","朝朝饮酒黄公壚，脫帽露頂爭叫呼。","庭中犢鼻昔嘗挂，懷裏琅玕今在無。","时人见子多落魄，共笑狂歌非远圖。","忽然遣躍紫騮马，還是昂藏一丈夫。","洛陽城头晓霜白，層冰峨峨满川澤。","但闻行路吟新诗，不歎舉家無擔石。","莫言貧賤长可欺，覆簣成山當有时。","莫言富归长可託，木槿朝看暮還落。","不见古时塞上翁，倚伏由来任天作。","去去滄波勿复陳，五湖三江愁殺人。"]', '诗', 'shi', '', NULL, '別梁鍠 李頎 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5c200457-70f8-485e-9538-0051ec211079', '送從弟遊江淮兼謁鄱陽劉太守', '送從弟游江淮兼謁鄱陽劉太守', 'e7091833-f8c1-44a0-ae16-cf52c39c60f1', '唐', '["都門柳色朝朝新，念爾今爲江上人。","穆陵關帶清風遠，彭蠡湖連芳草春。","泊舟借問西林寺，曉聽猿聲在山翠。","潯陽北望鴻鴈回，湓水東流客心醉。","須知聖代舉賢良，不使遺才滯一方。","應見鄱陽虎符守，思歸共指白雲鄉。"]', '["都门柳色朝朝新，念爾今爲江上人。","穆陵关带清风远，彭蠡湖連芳草春。","泊舟借问西林寺，晓听猿声在山翠。","潯陽北望鴻鴈回，湓水东流客心醉。","須知聖代舉賢良，不使遺才滯一方。","應见鄱陽虎符守，思归共指白云乡。"]', '诗', 'shi', '', NULL, '送從弟遊江淮兼謁鄱陽劉太守 李頎 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d39d3ffe-b532-4962-8b21-c570e0f54093', '雙笋歌送李回兼呈劉四', '雙笋歌送李回兼呈劉四', 'e7091833-f8c1-44a0-ae16-cf52c39c60f1', '唐', '["並抽新笋色漸綠，迥出空林雙碧玉。","春風解籜雨潤根，一枝半葉清露痕。","爲君當面拂雲日，孤生四遠何足論。","再三抱此悵爲別，嵩洛故人與之說。"]', '["並抽新笋色漸綠，迥出空林雙碧玉。","春风解籜雨潤根，一枝半葉清露痕。","爲君當面拂云日，孤生四远何足論。","再三抱此悵爲別，嵩洛故人與之说。"]', '诗', 'shi', '', NULL, '雙笋歌送李回兼呈劉四 李頎 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d9a38c34-7eb7-46d6-af26-da6f6f68bdf2', '送劉四赴夏縣', '送劉四赴夏縣', 'e7091833-f8c1-44a0-ae16-cf52c39c60f1', '唐', '["九霄特立紅鸞姿，萬仞孤生玉樹枝。","劉侯致身能若此，天骨自然多歎美。","聲名播揚二十年，足下長途幾千里。","舉世皆親丞相閣，我心獨愛伊川水。","脫略勢利猶埃塵，嘯傲時人而已矣。","新詩數歲即文雄，上書昔召蓬萊宮。","明主拜官麒麟閣，光車駿馬看玉童。","高人往來廬山遠，隱士往來張長公。","扶南甘蔗甜如蜜，雜以荔枝龍州橘。","赤縣繁詞滿劇曹，白雲孤峯暉永日。","朝持手板望飛鳥，暮誦楞伽對空室。","一朝出宰汾河間，明府下車人吏閑。","端坐訟庭更無事，開門咫尺巫咸山。","男耕女織蒙惠化，麥熟雉鳴長秋稼。","明年九府議功時，五辟三徵當在茲。","聞道桐鄉有遺老，邑中還欲置生祠。"]', '["九霄特立紅鸾姿，万仞孤生玉樹枝。","劉侯致身能若此，天骨自然多歎美。","声名播揚二十年，足下长途幾千里。","舉世皆親丞相閣，我心独愛伊川水。","脫略勢利猶埃塵，嘯傲时人而已矣。","新诗數歲即文雄，上书昔召蓬萊宮。","明主拜官麒麟閣，光车駿马看玉童。","高人往来廬山远，隐士往来張长公。","扶南甘蔗甜如蜜，杂以荔枝龙州橘。","赤縣繁词满劇曹，白云孤峯暉永日。","朝持手板望飞鸟，暮誦楞伽对空室。","一朝出宰汾河间，明府下车人吏闲。","端坐訟庭更無事，开门咫尺巫咸山。","男耕女织蒙惠化，麦熟雉鳴长秋稼。","明年九府議功时，五辟三徵當在茲。","闻道桐乡有遺老，邑中還欲置生祠。"]', '诗', 'shi', '', NULL, '送劉四赴夏縣 李頎 shi');
